    /** {monotonic(0/1), scoreOfLastPoint} for a "node=score,..." curve; empty -> {1, MIN}. */
    private static int[] curveStats(String curve) {
        int previous = Integer.MIN_VALUE;
        int last = Integer.MIN_VALUE;
        int monotonic = 1;
        if (curve == null || curve.isEmpty()) {
            return new int[]{monotonic, last};
        }
        String[] points = curve.split(",");
        for (String p : points) {
            int eq = p.indexOf('=');
            int value = eq < 0 ? Integer.MIN_VALUE : Integer.parseInt(p.substring(eq + 1));
            if (value < previous) {
                monotonic = 0;
            }
            previous = value;
            last = value;
        }
        return new int[]{monotonic, last};
    }

    /** Score at an exact node threshold in a "node=score,..." curve; MIN_VALUE if not reached. */
    private static int curveScoreAt(String curve, int node) {
        if (curve == null || curve.isEmpty()) {
            return Integer.MIN_VALUE;
        }
        String key = String.valueOf(node) + "=";
        String[] points = curve.split(",");
        for (String p : points) {
            if (p.startsWith(key)) {
                return Integer.parseInt(p.substring(key.length()));
            }
        }
        return Integer.MIN_VALUE;
    }

    public static void autoTest() {
        Log.setRunId(String.valueOf(System.currentTimeMillis()));
        // B112: remember the player's own run saves, so anything the suite writes on exit can be
        // removed instead of being offered as a run on the next launch.
        sts1solver.mirror.SaveGuard.begin();
        try {
            Probe.runSuite();
        }
        catch (Throwable throwable) {
            Log.error("autotest crashed", throwable);
            ++failed;
        }
        Log.info("AUTOTEST RESULT passed=" + passed + " failed=" + failed
                + (Probe.onlyGates != null ? " (only " + Probe.onlyGates + " asked for, "
                        + Probe.skippedSteps + " gate(s) skipped)" : "")
                + (Probe.coreOnly && Probe.onlyGates == null
                        ? " (core gates only, " + Probe.skippedSteps + " extended gate(s) skipped;"
                        + " run tools/run.ps1 -Full for all of them)" : ""));
        // B112: the engine will save the synthetic run when the game closes; remove it here, while
        // the suite still owns the process.
        int swept = sts1solver.mirror.SaveGuard.sweep();
        if (swept > 0) {
            Log.warn("save guard: " + swept + " synthetic run save(s) removed; the player's own saves"
                    + " were left alone");
        }
        Log.info("AUTOTEST DONE");
        try {
            File file = new File(SolverModPaths.request());
            if (file.exists()) {
                file.delete();
            }
        }
        catch (Throwable throwable) {
            // empty catch block
        }
        Runtime.getRuntime().halt(0);
    }

