                    sts1solver.search.Legal.apply(discovery);
                    boolean wrongRefused = !Driver.resolveSelectionByNames("__NotOffered__");
                    boolean stillOpen = Driver.selectionKind() == Driver.SelectionKind.REWARD;
                    String offered = "";
