        Probe.core("S74 a plan for turn 1 is dropped once the player ends the turn by hand", new Runnable(){

            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 23L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Defend_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                PlanCache.clear();
                Gameplay.reset();
                // 1.7.2: since 1.6.3 an unsettled board queues the solve instead of starting it
                // inline. Pump real frames so startQueuedSolve() consumes the queue, then drive
                // the sliced search -- the same shape as the successful second call below.
                Gameplay.startQuickSolve();
                long deadline = System.currentTimeMillis() + 60000L;
                int slicesFirst = 0;
                while (!Gameplay.hasPlan() && System.currentTimeMillis() < deadline) {
                    try { AbstractDungeon.actionManager.update(); } catch (Throwable ignored) {}
                    Gameplay.tick();
                    ++slicesFirst;
                    if (Gameplay.currentPlan() != null) {
                        while (!Gameplay.advanceQuickForTest(5L) && System.currentTimeMillis() < deadline) {
                            ++slicesFirst;
                        }
                    }
                }
                Solver.Result first = Gameplay.currentPlan();
                int before = first == null || first.plan.isEmpty() ? -1 : first.plan.get(0).turn;
                Probe.check(Gameplay.hasPlan(), "the fight starts with a plan for the current turn", "");
                Probe.check(!Gameplay.planIsStale(), "a plan computed on the live turn is not stale", "");
                Driver.endTurn();
                Probe.check(Gameplay.planIsStale(),
                        "ending the turn by hand makes the old plan stale", "firstTurn=" + before);
                Probe.check(!Gameplay.executeStep(),
                        "a stale step is refused instead of played on the new turn", "");
                Probe.check(Gameplay.currentPlan() == null, "the stale plan is dropped", "");
                String text = String.join(" | ", Gameplay.lines());
                Probe.check(text.contains("\u8fc7\u671f"), "the panel explains why it refused", text);
                // m17581: the press used to be dropped while the enemy turn was still resolving
                // ("solve refused: engine busy"), so the player pressed again. It is remembered now.
                Gameplay.startQuickSolve();
                int slices = 0;
                long deadline2 = System.currentTimeMillis() + 60000L;
                while (!Gameplay.hasPlan() && System.currentTimeMillis() < deadline2) {
                    try {
                        AbstractDungeon.actionManager.update();
                    } catch (Throwable ignored) {
                        // a half-built action may throw; the next frame tries again
                    }
                    Gameplay.tick();
                    ++slices;
                    if (Gameplay.currentPlan() != null) {
                        while (!Gameplay.advanceQuickForTest(5L)
                                && System.currentTimeMillis() < deadline2) {
                            ++slices;
                        }
                    }
                }
                Solver.Result second = Gameplay.currentPlan();
                int after = second == null || second.plan.isEmpty() ? -1 : second.plan.get(0).turn;
                Log.info("  S74 turns: before=" + before + " after=" + after + " frames=" + slices
                        + " queued=" + Gameplay.solveQueuedForTest());
                Probe.check(Gameplay.hasPlan() && !Gameplay.planIsStale(),
                        "replanning produces a plan for the new turn", "frames=" + slices);
                Probe.check(after >= 2, "the new plan starts on the new turn", "after=" + after);
            }
        });
