        Probe.step("S89 a stuck frame leaves a thread dump behind", new Runnable(){
            @Override
            public void run() {
                // m14296 (B47). The freeze report could only be narrowed to "after this log line",
                // because every suspect runs on the render thread and none of them logs while it runs.
                String state = sts1solver.Gameplay.watchdogState();
                Probe.check(state != null && state.indexOf("inCombat=") >= 0,
                        "the dump carries a one-line state", String.valueOf(state));
                int before = sts1solver.util.Watchdog.dumpCount();
                String path = sts1solver.util.Watchdog.dump(4200L);
                java.io.File file = new java.io.File(path == null ? "" : path);
                String text = "";
                try {
                    text = new String(java.nio.file.Files.readAllBytes(file.toPath()),
                            java.nio.charset.StandardCharsets.UTF_8);
                } catch (Throwable t) {
                    text = "unreadable: " + t;
                }
                Probe.check(file.isFile() && file.length() > 0, "the dump file is written",
                        String.valueOf(path) + " len=" + (file.isFile() ? file.length() : -1));
                Probe.check(text.indexOf("threads :") >= 0 && text.indexOf("    at ") >= 0,
                        "the dump lists every thread stack", "len=" + text.length());
                // B48: one stack cannot tell "our loop" from "the driver went away"; the dump now
                // re-samples the stuck thread and states which of the two it is.
                Probe.check(text.indexOf("sampling: ") >= 0 && text.indexOf("    sample 1: ") >= 0
                                && (text.indexOf("a loop of ours") >= 0 || text.indexOf("the stack moved") >= 0),
                        "the dump says whether the stack is one loop or moving",
                        "len=" + text.length());
                // B54: the freeze question is "our loop, or the outside world?", and the outside
                // world now has numbers: the phase the game was in, the GC counters during the
                // window, the heap, and which stack owned most of the samples.
                Probe.check(text.indexOf("phase   : ") > 0 && text.indexOf("gc      : ") > 0
                                && text.indexOf("gc during the window: +") > 0,
                        "the dump records the game phase and the GC counters", "len=" + text.length());
                Probe.check(text.indexOf("most repeated stack (") > 0 && text.indexOf("samples):") > 0,
                        "the dump names the stack that owned most of the samples",
                        "len=" + text.length());
                Probe.check(text.indexOf("        at ") > 0
                                && text.split("    sample ", -1).length > 10,
                        "each of the samples keeps a full frame list",
                        "samples=" + (text.split("    sample ", -1).length - 1));
                Probe.check(sts1solver.util.Watchdog.dumpCount() == before + 1,
                        "dumps are counted against the per-process cap",
                        "before=" + before + " after=" + sts1solver.util.Watchdog.dumpCount());
                Log.info("S89 dump: path=" + path + " len=" + (file.isFile() ? file.length() : -1)
                        + " dumps=" + sts1solver.util.Watchdog.dumpCount());
                try {
                    file.delete();
                } catch (Throwable ignored) {
                    // a leftover dump is harmless
                }
            }
        });

        Probe.core("S90 the marker layer is off while the solver owns the frame (B48)", new Runnable(){
            @Override
            public void run() {
                // m14700: the plan arrow was drawn while the search was still running. Gameplay.tick()
                // returns early for the whole sliced search, so the mark still names the card played
                // BEFORE it -- and a "click this next" hint is meaningless while the mod is clicking.
                sts1solver.ui.Hud.markStep(0, 0, false);
                sts1solver.ui.Hud.setBusy(false);
                // m21115-2: boxes belong to 自动出牌; this gate is about the busy rule, so it asks for
                // the autopilot flag explicitly instead of borrowing a frame's value.
                sts1solver.ui.Hud.setAutopilotMarkers(true);
                String idle = sts1solver.ui.Hud.markerGate();
                boolean idleDraw = sts1solver.ui.Hud.markersAllowed();
                sts1solver.ui.Hud.setBusy(true);
                String busy = sts1solver.ui.Hud.markerGate();
                boolean busyDraw = sts1solver.ui.Hud.markersAllowed();
                sts1solver.ui.Hud.setBusy(false);
                sts1solver.ui.Hud.markStep(-1, -1, false);
                sts1solver.ui.Hud.setAutopilotMarkers(true);
                Probe.check(idleDraw && !busyDraw,
                        "the marker draws when idle and not while a search or an action owns the frame",
                        "idle[" + idle + "] busy[" + busy + "]");
                // The dot count used to be len/(12*scale) with no ceiling: one corrupt hitbox asked the
                // batch for an unbounded number of sprites and froze the frame.
                // 10000px at scale 0.1 asks for 8333 dots; the gate wants the cap, not a rejection.
                int capped = sts1solver.ui.Hud.lineDots(10000.0f, 0.1f);
                int normal = sts1solver.ui.Hud.lineDots(600.0f, 1.0f);
                int tooLong = sts1solver.ui.Hud.lineDots(50000.0f, 1.0f);
                int badScale = sts1solver.ui.Hud.lineDots(600.0f, 0.0f);
                int nan = sts1solver.ui.Hud.lineDots(Float.NaN, 1.0f);
                Probe.check(capped == sts1solver.ui.Hud.MAX_DOTS && normal > 4 && normal < 60
                                && tooLong < 0 && badScale < 0 && nan < 0,
                        "a line's dot count is bounded and untrusted geometry is never drawn",
                        "capped=" + capped + " normal=" + normal + " tooLong=" + tooLong
                                + " badScale=" + badScale + " nan=" + nan);
                Probe.check(!sts1solver.ui.Hud.boxOk(Float.NaN, 0, 100, 100)
                                && !sts1solver.ui.Hud.boxOk(0, 0, 100000, 100)
                                && !sts1solver.ui.Hud.boxOk(0, 0, 0, 100)
                                && sts1solver.ui.Hud.boxOk(100, 100, 200, 280),
                        "a hitbox that was never laid out is not drawn",
                        "scale=" + com.megacrit.cardcrawl.core.Settings.scale);
                Log.info("S90 markers: idle[" + idle + "] busy[" + busy + "] capped=" + capped
                        + " normal=" + normal + " maxDots=" + sts1solver.ui.Hud.MAX_DOTS);
            }
        });


        Probe.core("S91 P2-14: autoplay waits one beat per action, and pace is a setting",
                new Runnable(){
            @Override
            public void run() {
                // m14889: autoplay executed the whole plan back to back (100-250 ms per step, 1.3 s
                // for a fight). The gate pins the two halves that matter: the delay is a pure clock
                // comparison (so no frame is ever slept) and 0 really means "no wait".
                Probe.check(sts1solver.ui.AutoPace.due(1000L, 1450L) == false
                                && sts1solver.ui.AutoPace.due(1450L, 1450L) == true,
                        "autoplay holds its action until the beat has passed",
                        "early=" + sts1solver.ui.AutoPace.due(1000L, 1450L)
                                + " due=" + sts1solver.ui.AutoPace.due(1450L, 1450L));
                Probe.check(sts1solver.ui.AutoPace.nextAt(1000L, 450) == 1450L
                                && sts1solver.ui.AutoPace.nextAt(1000L, 0) == 1000L,
                        "a zero delay means the next action may run right away",
                        "450=" + sts1solver.ui.AutoPace.nextAt(1000L, 450)
                                + " 0=" + sts1solver.ui.AutoPace.nextAt(1000L, 0));
                Probe.check(sts1solver.ui.AutoPace.clamp(-5) == 0
                                && sts1solver.ui.AutoPace.clamp(99999) == sts1solver.ui.AutoPace.MAX_MS
                                && sts1solver.ui.AutoPace.clamp(450) == 450,
                        "the pace is clamped to a sane range", "");
                int before = sts1solver.ui.AutoPace.delayMs();
                String labelBefore = sts1solver.ui.AutoPace.label();
                int cycled = sts1solver.ui.AutoPace.cycle();
                int afterCycle = sts1solver.ui.AutoPace.delayMs();
                sts1solver.ui.AutoPace.write(before);
                sts1solver.ui.AutoPace.invalidate();
                int back = sts1solver.ui.AutoPace.delayMs();
                Log.info("  S91 pace: before=" + before + " label=" + labelBefore + " cycled=" + cycled
                        + " readBack=" + afterCycle + " restored=" + back
                        + " profiles=" + java.util.Arrays.toString(sts1solver.ui.AutoPace.PROFILE_MS));
                Probe.check(cycled != before && afterCycle == cycled && back == before,
                        "the 节奏 button cycles the pace and the value survives a round trip",
                        "before=" + before + " cycled=" + cycled + " restored=" + back);
            }
        });

