        Probe.core("S275 B197: every BaseMod publish method is either muted in a window or proven unreachable",
                new Runnable(){
            @Override
            public void run() {
                // BaseMod exposes 50 publish* methods. The guard must cover exactly the ones a
                // sandbox window can reach, and the pair (muted, unreachable) must cover the whole
                // set -- so a BaseMod update that adds a dispatch fails here instead of silently
                // widening what a search can set off in other mods. @SpirePatch is CLASS-retained
                // (not visible to reflection at runtime), so the binding itself is checked by the
                // loader: a patch that names a method BaseMod does not have fails the game at load.
                // What the gate can check here is that the classification is total, current, and
                // that every guard is a real class in the list.
                try {
                    int patchClasses = sts1solver.mirror.HookQuiet.class.getDeclaredClasses().length;
                    java.util.Set<String> declared = new java.util.TreeSet<String>();
                    java.lang.reflect.Method[] methods = basemod.BaseMod.class.getDeclaredMethods();
                    for (int i = 0; i < methods.length; i++) {
                        if (java.lang.reflect.Modifier.isStatic(methods[i].getModifiers())
                                && methods[i].getName().startsWith("publish")) {
                            declared.add(methods[i].getName());
                        }
                    }
                    java.util.Set<String> guarded = new java.util.TreeSet<String>();
                    java.util.Collections.addAll(guarded, sts1solver.mirror.HookQuiet.GUARDED);
                    java.util.Set<String> combatGroup = new java.util.TreeSet<String>();
                    java.util.Collections.addAll(combatGroup, sts1solver.mirror.HookQuiet.COMBAT_HOOKS);
                    java.util.Set<String> otherGroup = new java.util.TreeSet<String>();
                    java.util.Collections.addAll(otherGroup, sts1solver.mirror.HookQuiet.OTHER_HOOKS);
                    java.util.Set<String> union = new java.util.TreeSet<String>(combatGroup);
                    union.addAll(otherGroup);
                    java.util.Set<String> groupOverlap = new java.util.TreeSet<String>(combatGroup);
                    groupOverlap.retainAll(otherGroup);
                    java.util.Set<String> unreachable = new java.util.TreeSet<String>();
                    java.util.Collections.addAll(unreachable, sts1solver.mirror.HookQuiet.UNREACHABLE);
                    java.util.Set<String> overlap = new java.util.TreeSet<String>(guarded);
                    overlap.retainAll(unreachable);
                    java.util.Set<String> unclassified = new java.util.TreeSet<String>(declared);
                    unclassified.removeAll(guarded);
                    unclassified.removeAll(unreachable);
                    java.util.Set<String> unknown = new java.util.TreeSet<String>(guarded);
                    unknown.addAll(unreachable);
                    unknown.removeAll(declared);
                    Log.info("  S275 publish=" + declared.size() + " guarded=" + guarded.size()
                            + " combat=" + combatGroup.size() + " other=" + otherGroup.size()
                            + " unreachable=" + unreachable.size() + " unclassified="
                            + unclassified + " unknown=" + unknown
                            + " patchClasses=" + patchClasses);
                    Probe.check(patchClasses == guarded.size(),
                            "one patch class per guarded publish method",
                            "classes=" + patchClasses + " listed=" + guarded.size());
                    Probe.check(combatGroup.size() == sts1solver.mirror.HookQuiet.COMBAT_METHODS
                                    && otherGroup.size() == sts1solver.mirror.HookQuiet.OTHER_METHODS,
                            "the two groups hold 15 and 6 methods",
                            "combat=" + combatGroup.size() + " other=" + otherGroup.size());
                    Probe.check(groupOverlap.isEmpty() && union.equals(guarded),
                            "the two groups partition the guarded list",
                            "overlap=" + groupOverlap + " union=" + union.size());
                    Probe.check(overlap.isEmpty(),
                            "no method is listed as both muted and unreachable",
                            String.valueOf(overlap));
                    Probe.check(unknown.isEmpty(),
                            "no listed method has disappeared from BaseMod",
                            String.valueOf(unknown));
                    Probe.check(unclassified.isEmpty(),
                            "no BaseMod publish method is left unclassified",
                            String.valueOf(unclassified));
                    Probe.check(sts1solver.mirror.HookQuiet.GUARDED_METHODS == guarded.size(),
                            "the pinned count equals the audited set", "");
                } catch (Throwable t) {
                    Probe.check(false, "S275 ran without throwing", String.valueOf(t));
                }
            }
        });

        Probe.core("S276 B199: the kill preference reads the node's own board, not the live fight",
                new Runnable(){
            @Override
            public void run() {
                // B199 (user 2026-11-19): with 局外: 计 on, the panel handed out "end turn ... end
                // turn" until the thief ran, while a 20 HP Looter was killable. B195's per-node
                // penalty called looterStanding() AFTER expand() uninstalled the child, so EVERY
                // node read the LIVE fight -- which still holds the thief for the whole search.
                // Kill and flee were penalised the same and the cheaper (no hits taken) flee line
                // won. The fact now travels with the node: readChoice stores it, both node scores
                // pass it. This gate pins the flag, the live read it replaced, and the wiring.
                sts1solver.search.GrowthBook.overrideCountingForTest(Boolean.TRUE);
                try {
                    int left = Solver.scoreNodeForTest(0, 0, true, false, 0, 20, 0, 0, 0, 0, true);
                    int clear = Solver.scoreNodeForTest(0, 0, true, false, 0, 20, 0, 0, 0, 0, false);
                    sts1solver.search.GrowthBook.overrideCountingForTest(Boolean.FALSE);
                    int leftOff = Solver.scoreNodeForTest(0, 0, true, false, 0, 20, 0, 0, 0, 0, true);
                    int clearOff = Solver.scoreNodeForTest(0, 0, true, false, 0, 20, 0, 0, 0, 0, false);
                    sts1solver.search.GrowthBook.overrideCountingForTest(Boolean.TRUE);
                    Log.info("  S276 score: left=" + left + " clear=" + clear
                            + " diff=" + (clear - left) + " leftOff=" + leftOff
                            + " clearOff=" + clearOff);
                    Probe.check(clear - left == Solver.KILL_FIRST_POINTS,
                            "a thief left in the node costs exactly KILL_FIRST_POINTS",
                            "diff=" + (clear - left));
                    Probe.check(leftOff == clearOff,
                            "with 局外: 不计 the flag costs nothing",
                            "left=" + leftOff + " clear=" + clearOff);

                    Synthetic.Spec looterSpec = new Synthetic.Spec();
                    looterSpec.seed = 9267L;
                    looterSpec.maxHealth = 80;
                    looterSpec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R",
                            "Defend_R", "Bash"};
                    looterSpec.monsters = new String[]{
                            "com.megacrit.cardcrawl.monsters.exordium.Looter"};
                    Synthetic.build(looterSpec, new Synthetic.SyntheticStep());
                    boolean liveLooter = Solver.looterStandingForTest();
                    int liveScore = Solver.scoreOf(0, 0, true, false, 0, 20, 0, 0, 0);
                    Log.info("  S276 live: looter=" + liveLooter + " liveScore=" + liveScore
                            + " left=" + left);
                    Probe.check(liveLooter, "the live fight still holds the thief", "");
                    Probe.check(liveScore == left,
                            "the live read penalises every node with monster HP left, kill or flee"
                                    + " alike -- the old behaviour this fix replaced",
                            "live=" + liveScore + " left=" + left);

                    // Put the thief on 3 HP, then let the node itself answer: a Strike kills it in
                    // the child, an end turn leaves it standing. The live fight must not move.
                    com.megacrit.cardcrawl.monsters.AbstractMonster thief =
                            AbstractDungeon.getMonsters().monsters.get(0);
                    thief.currentHealth = 3;
                    World root = World.captureLive();
                    sts1solver.search.Action strike = null;
                    java.util.List<sts1solver.search.Action> acts =
                            sts1solver.search.Legal.actions();
                    for (int i = 0; i < acts.size(); i++) {
                        sts1solver.search.Action a = acts.get(i);
                        if (a.isCard() && a.cardId != null && a.cardId.startsWith("Strike")) {
                            strike = a;
                            break;
                        }
                    }
                    String kill = strike == null ? "no-strike"
                            : Solver.choiceLooterForTest(root, strike);
                    String flee = Solver.choiceLooterForTest(root,
                            sts1solver.search.Action.endTurn());
                    boolean liveAfter = Solver.looterStandingForTest();
                    Log.info("  S276 node: strike=" + (strike == null ? "-" : strike.label)
                            + " kill=" + kill + " flee=" + flee + " liveAfter=" + liveAfter);
                    Probe.check(strike != null, "the fixture offers a Strike", "");
                    Probe.check("clear".equals(kill),
                            "the node that kills the thief carries no thief", "kill=" + kill);
                    Probe.check("left".equals(flee),
                            "the node that just ends the turn still carries the thief",
                            "flee=" + flee);
                    Probe.check(liveAfter,
                            "the node reads never disturbed the live fight (its thief is still"
                                    + " there)", "");
                } finally {
                    sts1solver.search.GrowthBook.overrideCountingForTest(null);
                    try { World.forceRestore(); } catch (Throwable t) { }
                    try { Driver.end(); } catch (Throwable t) { }
                    Gameplay.clearPendingForTest();
                    Gameplay.reset();
                }

                // B199: the rule is the thief family, not one room. The user's fight had an Act-2
                // Mugger next to the Looter; it carries the same smoke bomb, EscapeAction and
                // stolenGold, so it must count as a fleeing thief too.
                try {
                    Synthetic.Spec mugger = new Synthetic.Spec();
                    mugger.seed = 9268L;
                    mugger.maxHealth = 80;
                    mugger.deck = new String[]{"Strike_R", "Strike_R", "Defend_R",
                            "Defend_R", "Bash"};
                    mugger.monsters = new String[]{
                            "com.megacrit.cardcrawl.monsters.city.Mugger"};
                    Synthetic.build(mugger, new Synthetic.SyntheticStep());
                    boolean muggerBoard = Solver.looterStandingForTest();
                    Log.info("  S276 mugger: standing=" + muggerBoard);
                    Probe.check(muggerBoard,
                            "an Act-2 Mugger counts as the fleeing thief", "");
                } catch (Throwable t) {
                    Probe.check(false, "the Mugger board was built", String.valueOf(t));
                } finally {
                    try { World.forceRestore(); } catch (Throwable t) { }
                    try { Driver.end(); } catch (Throwable t) { }
                    Gameplay.clearPendingForTest();
                    Gameplay.reset();
                }
            }
        });

        Probe.core("S277 a failed legal-action scan stops the search instead of expanding a partial list",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9271L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                try {
                    java.lang.reflect.Field seam = sts1solver.search.Legal.class
                            .getDeclaredField("failNextScanForTest");
                    seam.setAccessible(true);
                    // Baseline: a normal fight enumerates completely and both entry points agree.
                    sts1solver.search.ActionGenerationResult base =
                            sts1solver.search.Legal.actionsResult();
                    java.util.List<sts1solver.search.Action> viaActions =
                            sts1solver.search.Legal.actions();
                    Probe.check(base.complete(), "baseline enumeration is complete", "");
                    Probe.check(viaActions.size() == base.actions.size() && viaActions.size() > 0,
                            "actions() and actionsResult().actions agree on candidate count",
                            "actions=" + viaActions.size() + " result=" + base.actions.size());
                    // Inject: arm the seam, hit the real catch, assert the incomplete contract.
                    seam.setBoolean(null, true);
                    sts1solver.search.ActionGenerationResult failed =
                            sts1solver.search.Legal.actionsResult();
                    Probe.check(!failed.complete(), "the injected scan reports incomplete", "");
                    Probe.check(failed.failure.startsWith("Legal action enumeration failed:")
                                    && failed.failure.contains("IllegalStateException")
                                    && failed.failure.contains("S277"),
                            "failure names the enum failure, the exception type and the seam",
                            failed.failure);
                    // One-shot: the next scan is complete again without touching the seam.
                    sts1solver.search.ActionGenerationResult after =
                            sts1solver.search.Legal.actionsResult();
                    Probe.check(after.complete() && !after.actions.isEmpty(),
                            "the seam fires once; the next scan has candidates again",
                            "count=" + after.actions.size());
                    // Search side: candidates() must refuse an incomplete set, not expand it.
                    World.forceRestore();
                    World world = World.captureLive();
                    seam.setBoolean(null, true);
                    java.lang.reflect.Method candidates = sts1solver.search.Solver.class
                            .getDeclaredMethod("candidates", World.class);
                    candidates.setAccessible(true);
                    try {
                        candidates.invoke(null, world);
                        Probe.check(false, "candidates refuses an incomplete action set",
                                "no exception was thrown");
                    } catch (java.lang.reflect.InvocationTargetException ite) {
                        Throwable cause = ite.getCause();
                        Probe.check(cause instanceof IllegalStateException
                                        && cause.getMessage() != null
                                        && cause.getMessage().startsWith("Incomplete legal action set:"),
                                "candidates throws Incomplete legal action set",
                                cause == null ? "null" : cause.getMessage());
                    }
                    Probe.check(!seam.getBoolean(null), "the seam is consumed by candidates", "");
                } catch (Throwable t) {
                    Probe.check(false, "S277 ran without throwing", String.valueOf(t));
                } finally {
                    try { World.forceRestore(); } catch (Throwable t) { }
                    try { Driver.end(); } catch (Throwable t) { }
                    Gameplay.clearPendingForTest();
                    Gameplay.reset();
                }
            }
        });

        Probe.core("S278 StateKey equality requires the full canonical string, not just the hash",
                new Runnable(){
            @Override
            public void run() {
                try {
                    sts1solver.search.StateKey a = sts1solver.search.StateKey.of("same");
                    sts1solver.search.StateKey b = sts1solver.search.StateKey.of("same");
                    Probe.check(a.equals(b), "of(same) equals of(same)", "");
                    Probe.check(a.hashCode() == b.hashCode(), "equal keys share a hashCode", "");
                    Probe.check(!a.equals(sts1solver.search.StateKey.of("b")),
                            "of(a) does not equal of(b)", "");
                    // Same hash components, different canonical string: must still be unequal.
                    java.lang.reflect.Constructor<sts1solver.search.StateKey> ctor =
                            sts1solver.search.StateKey.class.getDeclaredConstructor(
                                    long.class, long.class, String.class);
                    ctor.setAccessible(true);
                    sts1solver.search.StateKey x = ctor.newInstance(11L, 22L, "alpha");
                    sts1solver.search.StateKey y = ctor.newInstance(11L, 22L, "beta");
                    Probe.check(x.hi == y.hi && x.lo == y.lo,
                            "the two keys share hi/lo (hash components)", "");
                    Probe.check(!x.equals(y),
                            "equal hi/lo with different canonical strings are NOT equal", "");
                } catch (Throwable t) {
                    Probe.check(false, "S278 ran without throwing", String.valueOf(t));
                }
            }
        });

