        Probe.core("S104 B59: a search always hands the frame delta back (no animation speed-up)",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 1041L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Gameplay.reset();
                // Earlier gates may leave a sandbox window open on purpose; start this one clean so
                // the numbers below are about the solve and nothing else.
                if (sts1solver.drive.Driver.isInstalled()) {
                    sts1solver.drive.Driver.verifyReleased("the start of S104");
                }
                sts1solver.drive.Driver.resetLeakCount();
                int depthBefore = sts1solver.drive.Driver.borrowDepth();
                Gameplay.solveLive();
                String state = sts1solver.drive.Driver.gfxState();
                int leaksBefore = sts1solver.drive.Driver.frameDeltaLeaks();
                int depthAfter = sts1solver.drive.Driver.borrowDepth();
                Log.info("  S104 after a search: " + state + " depth " + depthBefore + " -> "
                        + depthAfter + " leaks=" + leaksBefore);
                Probe.check(!sts1solver.drive.Driver.isInstalled() && depthAfter == depthBefore,
                        "the real frame delta is back after a solve", "depth " + depthBefore + " -> "
                                + depthAfter + " " + state);
                Probe.check(leaksBefore == 0,
                        "no frame had to take the frame delta back", "leaks=" + leaksBefore);
                Probe.check(sts1solver.drive.Driver.verifyReleased("a gate"),
                        "nothing had to be taken back", state);
                // And the check itself has to be able to see a leak: borrow the delta by hand.
                sts1solver.drive.Driver.begin();
                boolean leaked = sts1solver.drive.Driver.isInstalled();
                boolean healed = sts1solver.drive.Driver.verifyReleased("the gate, on purpose");
                Log.info("  S104 deliberate leak: borrowed=" + leaked + " healed=" + healed
                        + " leaks=" + sts1solver.drive.Driver.frameDeltaLeaks());
                Probe.check(leaked && !healed && !sts1solver.drive.Driver.isInstalled(),
                        "a borrowed frame delta is detected and given back",
                        "leaked=" + leaked + " healed=" + healed + " "
                                + sts1solver.drive.Driver.gfxState());
            }
        });

        Probe.step("S105 B59: a static colour written by the search is named and put back mid-slice",
                new Runnable(){
            @Override
            public void run() {
                java.util.List<java.lang.reflect.Field> fields =
                        sts1solver.mirror.RenderState.staticColorTargets();
                Probe.check(fields.size() > 0, "there are static colours to watch",
                        String.valueOf(fields.size()));
                sts1solver.mirror.RenderState.StaticColors sc =
                        sts1solver.mirror.RenderState.captureStaticColorsOnly();
                Probe.check(sts1solver.mirror.RenderState.diffStatics(sc).isEmpty(),
                        "a fresh snapshot has no differences", "n/a");
                Object before = null;
                String name = null;
                for (int i = 0; i < fields.size(); i++) {
                    try {
                        Object v = fields.get(i).get(null);
                        if (v instanceof com.badlogic.gdx.graphics.Color) {
                            before = v;
                            name = fields.get(i).getDeclaringClass().getSimpleName() + "."
                                    + fields.get(i).getName();
                            break;
                        }
                    } catch (Throwable ignored) {
                        // skip unreadable fields
                    }
                }
                if (before == null) {
                    Probe.check(false, "a static colour could be read", "none readable");
                    return;
                }
                com.badlogic.gdx.graphics.Color c = (com.badlogic.gdx.graphics.Color) before;
                float saved = c.r;
                c.r = saved + 0.25f;
                java.util.List<String> diffs = sts1solver.mirror.RenderState.diffStatics(sc);
                int fixed = sts1solver.mirror.RenderState.repairStatics(sc);
                Log.info("  S105 colour: " + name + " diffs=" + diffs.size() + " fixed=" + fixed
                        + " restored=" + (c.r == saved) + " first=" + (diffs.isEmpty() ? "-" : diffs.get(0)));
                Probe.check(diffs.size() == 1 && fixed == 1 && c.r == saved,
                        "one changed static colour is named and restored",
                        "diffs=" + diffs.size() + " fixed=" + fixed + " restored=" + (c.r == saved));
                Probe.check(sts1solver.mirror.RenderState.diffStatics(sc).isEmpty(),
                        "the repair leaves nothing behind", "n/a");
            }
        });

