        Probe.core("S108 B59: the heap guard latches instead of flipping, and the parked pass has a ceiling",
                new Runnable(){
            @Override
            public void run() {
                long savedLimit = sts1solver.search.Solver.heapLimitMb;
                long savedPhase = sts1solver.search.Solver.deferredPhaseMs;
                try {
                    long used = sts1solver.search.Solver.heapUsedMb();
                    sts1solver.search.Solver.resetGuards();
                    sts1solver.search.Solver.heapLimitMb = 1L;
                    int wide = sts1solver.search.Solver.effectiveBeam(128);
                    // The collector frees gigabytes between layers, so the guard must not flip back
                    // the moment "used <= limit" is true again: only a comfortable drop releases it.
                    sts1solver.search.Solver.heapLimitMb = used;
                    int stillNarrow = sts1solver.search.Solver.effectiveBeam(128);
                    sts1solver.search.Solver.heapLimitMb = used * 2L + 64L;
                    int released = sts1solver.search.Solver.effectiveBeam(128);
                    sts1solver.search.Solver.heapLimitMb = 1L;
                    sts1solver.search.Solver.resetGuards();
                    int narrowed = sts1solver.search.Solver.effectiveBeam(128);
                    Log.info("  S108 guard: used=" + used + "MB wide=" + wide + " stillNarrow="
                            + stillNarrow + " released=" + released + " narrowed=" + narrowed
                            + " latched=" + sts1solver.search.Solver.guardLatched());
                    Probe.check(wide == sts1solver.search.Solver.GUARDED_BEAM
                                    && stillNarrow == sts1solver.search.Solver.GUARDED_BEAM,
                            "once the heap crossed the line the beam stays narrow", wide + " / "
                                    + stillNarrow);
                    // P2-58: every cap is a tier now, so "the beam comes back" means "back up to
                    // what this tier allows", not "back to the number I asked for".
                    int ceiling = Math.min(128, sts1solver.search.Limits.beam());
                    Probe.check(released == ceiling,
                            "a comfortable drop gives the beam back", released + " / cap " + ceiling);
                    Probe.check(narrowed == sts1solver.search.Solver.GUARDED_BEAM,
                            "a search that starts over the line narrows immediately",
                            String.valueOf(narrowed));
                    sts1solver.search.Solver.heapLimitMb = 0L;
                    Probe.check(sts1solver.search.Solver.effectiveBeam(128) == ceiling,
                            "the guard can be turned off", "cap " + ceiling);
                    sts1solver.search.Solver.deferredPhaseMs = 1L;
                    sts1solver.search.Solver.resetGuards();
                    Probe.check(!sts1solver.search.Solver.deferredPhaseExpired(),
                            "the clock only starts with the first parked pass", "n/a");
                    sts1solver.search.Solver.deferredPhaseBegin();
                    Thread.sleep(5L);
                    Probe.check(sts1solver.search.Solver.deferredPhaseExpired(),
                            "the parked pass expires", "n/a");
                    sts1solver.search.Solver.deferredPhaseCap();
                    Probe.check(sts1solver.search.Solver.deferredPhaseCapped(),
                            "the cut is remembered", "n/a");
                } catch (Throwable t) {
                    Probe.check(false, "the guard probes never throw", String.valueOf(t));
                } finally {
                    sts1solver.search.Solver.heapLimitMb = savedLimit;
                    sts1solver.search.Solver.deferredPhaseMs = savedPhase;
                    sts1solver.search.Solver.resetGuards();
                }
            }
        });

        Probe.core("S122 B72: a line the beam dropped on an earlier layer is replayed, not skipped",
                new Runnable(){
            @Override
            public void run() {
                long savedLimit = sts1solver.search.Solver.heapLimitMb;
                try {
                    // 1) the ceiling now follows the real heap instead of a flat 1400MB
                    long maxMb = Runtime.getRuntime().maxMemory() >> 20;
                    sts1solver.search.Solver.heapLimitMb = -1L;
                    long auto = sts1solver.search.Solver.effectiveHeapLimitMb();
                    long want = Math.max(256L, maxMb * sts1solver.search.Solver.HEAP_LIMIT_AUTO_PCT / 100L);
                    Log.info("  S122 heap: max=" + maxMb + "MB auto=" + auto + "MB want=" + want + "MB");
                    Probe.check(auto == want, "an unpinned guard follows the real heap",
                            "auto=" + auto + " want=" + want);
                    sts1solver.search.Solver.heapLimitMb = 1400L;
                    Probe.check(sts1solver.search.Solver.effectiveHeapLimitMb() == 1400L,
                            "a pinned value still wins", String.valueOf(auto));

                    // 2) a fight this deck cannot win: the beam starves, the frontier dies without
                    // overflow, so every parked line sits on an EARLIER layer than the dry one. Under
                    // the old rule those were skipped (kept>0, promoted=0); A/B it with the switch.
                    sts1solver.search.Solver.heapLimitMb = 0L;
                    sts1solver.search.Solver.resetGuards();
                    String off = s122Starved(false);
                    sts1solver.search.Solver.resetGuards();
                    String on = s122Starved(true);
                    Log.info("  S122 replay: off[" + off + "] on[" + on + "]");
                    Probe.check(on.indexOf("finished=true") >= 0,
                            "the starving search still terminates", on);
                    Probe.check(s122Int(off, "earlier=") == 0,
                            "with the switch off nothing from an earlier layer is replayed", off);
                    Probe.check(s122Int(on, "earlier=") > 0,
                            "a line parked on an earlier layer is replayed", on);
                    Probe.check(s122Int(off, "deferred=") > 0,
                            "the beam parks lines in both runs", off);
                    Probe.check(s122Int(on, "steps=") >= s122Int(off, "steps="),
                            "replaying the parked lines never shortens the plan", on + " / " + off);

                    // 3) the panel must not call that search exhausted
                    String noReplay = sts1solver.search.PlanText.winBest(true, 0, 270);
                    String replayed = sts1solver.search.PlanText.winBest(true, 3, 270);
                    String parked = sts1solver.search.PlanText.parkedNote(true, 0, 270);
                    Log.info("  S122 text: noReplay=[" + noReplay + "] replayed=[" + replayed
                            + "] note=[" + parked + "]");
                    Probe.check(noReplay.indexOf("被挤掉") >= 0,
                            "a dry frontier with an un-replayed parking lot says so", noReplay);
                    Probe.check(noReplay.indexOf("已搜完") < 0,
                            "and never claims the routes were exhausted", noReplay);
                    Probe.check(replayed.indexOf("已搜完") >= 0,
                            "a search that did replay its parked lines may say it finished", replayed);
                    Probe.check(parked.indexOf("270") >= 0
                                    && sts1solver.search.PlanText.parkedNote(true, 3, 270).isEmpty(),
                            "the parking tail counts the lines and disappears after a replay", parked);
                } catch (Throwable t) {
                    Probe.check(false, "the replay probes never throw", String.valueOf(t));
                } finally {
                    sts1solver.search.Solver.heapLimitMb = savedLimit;
                    sts1solver.search.Solver.resetGuards();
                }
            }
        });

