        Probe.core("S124 m21115: boxes only while 自动出牌 runs, and a duplicate card plays the usable copy",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9124L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Gameplay.reset();
                com.megacrit.cardcrawl.characters.AbstractPlayer p =
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                java.util.ArrayList hand = p.hand.group;
                hand.clear();
                com.megacrit.cardcrawl.cards.AbstractCard free =
                        new com.megacrit.cardcrawl.cards.red.FiendFire();
                free.setCostForTurn(0);
                com.megacrit.cardcrawl.cards.AbstractCard paid =
                        new com.megacrit.cardcrawl.cards.red.FiendFire();
                hand.add(paid);
                hand.add(free);
                com.megacrit.cardcrawl.ui.panels.EnergyPanel.totalCount = 0;
                sts1solver.search.Action action = sts1solver.search.Action.card(0, 0, 0,
                        paid.name, paid.name, "JawWorm", "Fiend Fire", "sandbox-only-uuid");
                com.megacrit.cardcrawl.cards.AbstractCard chosen = Gameplay.liveCardFor(action);
                boolean pickedFree = chosen == free;
                boolean paidRefused = !sts1solver.drive.Driver.canUse(paid,
                        p, com.megacrit.cardcrawl.dungeons.AbstractDungeon.getMonsters().monsters.get(0));
                String reason = sts1solver.drive.Driver.refusalReason(paid);
                Log.info("  S124 copies: copies=2 pickedFree=" + pickedFree
                        + " paidRefused=" + paidRefused + " cost=" + (chosen == null ? -1 : chosen.costForTurn)
                        + " reason=" + reason);
                Probe.check(pickedFree && paidRefused,
                        "the copy the game would accept is the one that gets played",
                        "pickedFree=" + pickedFree + " paidRefused=" + paidRefused);
                Probe.check(reason != null && reason.contains("cost=2") && reason.contains("energy="),
                        "a refusal names its reason and the numbers behind it", String.valueOf(reason));

                sts1solver.ui.Hud.setBusy(false);
                sts1solver.ui.Hud.markStep(0, 0, false);
                sts1solver.ui.Hud.setAutopilotMarkers(false);
                String gateOff = sts1solver.ui.Hud.markerGate();
                boolean drawOff = sts1solver.ui.Hud.markersAllowed();
                sts1solver.ui.Hud.setAutopilotMarkers(true);
                String gateOn = sts1solver.ui.Hud.markerGate();
                boolean drawOn = sts1solver.ui.Hud.markersAllowed();
                Log.info("  S124 markers: off[" + gateOff + "] on[" + gateOn + "]");
                Probe.check(!drawOff && gateOff.contains("auto=false"),
                        "a plan made by the button paints no boxes", gateOff);
                Probe.check(gateOn.contains("auto=true") && (drawOn || gateOn.contains("off=true")),
                        "autopilot is allowed to paint them again", gateOn);
                sts1solver.ui.Hud.markStep(-1, -1, false);
                sts1solver.ui.Hud.setAutopilotMarkers(true);
            }
        });

