        Probe.core("S82 a pile-picking card really moves the card, and a dead action is caught",
                new Runnable(){
            @Override
            public void run() {
                // m12397 (B43). Headbutt and every other pile-picking card opened the pick screen
                // from an action that was already done: FAST_DELTA=20 pushed the 0.1s window below
                // zero in the same frame, so the card never moved and the screen stayed open. The
                // fix makes every play tick slowly, and this gate proves both halves: the effect
                // happens now, and the detector still sees the old bug when it is forced back.
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 2026L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Strike_R",
                            "Defend_R", "Headbutt"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                } catch (Throwable t) {
                    Probe.check(false, "S82 fixture builds", String.valueOf(t));
                    return;
                }
                String moved = s82Headbutt(false);
                Log.info("  S82 pick: " + moved);
                Probe.check(moved.startsWith("ok") && moved.indexOf("opened=true") >= 0
                        && moved.indexOf("stillOpen=false") >= 0,
                        "a discard pick really opens the picker and closes it", moved);
                Probe.check(moved.indexOf("moved=true") >= 0,
                        "the chosen card really leaves the discard pile for the draw pile", moved);
                String old = s82Headbutt(true);
                Log.info("  S82 old-delta: " + old);
                Probe.check(old.indexOf("moved=false") >= 0,
                        "with the old fast tick forced back the card is NOT moved (the bug)", old);
                Probe.check(!Driver.isAwaitingSelection(), "no pick screen is left open after the gate",
                        String.valueOf(Driver.selectionKind()));
            }
        });

        Probe.step("S85 unlimited is the default, and an unlimited search still stops on its own",
                new Runnable(){
            @Override
            public void run() {
                // m13385 (P2-12): the player asked for "no limit by default, I can wait as long as
                // the worldline counter keeps moving", with the panel still able to pick a number.
                Probe.check(sts1solver.ui.DeepBudget.budgetMs(0L)
                                == sts1solver.ui.DeepBudget.UNLIMITED,
                        "0 seconds means no time limit",
                        String.valueOf(sts1solver.ui.DeepBudget.budgetMs(0L)));
                Probe.check(sts1solver.ui.DeepBudget.budgetMs(300L) == 300000L,
                        "a concrete number still means exactly that many seconds",
                        String.valueOf(sts1solver.ui.DeepBudget.budgetMs(300L)));
                Probe.check(sts1solver.ui.DeepBudget.nodes(0) == 0,
                        "0 nodes means no node cap either",
                        String.valueOf(sts1solver.ui.DeepBudget.nodes(0)));
                // m03871: the labels moved on (the seconds chip says 无限 for "no clock", and a
                // concrete budget is spelled 自动(300s)), so the assertion names the strings the
                // panel actually draws instead of the wording from before 1.0.1.
                Probe.check("无限".equals(sts1solver.ui.Budget.secondsLabel(0))
                        && "不限".equals(sts1solver.ui.Budget.nodesLabel(0))
                        && "自动(300s)".equals(sts1solver.ui.Budget.secondsLabel(300))
                        && "不限".equals(sts1solver.Gameplay.budgetText(
                                sts1solver.ui.DeepBudget.UNLIMITED)),
                        "the panel and the progress line say 不限/无限 instead of a fake number",
                        sts1solver.ui.Budget.secondsLabel(0) + "/" + sts1solver.ui.Budget.nodesLabel(0)
                                + "/" + sts1solver.ui.Budget.secondsLabel(300));
                // The one-slime fixture from S59 is a zero-damage win, so the search proves it is
                // optimal and stops on its own -- with no time budget at all. That is exactly the
                // property the player needs: unlimited must not mean "runs forever".
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 77L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Strike_R",
                            "Strike_R", "Strike_R", "Strike_R", "Strike_R", "Strike_R", "Strike_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.AcidSlime_S"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                } catch (Throwable t) {
                    Probe.check(false, "S85 fixture builds", String.valueOf(t));
                    return;
                }
                long t0 = System.currentTimeMillis();
                Solver.Result unlimited = Solver.solve(sts1solver.mirror.World.captureLive(), 16, 12,
                        sts1solver.ui.DeepBudget.UNLIMITED);
                long ms = System.currentTimeMillis() - t0;
                Log.info("  S85 unlimited: win=" + unlimited.win + " reason=" + unlimited.reason
                        + " proven=" + unlimited.provenOptimal + " nodes=" + unlimited.nodes
                        + " plan=" + unlimited.plan.size() + " ms=" + ms);
                Probe.check(!"time".equals(unlimited.reason),
                        "an unlimited search never stops because the clock ran out", unlimited.reason);
                Probe.check(unlimited.win && unlimited.provenOptimal,
                        "an unlimited search still stops the moment the line is proven optimal",
                        "win=" + unlimited.win + " proven=" + unlimited.provenOptimal);
                Probe.check(!unlimited.plan.isEmpty(), "an unlimited search still reports a line",
                        "plan=" + unlimited.plan.size());
                Probe.check(ms < 60000L, "unlimited does not turn a proven win into a long run",
                        "ms=" + ms);
            }
        });

        // ---------------------------------------------------------------------------------
        // S86: a probe must not be heard, and must not leak a music track. B44 silenced the main
        // track only, but a boss arms its theme through unsilenceBGM + playPrecachedTempBgm, which
        // plays on the TEMP track -- so the boss theme stayed audible, and each build appended a
        // TempMusic that was never removed (a suite had piled up 507 of them).
        // ---------------------------------------------------------------------------------
        // ---------------------------------------------------------------------------------
        // B46: a probe instance must never make a sound. The tools start a SECOND game process;
        // whether the player muted his own game is irrelevant to that process, so it mutes itself
        // and never writes the player's STSSound.
        // ---------------------------------------------------------------------------------
        Probe.step("S87 a probe instance mutes itself and leaves the player's sound settings alone",
                new Runnable(){
            @Override
            public void run() {
                boolean alreadyArmed = sts1solver.util.SilentInstance.isArmed();
                float beforeMusic = com.megacrit.cardcrawl.core.Settings.MUSIC_VOLUME;
                Object prefBefore = com.megacrit.cardcrawl.core.Settings.soundPref.data.get("Music Volume");
                // Pretend the player just raised the sliders, whichever state this process is in.
                com.megacrit.cardcrawl.core.Settings.MUSIC_VOLUME = 0.5f;
                com.megacrit.cardcrawl.core.Settings.SOUND_VOLUME = 0.5f;
                com.megacrit.cardcrawl.core.Settings.MASTER_VOLUME = 0.5f;
                if (!alreadyArmed) {
                    sts1solver.util.SilentInstance.arm("S87");
                } else {
                    sts1solver.util.SilentInstance.tick();
                }
                Probe.check(sts1solver.util.SilentInstance.isArmed(),
                        "the instance is armed", "alreadyArmed=" + alreadyArmed);
                Probe.check(com.megacrit.cardcrawl.core.Settings.MUSIC_VOLUME == 0.0f
                        && com.megacrit.cardcrawl.core.Settings.SOUND_VOLUME == 0.0f
                        && com.megacrit.cardcrawl.core.Settings.MASTER_VOLUME == 0.0f,
                        "music, sound and master volume are all zero",
                        "music=" + com.megacrit.cardcrawl.core.Settings.MUSIC_VOLUME
                                + " sound=" + com.megacrit.cardcrawl.core.Settings.SOUND_VOLUME
                                + " master=" + com.megacrit.cardcrawl.core.Settings.MASTER_VOLUME);
                float saved = sts1solver.util.SilentInstance.savedMusicVolume();
                Probe.check(saved >= 0.0f && (alreadyArmed || saved == beforeMusic),
                        "the volume the player had was recorded before muting",
                        "saved=" + saved + " before=" + beforeMusic + " alreadyArmed=" + alreadyArmed);
                com.megacrit.cardcrawl.core.Settings.MUSIC_VOLUME = 0.7f;
                sts1solver.util.SilentInstance.tick();
                Probe.check(com.megacrit.cardcrawl.core.Settings.MUSIC_VOLUME == 0.0f,
                        "a later write is pulled back to silence",
                        "music=" + com.megacrit.cardcrawl.core.Settings.MUSIC_VOLUME);
                Object prefAfter = com.megacrit.cardcrawl.core.Settings.soundPref.data.get("Music Volume");
                Probe.check(prefBefore == null ? prefAfter == null : prefBefore.equals(prefAfter),
                        "the player's STSSound map is never written",
                        "before=" + prefBefore + " after=" + prefAfter);
                Object master = com.megacrit.cardcrawl.core.CardCrawlGame.music;
                int tracksBefore = sts1solver.mirror.MusicMute.aliveTracks();
                sts1solver.mirror.MusicMute.begin(false);
                com.megacrit.cardcrawl.core.CardCrawlGame.music.playTempBgmInstantly("BOSS_BOTTOM", true);
                com.megacrit.cardcrawl.core.CardCrawlGame.music.unsilenceBGM();
                for (int i = 0; i < 60; i++) {
                    sts1solver.util.SilentInstance.tick();
                }
                int audible = Probe.musicCounts(master)[2];
                sts1solver.mirror.MusicMute.end();
                int tracksAfter = sts1solver.mirror.MusicMute.aliveTracks();
                Log.info("S87 silent: saved=" + saved + " audibleAfterTick=" + audible
                        + " tracks=" + tracksBefore + "/" + tracksAfter);
                Probe.check(audible == 0, "a track armed after boot is silenced within a second",
                        "audible=" + audible);
                Probe.check(tracksAfter == tracksBefore, "the gate leaves no track behind",
                        "before=" + tracksBefore + " after=" + tracksAfter);
            }
        });

        Probe.step("S86 a synthetic boss fight is silent and leaves no music track behind",
                new Runnable(){
            @Override
            public void run() {
                Object master = com.megacrit.cardcrawl.core.CardCrawlGame.music;
                Probe.check(master != null, "the live game really owns a music master", String.valueOf(master));
                if (master == null) {
                    return;
                }
                int tracksBefore = sts1solver.mirror.MusicMute.aliveTracks();
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 4111L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Defend_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.Hexaghost"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                int afterFirst = sts1solver.mirror.MusicMute.aliveTracks();
                int droppedFirst = sts1solver.mirror.MusicMute.lastDropped();
                int[] after = Probe.musicCounts(master);
                Log.info("S86 music: tracksBefore=" + tracksBefore + " afterBuild=" + afterFirst
                        + " dropped=" + droppedFirst + " main=" + after[0] + " temp=" + after[1]
                        + " audible=" + after[2]);
                Probe.check(after[2] == 0, "no music track is audible after the synthetic fight",
                        "audible=" + after[2] + " main=" + after[0] + " temp=" + after[1]);
                Probe.check(afterFirst <= tracksBefore, "the build disposed the tracks it armed",
                        "before=" + tracksBefore + " after=" + afterFirst + " dropped=" + droppedFirst);
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                int afterSecond = sts1solver.mirror.MusicMute.aliveTracks();
                Probe.check(afterSecond == afterFirst, "a second fight does not accumulate music tracks",
                        "first=" + afterFirst + " second=" + afterSecond);
                // This Hexaghost build happens outside a boss room, so it arms nothing; play the boss
                // theme through the engine code the boss itself uses, then prove the window both
                // reaches the mixer and disposes what it created.
                int baseline = sts1solver.mirror.MusicMute.aliveTracks();
                sts1solver.mirror.MusicMute.begin(false);
                com.megacrit.cardcrawl.core.CardCrawlGame.music.playTempBgmInstantly("BOSS_BOTTOM", true);
                int armed = sts1solver.mirror.MusicMute.aliveTracks();
                com.megacrit.cardcrawl.core.CardCrawlGame.music.unsilenceBGM();
                int audibleInWindow = Probe.musicCounts(master)[2];
                sts1solver.mirror.MusicMute.end();
                int disposed = sts1solver.mirror.MusicMute.aliveTracks();
                int audibleAfterWindow = Probe.musicCounts(master)[2];
                Log.info("S86 arm: baseline=" + baseline + " armed=" + armed + " disposed=" + disposed
                        + " audibleInWindow=" + audibleInWindow + " audibleAfter=" + audibleAfterWindow);
                Probe.check(armed > baseline, "the boss theme really reaches the live mixer",
                        "baseline=" + baseline + " armed=" + armed);
                Probe.check(disposed == baseline, "the window disposed the track it created",
                        "baseline=" + baseline + " disposed=" + disposed);
                Probe.check(audibleAfterWindow == 0, "nothing is left audible when the window closes",
                        "audible=" + audibleAfterWindow);

                // The in-game window must put the player's own silence flags back: a simulated boss
                // calls unsilenceBGM() on the real mixer, and the search must undo that.
                int audibleBeforeSearch = Probe.musicCounts(master)[2];
                sts1solver.mirror.MusicMute.begin(true);
                com.megacrit.cardcrawl.core.CardCrawlGame.music.unsilenceBGM();
                sts1solver.mirror.MusicMute.end();
                int audibleAfterSearch = Probe.musicCounts(master)[2];
                Probe.check(audibleAfterSearch == audibleBeforeSearch,
                        "a search puts the player's music back the way it found it",
                        "before=" + audibleBeforeSearch + " after=" + audibleAfterSearch);
            }
        });


        Probe.step("S63 A0: the budget is spent before the search may stop",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 1307L;
                spec.maxHealth = 90;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                sts1solver.search.Solver.Result thin = sts1solver.search.Solver.solve(
                        sts1solver.mirror.World.captureLive(), 10, 96, 500L);
                sts1solver.search.Solver.Result full = sts1solver.search.Solver.solve(
                        sts1solver.mirror.World.captureLive(), 10, 96, 4000L);
                Log.info("  S63 thin: win=" + thin.win + " hpLoss=" + thin.hpLoss
                        + " nodes=" + thin.nodes + " expansions=" + thin.expansions
                        + " proven=" + thin.provenOptimal + " exhausted=" + thin.frontierExhausted
                        + " left=" + thin.frontierLeft + " reason=" + thin.reason);
                Log.info("  S63 full: win=" + full.win + " hpLoss=" + full.hpLoss
                        + " nodes=" + full.nodes + " expansions=" + full.expansions
                        + " proven=" + full.provenOptimal + " exhausted=" + full.frontierExhausted
                        + " left=" + full.frontierLeft + " reason=" + full.reason);
                Probe.check(!thin.win || full.win,
                        "a bigger budget never turns a win into a loss", "");
                Probe.check(full.nodes >= thin.nodes,
                        "the bigger budget really searched more",
                        full.nodes + " vs " + thin.nodes);
                Probe.check(!(thin.win && full.win) || full.hpLoss <= thin.hpLoss,
                        "a bigger budget never finds a worse line",
                        thin.hpLoss + " -> " + full.hpLoss);
                Probe.check(full.frontierExhausted ? full.frontierLeft == 0 : full.frontierLeft >= 0,
                        "the frontier count agrees with the exhausted flag",
                        "exhausted=" + full.frontierExhausted + " left=" + full.frontierLeft);
                Probe.check(full.win || full.frontierExhausted || full.frontierLeft > 0,
                        "a losing search reports why it stopped",
                        "left=" + full.frontierLeft + " reason=" + full.reason);
                String headline = sts1solver.search.PlanText.headline(full);
                Log.info("  S63 headline: " + headline);
                Probe.check(headline.length() > 0,
                        "the panel has a headline for the full-budget result", headline);
                Probe.check(!full.win || headline.indexOf("可赢") >= 0,
                        "a winning result says so in the headline", headline);
                Probe.check(!full.win || !full.provenOptimal || headline.indexOf("已证明最优") >= 0,
                        "a proven (zero-damage) win says it cannot be improved", headline);
                Probe.check(sts1solver.search.PlanText.openCandidates(full)
                                == (full.cutShort ? full.frontierLeft : 0),
                        "only a search that stopped on a limit reports open candidates",
                        "cutShort=" + full.cutShort + " left=" + full.frontierLeft
                                + " deferred=" + full.deferred);
                // A0's real requirement: a win is not a stopping condition. The Cultist hits back,
                // so a winning line exists but can never be "proven optimal" (zero HP lost).
                Synthetic.Spec costly = new Synthetic.Spec();
                costly.seed = 1311L;
                costly.maxHealth = 60;
                costly.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Defend_R", "Defend_R"};
                costly.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.Cultist"};
                Synthetic.build(costly, new Synthetic.SyntheticStep());
                sts1solver.search.Solver.Result costlyResult = sts1solver.search.Solver.solve(
                        sts1solver.mirror.World.captureLive(), 10, 96, 8000L);
                Log.info("  S63 costly: win=" + costlyResult.win + " hpLoss=" + costlyResult.hpLoss
                        + " nodes=" + costlyResult.nodes + " expansions=" + costlyResult.expansions
                        + " proven=" + costlyResult.provenOptimal
                        + " afterWin=" + costlyResult.layersAfterFirstWin
                        + " exhausted=" + costlyResult.frontierExhausted
                        + " left=" + costlyResult.frontierLeft + " reason=" + costlyResult.reason);
                Probe.check(!costlyResult.win || costlyResult.layersAfterFirstWin > 0,
                        "a found win does not end the search (A0)",
                        "win=" + costlyResult.win + " afterWin=" + costlyResult.layersAfterFirstWin
                                + " proven=" + costlyResult.provenOptimal);
            }
        });

