        Probe.step("S67 P2-11b: one search scale on the panel and in the headline, and a heap guard",
                new Runnable(){
            @Override
            public void run() {
                // 1. the guard is a pure function of (beam, heap limit): narrow passes are never
                //    touched, and 0 disables it, so the gate can pin both branches.
                long savedLimit = sts1solver.search.Solver.heapLimitMb;
                try {
                    // P2-58: the beam also has a tier ceiling, so "the guard is off" means "the pass
                    // gets what the tier allows", not "it gets the number I asked for".
                    int ceiling = Math.min(128, sts1solver.search.Limits.beam());
                    sts1solver.search.Solver.heapLimitMb = 0L;
                    Probe.check(sts1solver.search.Solver.effectiveBeam(128) == ceiling,
                            "heapLimitMb=0 disables the guard (opt-out is real)",
                            "beam=" + sts1solver.search.Solver.effectiveBeam(128)
                                    + " cap=" + ceiling);
                    sts1solver.search.Solver.heapLimitMb = 1L;
                    int wide = sts1solver.search.Solver.effectiveBeam(128);
                    int mid = sts1solver.search.Solver.effectiveBeam(64);
                    int narrow = sts1solver.search.Solver.effectiveBeam(32);
                    Log.info("  S67 guard: limit=1mb beam(128)=" + wide + " beam(64)=" + mid
                            + " beam(32)=" + narrow);
                    Probe.check(wide == sts1solver.search.Solver.GUARDED_BEAM
                            && mid == sts1solver.search.Solver.GUARDED_BEAM,
                            "over the heap limit the wide passes narrow to 48",
                            wide + "/" + mid);
                    Probe.check(narrow == 32,
                            "a narrow pass keeps its width under memory pressure",
                            "beam(32)=" + narrow);
                }
                finally {
                    sts1solver.search.Solver.heapLimitMb = savedLimit;
                }

                // 2. totals: a single pass has total == pass, a job that ran several passes reports
                //    the job (never less than the answer it describes).
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 1313L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Defend_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                sts1solver.search.Solver.Result single = sts1solver.search.Solver.solve(
                        sts1solver.mirror.World.captureLive(), 10, 96, 1500L);
                Log.info("  S67 single: nodes=" + single.nodes + "/" + single.totalNodes
                        + " expansions=" + single.expansions + "/" + single.totalExpansions
                        + " passes=" + single.passes);
                Probe.check(single.totalNodes == single.nodes
                                && single.totalExpansions == single.expansions
                                && single.passes == 1,
                        "a single pass reports itself as the whole job",
                        single.totalNodes + "/" + single.nodes);

                sts1solver.search.Solver.PortfolioSession job = new sts1solver.search.Solver.PortfolioSession(
                        sts1solver.mirror.World.captureLive(), 4000L, 0);
                int slices = 0;
                while (!job.advance(40L) && slices < 400) {
                    ++slices;
                }
                sts1solver.search.Solver.Result r = job.result();
                Log.info("  S67 portfolio: passes=" + (r == null ? -1 : r.passes)
                        + " nodes=" + (r == null ? -1 : r.nodes)
                        + "/" + (r == null ? -1 : r.totalNodes)
                        + " expansions=" + (r == null ? -1 : r.expansions)
                        + "/" + (r == null ? -1 : r.totalExpansions) + " slices=" + slices);
                Probe.check(r != null && r.passes >= 1
                                && r.totalNodes >= r.nodes
                                && r.totalExpansions >= r.expansions
                                && (r.passes > 1 || r.totalNodes == r.nodes),
                        "a multi-pass job reports the job-wide numbers",
                        r == null ? "null" : (r.totalNodes + "/" + r.nodes));

                // 3. wording: when the panel counted several passes, the dead-end text names both
                //    scales instead of quoting one number that contradicts the panel.
                String dual = sts1solver.search.PlanText.headline(false, false, "no-live-branches",
                        38, 33, true, 26, 200, 256, 4805);
                Log.info("  S67 dual: " + dual);
                Probe.check(dual.indexOf("本档只搜了 256") >= 0
                                && dual.indexOf("整次搜索共 4805") >= 0
                                && dual.indexOf("不能证明会死") >= 0,
                        "the dead-end wording quotes the pass and the whole job",
                        dual);
                String onlyPass = sts1solver.search.PlanText.headline(false, false, "no-live-branches",
                        38, 33, true, 26, 200, 256);
                Probe.check(onlyPass.indexOf("256") >= 0 && onlyPass.indexOf("整次搜索") < 0,
                        "a caller without totals keeps the single-scale wording",
                        onlyPass);

                // 4. the panel text the player reads uses that same one wording.
                sts1solver.search.QuickSession quick = new sts1solver.search.QuickSession(
                        sts1solver.mirror.World.captureLive(), 2500L, false);
                int steps = 0;
                while (!quick.advance(20L) && steps < 300) {
                    ++steps;
                }
                String text = sts1solver.Gameplay.worldlineText(quick);
                sts1solver.search.Solver.Result qr = quick.result();
                Log.info("  S67 panel: " + text + " | passes=" + (qr == null ? -1 : qr.passes)
                        + " total=" + (qr == null ? -1 : qr.totalNodes));
                Probe.check(text.indexOf("条世界线") >= 0,
                        "the panel still says how many worldlines were reviewed", text);
                Probe.check(qr != null && qr.totalNodes >= qr.nodes,
                        "the quick job's answer carries the job-wide count",
                        qr == null ? "null" : (qr.totalNodes + "/" + qr.nodes));
            }
        });

        Probe.step("S54 the coverage tail answers its real trigger instead of being skipped",
                new Runnable(){
            @Override
            public void run() {
                // Coverage used to report four cards, one potion, one relic and four monsters as
                // unreachable, which read like missing support. Each one is refused by the game itself
                // until its real trigger happens, so the sweep now reproduces the trigger. This gate
                // pins the trigger of every one of them, so a future regression cannot quietly turn
                // "accounted" back into "skipped".
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 5401L;
                spec.maxHealth = 90;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                World w = World.captureLive();
                w.install();
                Driver.begin();
                try {
                    com.megacrit.cardcrawl.monsters.AbstractMonster target =
                            Driver.aliveMonsters().isEmpty() ? null : Driver.aliveMonsters().get(0);
                    com.megacrit.cardcrawl.ui.panels.EnergyPanel.setEnergy(99);
                    // Grand Finale: the game refuses it unless the draw pile is empty.
                    AbstractCard finale = com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Grand Finale");
                    AbstractDungeon.player.hand.group.clear();
                    AbstractDungeon.player.hand.group.add(finale);
                    AbstractDungeon.player.drawPile.group.clear();
                    AbstractDungeon.player.drawPile.group.add(
                            com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Strike_R"));
                    boolean refused = !Driver.canUse(finale, AbstractDungeon.player, target);
                    AbstractDungeon.player.drawPile.group.clear();
                    boolean allowed = Driver.canUse(finale, AbstractDungeon.player, target);
                    Log.info("  S54 Grand Finale: with a full draw pile canUse=" + !refused
                            + " with an empty one canUse=" + allowed);
                    Probe.check(refused, "Grand Finale is refused while the draw pile still has cards", "");
                    Probe.check(allowed, "an empty draw pile is exactly what Grand Finale waits for", "");
                    // Deus Ex Machina: its effect only exists when the card is drawn.
                    AbstractCard deus = com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("DeusExMachina");
                    AbstractDungeon.player.hand.group.clear();
                    AbstractDungeon.player.hand.group.add(deus);
                    int handBeforeDeus = AbstractDungeon.player.hand.size();
                    deus.triggerWhenDrawn();
                    Driver.drain();
                    int handAfterDeus = AbstractDungeon.player.hand.size();
                    Log.info("  S54 DeusExMachina: hand " + handBeforeDeus + "->" + handAfterDeus);
                    Probe.check(handAfterDeus > handBeforeDeus,
                            "Deus Ex Machina makes its cards when it is drawn (not when played)",
                            handBeforeDeus + "->" + handAfterDeus);
                    // Tactician: discarding it refunds energy.
                    AbstractCard tactician =
                            com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Tactician");
                    AbstractDungeon.player.hand.group.clear();
                    AbstractDungeon.player.hand.group.add(tactician);
                    com.megacrit.cardcrawl.ui.panels.EnergyPanel.setEnergy(3);
                    int energyBeforeTactician =
                            com.megacrit.cardcrawl.ui.panels.EnergyPanel.getCurrentEnergy();
                    tactician.triggerOnManualDiscard();
                    Driver.drain();
                    int energyAfterTactician =
                            com.megacrit.cardcrawl.ui.panels.EnergyPanel.getCurrentEnergy();
                    Log.info("  S54 Tactician: energy " + energyBeforeTactician + "->"
                            + energyAfterTactician);
                    Probe.check(energyAfterTactician == energyBeforeTactician + 1,
                            "discarding Tactician refunds one energy (its real effect)",
                            energyBeforeTactician + "->" + energyAfterTactician);
                    // Reflex: discarding it draws cards.
                    AbstractCard reflex = com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Reflex");
                    AbstractDungeon.player.hand.group.clear();
                    AbstractDungeon.player.hand.group.add(reflex);
                    AbstractDungeon.player.drawPile.group.clear();
                    AbstractDungeon.player.drawPile.group.add(
                            com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Strike_R"));
                    int handBeforeReflex = AbstractDungeon.player.hand.size();
                    reflex.triggerOnManualDiscard();
                    Driver.drain();
                    int handAfterReflex = AbstractDungeon.player.hand.size();
                    Log.info("  S54 Reflex: hand " + handBeforeReflex + "->" + handAfterReflex);
                    // The hook is called directly here, so the card has not been removed from the
                    // hand first: the only change is the card Reflex draws.
                    Probe.check(handAfterReflex == handBeforeReflex + 1,
                            "discarding Reflex draws a card into the hand",
                            handBeforeReflex + "->" + handAfterReflex);
                    // Fairy Potion: the game itself says you cannot drink it.
                    com.megacrit.cardcrawl.potions.AbstractPotion fairy =
                            com.megacrit.cardcrawl.helpers.PotionHelper.getPotion("FairyPotion");
                    Probe.check(fairy != null && "FairyPotion".equals(fairy.ID) && !fairy.canUse(),
                            "Fairy Potion reports canUse()==false: it is death-triggered, not unusable",
                            fairy == null ? "null" : fairy.ID + " canUse=" + fairy.canUse());
                    // Deprecated relic: a save-compatibility shell that throws on construction.
                    boolean deprecatedThrew = false;
                    String deprecatedName = "";
                    try {
                        Class<?> dc = Class.forName(
                                "com.megacrit.cardcrawl.relics.deprecated.DEPRECATED_DarkCore");
                        deprecatedName = dc.getSimpleName();
                        dc.getConstructor().newInstance();
                    } catch (java.lang.reflect.InvocationTargetException expected) {
                        deprecatedThrew = true;
                    } catch (Exception other) {
                        // A missing class or an inaccessible constructor is a different failure;
                        // the check below reports it as "did not throw".
                    }
                    Probe.check(deprecatedThrew && deprecatedName.startsWith("DEPRECATED_"),
                            "the deprecated relic is named DEPRECATED_ and throws when built",
                            deprecatedName + " threw=" + deprecatedThrew);
                    // Four monster bodies have no no-arg constructor; the sweep builds them with
                    // neutral arguments instead of calling them unreachable.
                    String[] bodies = new String[]{
                        "com.megacrit.cardcrawl.monsters.city.BronzeOrb",
                        "com.megacrit.cardcrawl.monsters.exordium.AcidSlime_S",
                        "com.megacrit.cardcrawl.monsters.exordium.Lagavulin",
                        "com.megacrit.cardcrawl.monsters.exordium.SpikeSlime_S"};
                    int bodiesBuilt = 0;
                    StringBuilder bodyNotes = new StringBuilder();
                    for (String name : bodies) {
                        try {
                        Class<?> bc = Class.forName(name);
                        boolean noArg;
                        try {
                            bc.getConstructor();
                            noArg = true;
                        } catch (NoSuchMethodException expected) {
                            noArg = false;
                        }
                        com.megacrit.cardcrawl.monsters.AbstractMonster body =
                                sts1solver.coverage.Coverage.instantiate(bc);
                        boolean ok = body != null && !noArg;
                        if (ok) {
                            ++bodiesBuilt;
                        }
                        bodyNotes.append(bc.getSimpleName()).append(noArg ? ":noarg" : ":built")
                                .append(ok ? "+ " : "! ");
                        } catch (Exception other) {
                            bodyNotes.append(name).append(":missing ");
                        }
                    }
                    Log.info("  S54 monster bodies: " + bodyNotes);
                    Probe.check(bodiesBuilt == bodies.length,
                            "the four bodies without a no-arg constructor are still built",
                            bodiesBuilt + "/" + bodies.length + " " + bodyNotes);
                } finally {
                    Driver.end();
                    w.readBack();
                    w.uninstall();
                }
            }
        });

        Probe.step("S55 a route that burns a death save ranks below one that does not",
                new Runnable(){
            @Override
            public void run() {
                // G3 (JUDGMENT.md): STS1 runs Lizard Tail / Fairy in a Bottle inside
                // AbstractPlayer.damage(), so the behaviour was always right -- the player never
                // rests on 0 HP. What was missing is the COST: a route that needed a save should
                // rank below one that did not, before any HP comparison. This gate pins both the
                // arithmetic and the two real observables (relic counter -2, potion bar shrink).
                int clean = sts1solver.search.Solver.scoreOf(0, 0, true, false, 0, 0, 0, 0, 0);
                int oneSave = sts1solver.search.Solver.scoreOf(0, 0, true, false, 0, 0, 0, 0, 1);
                int twoSaves = sts1solver.search.Solver.scoreOf(0, 0, true, false, 0, 0, 0, 0, 2);
                Probe.check(clean - oneSave == sts1solver.search.DeathSaves.POINTS,
                        "one death save costs its stated points",
                        (clean - oneSave) + " vs " + sts1solver.search.DeathSaves.POINTS);
                Probe.check(oneSave - twoSaves == sts1solver.search.DeathSaves.POINTS,
                        "a second death save costs the same again",
                        (oneSave - twoSaves) + " vs " + sts1solver.search.DeathSaves.POINTS);
                int loss = sts1solver.search.Solver.scoreOf(0, 0, false, false, 0, 0, 0, 0, 0);
                Probe.check(oneSave > loss, "a saved victory still beats a loss",
                        oneSave + " vs " + loss);
                int cleanButBloodied = sts1solver.search.Solver.scoreOf(90, 0, true, false, 12, 0, 0, 0, 0);
                int savedButHealthy = sts1solver.search.Solver.scoreOf(0, 0, true, false, 3, 0, 0, 0, 1);
                Probe.check(cleanButBloodied > savedButHealthy,
                        "fewer death saves outranks less HP lost",
                        cleanButBloodied + " vs " + savedButHealthy);
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 5501L;
                spec.maxHealth = 90;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                World w = World.captureLive();
                w.install();
                Driver.begin();
                try {
                    // Ready state: one Fairy in a Bottle in the bar, Lizard Tail unused (-1).
                    int potionSlot = -1;
                    for (int i = 0; i < AbstractDungeon.player.potions.size(); i++) {
                        if (AbstractDungeon.player.potions.get(i) instanceof com.megacrit.cardcrawl.potions.PotionSlot) {
                            potionSlot = i;
                            break;
                        }
                    }
                    com.megacrit.cardcrawl.potions.AbstractPotion fairy =
                            com.megacrit.cardcrawl.helpers.PotionHelper.getPotion("FairyPotion");
                    if (potionSlot >= 0 && fairy != null) {
                        fairy.slot = potionSlot;
                        AbstractDungeon.player.potions.set(potionSlot, fairy);
                    }
                    AbstractDungeon.player.relics.add(new com.megacrit.cardcrawl.relics.LizardTail());
                    int fairies0 = sts1solver.search.DeathSaves.fairiesInBar();
                    boolean tailReady = sts1solver.search.DeathSaves.lizardTailSpent();
                    int saves0 = sts1solver.search.DeathSaves.usedSoFar(fairies0);
                    Log.info("  S55 ready: fairies=" + fairies0 + " tailSpent=" + tailReady
                            + " saves=" + saves0);
                    Probe.check(fairies0 == 1 && !tailReady && saves0 == 0,
                            "an untouched fight has no death saves burned",
                            "fairies=" + fairies0 + " tailSpent=" + tailReady + " saves=" + saves0);
                    // First lethal hit: the game itself spends the Fairy in a Bottle.
                    AbstractDungeon.player.damage(new com.megacrit.cardcrawl.cards.DamageInfo(
                            AbstractDungeon.player, 999,
                            com.megacrit.cardcrawl.cards.DamageInfo.DamageType.HP_LOSS));
                    Driver.drain();
                    int fairiesAfter = sts1solver.search.DeathSaves.fairiesInBar();
                    int savesAfterFairy = sts1solver.search.DeathSaves.usedSoFar(fairies0);
                    boolean aliveAfterFairy = AbstractDungeon.player.currentHealth > 0
                            && !AbstractDungeon.player.isDead;
                    Log.info("  S55 after the first lethal hit: hp="
                            + AbstractDungeon.player.currentHealth + " fairies=" + fairiesAfter
                            + " saves=" + savesAfterFairy + " alive=" + aliveAfterFairy);
                    Probe.check(savesAfterFairy == 1 && fairiesAfter == 0 && aliveAfterFairy,
                            "a lethal hit spends the Fairy in a Bottle and the player survives",
                            "fairies=" + fairiesAfter + " saves=" + savesAfterFairy
                                    + " hp=" + AbstractDungeon.player.currentHealth
                                    + " alive=" + aliveAfterFairy);
                    Probe.check(!sts1solver.search.DeathSaves.lizardTailSpent(),
                            "the relic is still ready while the potion does the saving", "");
                    // Second lethal hit: now only Lizard Tail is left, and it flips its counter.
                    AbstractDungeon.player.damage(new com.megacrit.cardcrawl.cards.DamageInfo(
                            AbstractDungeon.player, 999,
                            com.megacrit.cardcrawl.cards.DamageInfo.DamageType.HP_LOSS));
                    Driver.drain();
                    boolean tailSpent = sts1solver.search.DeathSaves.lizardTailSpent();
                    int savesAfterTail = sts1solver.search.DeathSaves.usedSoFar(fairies0);
                    boolean aliveAfterTail = AbstractDungeon.player.currentHealth > 0
                            && !AbstractDungeon.player.isDead;
                    Log.info("  S55 after the second lethal hit: hp="
                            + AbstractDungeon.player.currentHealth + " tailSpent=" + tailSpent
                            + " saves=" + savesAfterTail + " alive=" + aliveAfterTail);
                    Probe.check(tailSpent && savesAfterTail == 2 && aliveAfterTail,
                            "a second lethal hit burns Lizard Tail (counter -2) and is counted",
                            "tailSpent=" + tailSpent + " saves=" + savesAfterTail
                                    + " hp=" + AbstractDungeon.player.currentHealth
                                    + " alive=" + aliveAfterTail);
                } finally {
                    Driver.end();
                    w.readBack();
                    w.uninstall();
                }
            }
        });

        Probe.step("S56 route quality reads the reference's keys, not our own panel numbers",
                new Runnable(){
            @Override
            public void run() {
                // The reference orders finished routes by
                // CombatSolver-main src\Search\RouteQualityPolicy.cs:98-115 (ComparePrimary):
                // won -> survives -> death-save uses -> strategic HP deficit -> growth -> end turn.
                // Block is absent there on purpose: it only appears in beam retention
                // (BeamRetentionPolicy.Ranking.cs:34-35 UsefulDefensiveBlockReserve).
                int ok = 0;
                int total = 0;
                // 1. victory beats a survival/escape line, which beats a death.
                ++total;
                if (Solver.compareRoutes(true, false, 0, 50, 0, 20, 1,
                        false, true, 0, 0, 0, 3, 1) < 0) ++ok;
                ++total;
                if (Solver.compareRoutes(false, true, 0, 0, 0, 3, 1,
                        false, false, 0, 5, 0, 3, 1) < 0) ++ok;
                Probe.check(ok == total,
                        "a victory outranks an escape, and an escape outranks a death",
                        ok + "/" + total);
                // 2. deficit comes BEFORE turns: a 9-turn clean win beats a 3-turn win that cost 10 HP.
                Probe.check(Solver.compareRoutes(true, false, 0, 0, 0, 9, 1,
                        true, false, 0, 10, 0, 3, 1) < 0,
                        "strategic deficit is read before the turn count",
                        "0hp/9turns vs 10hp/3turns");
                // 3. turns decide among equal deficit (the old bug went the other way through block).
                Probe.check(Solver.compareRoutes(true, false, 0, 0, 0, 7, 1,
                        true, false, 0, 0, 0, 9, 1) < 0,
                        "with the same deficit fewer turns win",
                        "7 vs 9");
                // 4. death saves outrank HP, and potions are HP of deficit (reference exchange rate:
                //    the standard tier is 9 HP, and a potion used to be a flat 10 -- the value passed
                //    here is the potion HP cost itself, see PotionBook).
                Probe.check(Solver.compareRoutes(false, false, 0, 30, 0, 3, 1,
                        false, false, 1, 0, 0, 3, 1) < 0,
                        "a route that keeps its death save outranks one that does not",
                        "saves 0/30hp vs 1/0hp");
                Probe.check(Solver.compareRoutes(true, false, 0, 0, 10, 3, 1,
                        true, false, 0, 10, 0, 3, 1) == 0,
                        "ten HP of potion value is exactly ten HP of deficit",
                        "compare=" + Solver.compareRoutes(true, false, 0, 0, 10, 3, 1,
                                true, false, 0, 10, 0, 3, 1));
                // 5. Leftover block is not a quality dimension at all (a 9-turn win with 40 block
                //    cannot buy its way past a 7-turn clean win) -- the old G5 fix, kept pinned.
                Probe.check(Solver.scoreOf(0, 0, true, false, 7, 0, 0, 0)
                                > Solver.scoreOf(0, 0, true, false, 9, 0, 40, 0),
                        "leftover block cannot buy a slower win",
                        Solver.scoreOf(0, 0, true, false, 7, 0, 0, 0) + " vs "
                                + Solver.scoreOf(0, 0, true, false, 9, 0, 40, 0));
                // 6. The reference's IsCompleteVictory is a separate flag, not a rewrite of `win`:
                //    on a real search a reported victory is always replayable, and the flag agrees.
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 5601L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Bash", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Solver.Result result = Solver.solvePortfolio(World.captureLive(), 8000L);
                Log.info("  S56 search: " + result.summary() + " steps=" + result.plan.size());
                Probe.check(!result.win || result.completeVictory,
                        "a reported victory is a complete victory (win and replayable agree)",
                        "win=" + result.win + " complete=" + result.completeVictory
                                + " steps=" + result.plan.size());
                Probe.check(!result.win || result.plan.size() > 0,
                        "a reported victory still carries at least one action",
                        "win=" + result.win + " steps=" + result.plan.size());
                Probe.check(result.summary().contains("complete="),
                        "the result summary exposes the complete-victory flag",
                        result.summary());
            }
        });
