                        int t0 = GameActionManager.turn;
                        int e0 = Driver.energy();
                        Legal.apply(vault);
                        int t1 = GameActionManager.turn;
                        int e1 = Driver.energy();
                        int hand = AbstractDungeon.player.hand.size();
                        int hpAfter = AbstractDungeon.player.currentHealth;
                        Log.info("  S52 vault: turn " + t0 + "->" + t1 + " energy " + e0 + "->" + e1
                                + " hand=" + hand + " hp " + hpBefore + "->" + hpAfter
                                + " over=" + Driver.combatOver());
                        Probe.check(t1 == t0 + 1,
                                "Vault advances the turn instead of stalling on the button",
                                t0 + "->" + t1);
                        Probe.check(e1 == master, "Vault hands the next turn its full energy",
                                e1 + "/" + master);
                        Probe.check(hpAfter == hpBefore,
                                "the enemy turn is skipped, so nothing hits the player",
                                hpBefore + "->" + hpAfter);
                        Probe.check(hand > 0 && !Driver.combatOver(),
                                "the next turn really starts (a new hand was drawn)",
                                "hand=" + hand + " over=" + Driver.combatOver());
