        Probe.step("S44 the step marker follows the card, not the position", new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9923L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Defend_R", "Bash", "Strike_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                World w = World.captureLive();
                w.install();
                Driver.begin();
                try {
                    java.util.List<AbstractCard> hand = AbstractDungeon.player.hand.group;
                    if (hand.size() < 3) {
                        Probe.check(false, "the marker gate needs a full hand", String.valueOf(hand.size()));
                        return;
                    }
                    AbstractCard meant = hand.get(2);
                    String uuid = meant.uuid.toString();
                    // The hand is restructured: the card that WAS at index 2 is moved to 0, so the
                    // plan's saved index now points at a different card. (A reverse() would leave a
                    // 5-card hand's middle card exactly where it was -- this gate must really move it.)
                    java.util.Collections.swap(hand, 0, 2);
                    Probe.check(!uuid.equals(hand.get(2).uuid.toString()),
                            "the hand really was reordered", "");
                    String byUuid = sts1solver.ui.Hud.markerSnapshotForUuid(uuid);
                    Log.info("  S44 by uuid: " + byUuid + "  (old index 2 now holds "
                            + hand.get(2).name + ")");
                    Probe.check(byUuid.startsWith("card=ok"),
                            "the marker still finds the intended card", byUuid);
                    sts1solver.ui.Hud.markStep(uuid, 2, -1, false);
                    String marked = sts1solver.ui.Hud.markerSnapshot();
                    Log.info("  S44 marked: " + marked);
                    Probe.check(marked.contains("card=ok"),
                            "the drawn marker resolves by identity", marked);
                } catch (Throwable t) {
                    Probe.check(false, "the marker gate ran", String.valueOf(t));
                } finally {
                    Driver.end();
                    w.readBack();
                    w.uninstall();
                }
            }
        });

