        Probe.step("S49 a clone silences the MTS console but not our log file (P1-2d)",
                new Runnable(){
            @Override
            public void run() {
                try {
                    sts1solver.util.ConsoleMute.reset();
                    Probe.check(!sts1solver.util.ConsoleMute.isMuted(),
                            "the console is attached when nothing is simulated", "");
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9431L;
                    spec.maxHealth = 80;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R"};
                    spec.monsters = new String[]{
                            "com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Object filter = consoleFilter();
                    String before = filterVerdict(filter);
                    String marker = "S49 file channel marker " + System.nanoTime();
                    World w = World.captureLive();
                    w.install();
                    try {
                        Probe.check(sts1solver.util.ConsoleMute.isMuted(),
                                "installing a clone mutes the console", sts1solver.util.ConsoleMute.status());
                        String inside = filterVerdict(filter);
                        Log.info("  S49 filter " + before + " -> " + inside + " ("
                                + sts1solver.util.ConsoleMute.status() + ")");
                        Probe.check("DENY".equals(inside),
                                "the console appender is told to drop the event", String.valueOf(inside));
                        Log.info(marker);
                    } finally {
                        w.uninstall();
                    }
                    Probe.check(!sts1solver.util.ConsoleMute.isMuted(),
                            "uninstalling hands the console back", "");
                    Probe.check("NEUTRAL".equals(filterVerdict(filter)),
                            "the filter lets events through again once the clone is gone",
                            String.valueOf(filterVerdict(filter)));
                    String logText = "";
                    try {
                        logText = new String(java.nio.file.Files.readAllBytes(
                                java.nio.file.Paths.get(Log.pathFor("solver.log"))),
                                java.nio.charset.StandardCharsets.UTF_8);
                    } catch (Throwable ignored) {
                        // reported below
                    }
                    Probe.check(logText.contains(marker),
                            "our own log line still reached solver.log while muted", marker);
                    // the mute must nest: a probe window around a solve survives an inner uninstall
                    sts1solver.util.ConsoleMute.push();
                    World outer = World.captureLive();
                    outer.install();
                    outer.uninstall();
                    boolean stillMuted = sts1solver.util.ConsoleMute.isMuted();
                    sts1solver.util.ConsoleMute.pop();
                    Probe.check(stillMuted && !sts1solver.util.ConsoleMute.isMuted(),
                            "an inner install/uninstall does not unmute an outer window",
                            String.valueOf(stillMuted));
                } catch (Throwable t) {
                    Probe.check(false, "the console-mute gate ran", String.valueOf(t));
                } finally {
                    sts1solver.util.ConsoleMute.reset();
                }
            }
        });

