        Probe.core("S126 B76: an exhausted card comes back with its printed cost, and the exhaust pile"
                        + " never reports a per-turn cost as a drift",
                new Runnable(){
            @Override
            public void run() {
                // B76 (m21391): the live game resets an exhausted card one second later, inside
                // ExhaustCardEffect. The sandbox drops that effect, so the card kept the cost it had
                // for the turn -- and the plan was thrown away over "Shockwave(0)" vs "Shockwave".
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9126L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Gameplay.reset();
                com.megacrit.cardcrawl.characters.AbstractPlayer p =
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                com.megacrit.cardcrawl.cards.AbstractCard inHand = null;
                com.megacrit.cardcrawl.cards.AbstractCard toExhaust = null;
                for (com.megacrit.cardcrawl.cards.AbstractCard c : p.hand.group) {
                    if (inHand == null && "Strike_R".equals(c.cardID)) {
                        inHand = c;
                    }
                    if (toExhaust == null && "Defend_R".equals(c.cardID)) {
                        toExhaust = c;
                    }
                }
                if (inHand == null || toExhaust == null) {
                    Probe.check(false, "the hand holds a Strike_R and a Defend_R", "null card");
                    return;
                }
                inHand.setCostForTurn(0);
                int printed = toExhaust.cost;
                toExhaust.setCostForTurn(0);
                p.hand.moveToExhaustPile(toExhaust);
                boolean kept = toExhaust.costForTurn == 0;
                sts1solver.mirror.ExhaustAttrs.begin();
                boolean reset = toExhaust.costForTurn == printed && !toExhaust.isCostModifiedForTurn;
                String digest = sts1solver.mirror.Digest.ofCurrent();
                boolean handShows = digest.indexOf("Strike_R(0)") >= 0;
                boolean exhaustQuiet = digest.indexOf("Defend_R(0)") < 0;
                Log.info("  S126 exhaust: keptBeforeReset=" + kept + " printed=" + printed
                        + " reset=" + reset + " handShows=" + handShows
                        + " exhaustQuiet=" + exhaustQuiet
                        + " resets=" + sts1solver.mirror.ExhaustAttrs.resets()
                        + " last=[" + sts1solver.mirror.ExhaustAttrs.lastReset() + "]");
                Probe.check(kept, "the effect never runs here, so the card did keep the turn cost", "");
                Probe.check(reset, "the sandbox resets an exhausted card like the live game does", "");
                Probe.check(handShows && exhaustQuiet,
                        "only the exhaust pile stops reporting a per-turn cost",
                        "handShows=" + handShows + " exhaustQuiet=" + exhaustQuiet);
            }
        });


        Probe.core("S127 B77: a plan survives both a missing card and a drift -- it only pauses",
                new Runnable(){
            @Override
            public void run() {
                // B77 (m21571): STS2 behaviour, as the player asked. Deploy the plan; when the card
                // or the potion it names is gone, pause and KEEP the plan; when the board comes out
                // differently than predicted, keep walking instead of dropping the route.
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9127L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Defend_R", "Defend_R", "Defend_R", "Strike_R", "Strike_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Gameplay.reset();
                // The first tick after a fresh fight latches "in combat" and clears the slate
                // (Gameplay.java: inCombat transition). Let it happen before the plan is installed,
                // otherwise the gate is really testing that reset path, not the pause.
                Gameplay.tick();
                for (int i = 0; i < 400 && !Gameplay.engineSettledForTest(); i++) {
                    com.megacrit.cardcrawl.dungeons.AbstractDungeon.actionManager.update();
                }
                Solver.Result r = Solver.solve(sts1solver.mirror.World.captureLive(), 16, 48, 6000L);
                if (r == null || r.plan == null || r.plan.isEmpty()) {
                    Probe.check(false, "the search produced a line to deploy", "plan empty");
                    return;
                }
                int cardStep = -1;
                String cardId = null;
                for (int i = 0; i < r.plan.size(); i++) {
                    Solver.Step st = r.plan.get(i);
                    if (st.action != null && st.action.isCard() && cardId == null) {
                        cardStep = i;
                        cardId = st.action.cardId;
                    }
                }
                if (cardId == null) {
                    Probe.check(false, "the line contains a card play", "steps=" + r.plan.size());
                    return;
                }
                com.megacrit.cardcrawl.characters.AbstractPlayer p =
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                int dropped = 0;
                for (int i = p.hand.group.size() - 1; i >= 0; i--) {
                    com.megacrit.cardcrawl.cards.AbstractCard c = p.hand.group.get(i);
                    if (c != null && cardId.equals(c.cardID)) {
                        p.hand.moveToDiscardPile(c);
                        ++dropped;
                    }
                }
                Gameplay.installPlanForTest(r, cardStep);
                Gameplay.tick();
                String missing = Gameplay.planStateForTest();
                boolean keptPlan = missing.indexOf("plan=-") < 0;
                boolean paused = missing.indexOf("autopilot=false") >= 0;
                boolean said = missing.indexOf("\u8ba1\u5212\u5df2\u4fdd\u7559") >= 0;
                Log.info("  S127 missing: id=" + cardId + " cards=" + dropped + " " + missing);
                Probe.check(keptPlan && paused && said,
                        "a card that is not in hand pauses the autopilot and keeps the plan",
                        missing);
                Gameplay.installPlanForTest(r, cardStep);
                Gameplay.driftForTest();
                String drifted = Gameplay.planStateForTest();
                Log.info("  S127 drift: " + drifted);
                Probe.check(drifted.indexOf("plan=-") < 0 && drifted.indexOf("autopilot=true") >= 0,
                        "a board that came out differently no longer drops the plan", drifted);
            }
        });

        Probe.core("S128 B78: a step is matched by identity, and a line that cannot replay is not a win",
                new Runnable(){
            @Override
            public void run() {
                // B78 (m21889): the player asked why a plan still wanted to play 发掘+ after 坚毅 had
                // exhausted it. The plan's NAMES came from the explored tree while its POSITIONS came
                // from a later replay, so "hand index 7" became whatever sat there -- the card next
                // to the intended one. A step now has to resolve by uuid / name, and a line whose
                // steps cannot be reproduced is reported as such instead of as 可赢.
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9128L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Defend_R", "Defend_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Gameplay.reset();
                Gameplay.tick();
                for (int i = 0; i < 400 && !Gameplay.engineSettledForTest(); i++) {
                    com.megacrit.cardcrawl.dungeons.AbstractDungeon.actionManager.update();
                }
                com.megacrit.cardcrawl.characters.AbstractPlayer p =
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                java.util.List<com.megacrit.cardcrawl.cards.AbstractCard> hand = p.hand.group;
                Action strike = null;
                for (Action a : Legal.actions()) {
                    if (a.isCard() && "Strike_R".equals(a.cardId)) {
                        strike = a;
                        break;
                    }
                }
                if (strike == null) {
                    Probe.check(false, "the opening hand offers a card play", "no Strike_R action");
                    return;
                }
                com.megacrit.cardcrawl.cards.AbstractCard expected =
                        hand.get(Math.min(strike.handIndex, hand.size() - 1));
                // Move the named card somewhere else: the recorded index now points at a neighbour.
                int strikeAt = hand.indexOf(expected);
                int otherAt = strikeAt == 0 ? 1 : 0;
                java.util.Collections.swap(hand, strikeAt, otherAt);
                com.megacrit.cardcrawl.cards.AbstractCard byIndex = hand.get(strike.handIndex);
                com.megacrit.cardcrawl.cards.AbstractCard resolved = Legal.handCardFor(strike);
                boolean identity = resolved == expected;
                boolean indexMoved = byIndex != expected;
                Log.info("  S128 identity: card=" + expected.name + " indexNow=" + (byIndex == null ? "?" : byIndex.name)
                        + " resolved=" + (resolved == null ? "?" : resolved.name)
                        + " identity=" + identity + " moved=" + indexMoved);
                Probe.check(identity && indexMoved,
                        "a step finds its card by identity even when the hand order changed",
                        "byIndex=" + (byIndex == null ? "?" : byIndex.name));

                // The reported case: the named card is GONE (exhausted). The old code played the
                // neighbour at that index; now the step refuses instead of guessing.
                p.hand.moveToExhaustPile(expected);
                String threw = "";
                boolean refused = false;
                try {
                    Legal.handCardFor(strike);
                } catch (Throwable t) {
                    refused = t instanceof sts1solver.search.ReplayException;
                    threw = String.valueOf(t.getMessage());
                }
                Log.info("  S128 missing: refused=" + refused + " msg=" + threw);
                Probe.check(refused,
                        "a step whose card is no longer in hand refuses instead of playing a neighbour",
                        threw);

                // And the panel must not call such a line a win.
                String partial = sts1solver.search.PlanText.replayedPartially(2, "发掘+", 2);
                Log.info("  S128 text: " + partial);
                Probe.check(partial.indexOf("重放不通过") >= 0 && partial.indexOf("第 3 步") >= 0
                                && partial.indexOf("不算可赢") >= 0 && partial.indexOf("可赢（") < 0,
                        "a line that did not replay is reported as such, never as a win", partial);
            }
        });

        Probe.core("S129 B79: the plan's answer is copied by uuid, and a refusal is retried and bucketed",
                new Runnable(){
            @Override
            public void run() {
                // B79 (user m22205): the player asked for two things -- the printed line must be
                // playable, and a replay that fails must be a REAL failure, not "the screen had not
                // opened yet". (1) The plan carries the uuid of the card it picked, so a replay copies
                // that pick instead of deciding again -- two identical Defends are indistinguishable by
                // id or by name. (2) A refusal is retried once after the engine settles, so "not yet"
                // is told apart from "not offered". (3) Whatever survives is bucketed in the log.
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9129L;
                spec.maxHealth = 80;
                spec.ascension = 0;
                spec.deck = new String[]{"Headbutt", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Gameplay.reset();
                Gameplay.tick();
                for (int i = 0; i < 400 && !Gameplay.engineSettledForTest(); i++) {
                    com.megacrit.cardcrawl.dungeons.AbstractDungeon.actionManager.update();
                }
                com.megacrit.cardcrawl.characters.AbstractPlayer p =
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                while (!p.hand.group.isEmpty()) {
                    p.hand.group.remove(0);
                }
                p.discardPile.group.clear();
                com.megacrit.cardcrawl.cards.AbstractCard hb =
                        com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Headbutt");
                com.megacrit.cardcrawl.cards.AbstractCard first =
                        com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Defend_R");
                com.megacrit.cardcrawl.cards.AbstractCard second =
                        com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Defend_R");
                p.hand.group.add(hb);
                p.hand.refreshHandLayout();
                p.discardPile.addToTop(first);
                p.discardPile.addToTop(second);
                String want = second.uuid.toString();
                Action step = Action.card(0, 0, 0, "Headbutt", hb.name, "JawWorm", "Headbutt",
                        hb.uuid.toString()).withChoice("Defend_R", second.name, want);
                boolean carried = want.equals(step.choiceUuids) && "Defend_R".equals(step.choice);
                java.util.List<Action> line = new java.util.ArrayList<Action>();
                line.add(step);
                java.util.List<Solver.Step> steps = Solver.replay(sts1solver.mirror.World.captureLive(), line);
                String copied = steps.isEmpty() ? "-" : steps.get(0).action.choiceUuids;
                boolean copyOk = want.equals(copied);
                Log.info("  S129 copy: carried=" + carried + " steps=" + steps.size()
                        + " copied=" + (copyOk ? "the planned copy" : copied)
                        + " failure=" + Solver.lastReplayFailure());
                Probe.check(carried && steps.size() == 1 && copyOk,
                        "a replayed line picks the exact card the plan named (uuid, not a second guess)",
                        "carried=" + carried + " steps=" + steps.size() + " copied=" + copied);

                // Same board, a plan that asks for a card this fight cannot offer: refused, with a
                // bucket. The settle-retry runs first, so a screen that opens a tick late cannot be
                // reported as a modelling error.
                Action bad = Action.card(0, 0, 0, "Headbutt", hb.name, "JawWorm", "Headbutt",
                        hb.uuid.toString()).withChoice("Bash", "Bash", "");
                java.util.List<Action> line2 = new java.util.ArrayList<Action>();
                line2.add(bad);
                java.util.List<Solver.Step> steps2 = Solver.replay(sts1solver.mirror.World.captureLive(), line2);
                String why = Solver.lastReplayFailure();
                boolean refused = steps2.isEmpty();
                boolean classified = why.indexOf("not-offered") >= 0 || why.indexOf("not-settled") >= 0;
                Log.info("  S129 refused: steps=" + steps2.size() + " failure=" + why);
                Probe.check(refused && classified,
                        "a line the board cannot answer is refused with a reason bucket", why);

                Driver.SelectionKind idle = Driver.settleForReplay(4);
                boolean bounded = idle == Driver.SelectionKind.NONE && Driver.lastSettlePumps() <= 4L;
                Log.info("  S129 settle: idle=" + idle + " pumps=" + Driver.lastSettlePumps()
                        + " bounded=" + bounded);
                Probe.check(bounded,
                        "settling is bounded and reports no screen when there is none",
                        "idle=" + idle + " pumps=" + Driver.lastSettlePumps());
            }
        });

