        Probe.core("S133 m23574: Well-Laid Plans chooses a card to keep at end of turn, and it stays",
                new Runnable(){
            @Override
            public void run() {
                String old = s133Retain(false, false);
                Log.info("  S133 old: " + old);
                String generic = s133Retain(false, true);
                Log.info("  S133 generic: " + generic);
                String list = s133Retain(true, false);
                Log.info("  S133 list: " + list);
                // The pick leaves the hand the moment it is answered (a real click does the same,
                // HandCardSelectScreen.selectHoveredCard). With the old fast frame the retain action is
                // already done, so nothing retrieves it and the card is not kept -- which is the bug this
                // row pins down. (Before B181 the un-retained card also vanished from every pile; the
                // answer now resolves on the small frame, so it is discarded instead. Both are "not
                // kept", and that is the property this branch asserts.)
                Probe.check(old.startsWith("ok") && old.contains("inHand=false")
                        && old.contains("exhausted=false"),
                        "with a big frame and the screen rule off the chosen card is not kept", old);
                Probe.check(generic.startsWith("ok") && generic.contains("awaited=true"),
                        "ending the turn stops at the keep-a-card screen", generic);
                Probe.check(generic.startsWith("ok") && generic.contains("inHand=true")
                        && generic.contains("discarded=false") && generic.contains("exhausted=false"),
                        "the screen rule alone keeps the chosen card in hand", generic);
                Probe.check(generic.startsWith("ok") && s122Int(generic, "screenFrames=") > 0,
                        "the frozen frames were handed the game's own frame length", generic);
                Probe.check(generic.startsWith("ok") && s122Int(generic, "orphans=") == 0,
                        "no selection was left with nothing to consume it", generic);
                Probe.check(generic.startsWith("ok") && s122Int(generic, "discard=") == 4,
                        "every card that was not kept is discarded", generic);
                Probe.check(generic.startsWith("ok") && s122Int(generic, "handAfter=") == 6,
                        "the kept card is one of the six cards in hand after the turn", generic);
                Probe.check(list.startsWith("ok") && list.contains("inHand=true"),
                        "the older per-power small frame still keeps the card", list);
            }
        });
