        Probe.core("S146 RNG: a sandbox random copies the stream POSITION, not a shared seed", new Runnable(){
            @Override
            public void run() {
                // A java.util.Random keeps its position in an AtomicLong; ClonePolicy shares
                // java.util.concurrent.* by reference, so a field-by-field copy silently kept pointing at
                // the LIVE seed. Every simulated draw then advanced the real run's stream, and two
                // sibling forks drew from one sequence. The copy is now made by serializing the stream
                // position, and this gate holds that to account.
                java.util.List<String> keys = Statics.mirrorKeys();
                boolean wired = keys.contains("com.badlogic.gdx.math.MathUtils#random");
                Log.info("  S146 mirror keys: " + keys.size() + " (MathUtils.random=" + wired + ")");
                Probe.check(wired, "the global MathUtils random (533 call sites) is in the mirror table",
                        wired ? "wired" : "absent from Statics.ROOTS");

                long seed = 20261102L;
                java.util.Random live = new java.util.Random(seed);
                java.util.Random reference = new java.util.Random(seed);
                java.util.Random copy = new Cloner().copy(live);
                StringBuilder wrong = new StringBuilder();
                boolean same = true;
                for (int i = 0; i < 6; i++) {
                    int got = copy.nextInt(1000);
                    int want = reference.nextInt(1000);
                    if (got != want) {
                        same = false;
                        wrong.append(" i=").append(i).append(" copy=").append(got).append(" live=").append(want);
                    }
                }
                Probe.check(copy != live, "the copy is a separate object, not the live seed holder",
                        copy == live ? "same object" : "distinct");
                Probe.check(same, "a copied random continues at the live stream's position",
                        same ? "6/6 draws equal" : wrong.toString().trim());

                java.util.Random src = new java.util.Random(seed);
                for (int i = 0; i < 5; i++) {
                    src.nextInt();
                }
                java.util.Random f1 = new Cloner().copy(src);
                java.util.Random f2 = new Cloner().copy(src);
                StringBuilder s1 = new StringBuilder();
                StringBuilder s2 = new StringBuilder();
                for (int i = 0; i < 5; i++) {
                    s1.append(f1.nextInt(100)).append(',');
                    s2.append(f2.nextInt(100)).append(',');
                }
                java.util.Random src2 = new java.util.Random(seed);
                for (int i = 0; i < 5; i++) {
                    src2.nextInt();
                }
                StringBuilder srcSeq = new StringBuilder();
                for (int i = 0; i < 5; i++) {
                    srcSeq.append(src2.nextInt(100)).append(',');
                }
                Probe.check(s1.toString().equals(s2.toString()),
                        "two sibling forks from one position draw the same numbers (independent copies)",
                        "a=" + s1 + "b=" + s2);
                Probe.check(srcSeq.toString().equals(s1.toString()),
                        "drawing inside the copies did not advance the source stream",
                        "source=" + srcSeq + "copy=" + s1);
            }
        });
        Probe.core("S147 panel: a potion action prints the potion's name, not its slot", new Runnable(){
            @Override
            public void run() {
                // B92: the panel showed "POTION#2". The slot is gone the moment the potion is drunk, so
                // the name has to be captured when the action is built; this gate builds one and reads
                // the label back, which is exactly what the panel and the execute history print.
                //
                // Asked for on its own (-Gates S147) the suite starts at the main menu with no player at
                // all; the first version dereferenced AbstractDungeon.player.potions unguarded and
                // reported an NPE as a failed gate. Build a board first, like the older gates do.
                if (AbstractDungeon.player == null) {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 91L;
                    spec.maxHealth = 80;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                    Log.info("  S147 built a board first: player="
                            + (AbstractDungeon.player == null ? "-" : Integer.toString(AbstractDungeon.player.currentHealth)));
                }
                com.megacrit.cardcrawl.potions.AbstractPotion potion =
                        new com.megacrit.cardcrawl.potions.FirePotion();
                java.util.ArrayList<com.megacrit.cardcrawl.potions.AbstractPotion> belt = null;
                String label = null;
                String expected = null;
                int slot = -1;
                try {
                    belt = AbstractDungeon.player.potions;
                    slot = belt.size();
                    belt.add(potion);
                    label = new Driver.Play(null, null, 0, slot).label();
                    expected = potion.name;
                } finally {
                    if (belt != null && slot >= 0 && slot < belt.size() && belt.get(slot) == potion) {
                        belt.remove(slot);
                    }
                }
                Log.info("  S147 potion label: " + label + " (potion name=" + expected
                        + ", slot=" + slot + ")");
                Probe.check(label != null && label.startsWith(expected),
                        "the action label spells the potion out", label == null ? "no label" : label);
                Probe.check(label == null || !label.startsWith("POTION#"),
                        "the label is not the internal slot number",
                        label == null ? "no label" : label);
            }
        });
        Probe.core("S148 autoplay: the panel plays a mod character's line on the real engine", new Runnable(){
            @Override
            public void run() {
                // P6-02: S146/S147 prove the sandbox agrees with the live engine when OUR code applies
                // the action. Autoplay does it differently -- it finds the card by uuid in the hand,
                // submits an end turn through the player and waits for the engine to settle. A mod
                // character whose cards only exist inside the sandbox would pass those and fail this.
                //
                // Skipped one by one when the character mod is not enabled, so the core suite (which
                // runs without character mods) stays green instead of reporting a fake failure.
                // 2026-11-02: the user unsubscribed every character mod except these two (ninja / 菜农),
                // so the list shrank to what is actually on the install. The other entries used to be
                // covered here (aristocrat, and the merchant ArlequinAndante which registers into the
                // game's own package, B90); they are kept as a comment so a later install with more
                // mods can put them back: "aristocrat.CharacterFile",
                // "com.megacrit.cardcrawl.characters.MerchantPlayer".
                String[] classes = {"characters.ninja", "CaiNongMod.Characters.CaiNong"};
                int ran = 0;
                for (int i = 0; i < classes.length; i++) {
                    String report = ModCharProbe.autoplayCheckForTest(classes[i], 4000L);
                    Log.info("  S148 " + classes[i] + ": " + report);
                    if (report.startsWith("skipped")) {
                        Probe.check(true, classes[i] + " is not enabled on this install (skipped)",
                                report);
                        continue;
                    }
                    ++ran;
                    int verified = s122Int(report, "verified=");
                    int want = s122Int(report, "want=");
                    int drift = s122Int(report, "drift=");
                    Probe.check(verified >= Math.min(1, want),
                            "autoplay executed the mod character's first step",
                            report);
                    Probe.check(drift == 0, "the mod character's line did not drift", report);
                }
                Probe.check(true, "mod character autoplay coverage", ran + " character(s) exercised");
            }
        });
