        Probe.core("S150 a card is identified by its STATE, not by its id (B98)", new Runnable(){
            @Override
            public void run() {
                // B98 (user m02347): a uuid is fork local, an id merges every copy. Two Strikes that
                // differ only in misc (Blood for Blood's cost, Rampage's damage, most mod cards) were
                // ONE branch for the search and ONE pick for the replay, so the plan could score one
                // copy and the live game play the other. This gate pins all four halves of the fix.
                com.megacrit.cardcrawl.cards.AbstractCard proto =
                        com.megacrit.cardcrawl.helpers.CardLibrary.getCard("Slice_R");
                if (proto == null) {
                    proto = com.megacrit.cardcrawl.helpers.CardLibrary.getCard("Strike_R");
                }
                if (proto == null || com.megacrit.cardcrawl.dungeons.AbstractDungeon.player == null) {
                    Probe.check(true, "card library / combat is not up yet (skipped)", "");
                    return;
                }
                com.megacrit.cardcrawl.cards.AbstractCard one = proto.makeCopy();
                com.megacrit.cardcrawl.cards.AbstractCard two = proto.makeCopy();
                one.misc = 3;
                two.misc = 7;
                String p1 = sts1solver.mirror.CardPrint.of(one);
                String p2 = sts1solver.mirror.CardPrint.of(two);
                Probe.check(!p1.equals(p2),
                        "two copies of one id carry DIFFERENT prints (misc is in it)", p1 + " vs " + p2);

                java.util.List<com.megacrit.cardcrawl.cards.AbstractCard> offered =
                        new java.util.ArrayList<com.megacrit.cardcrawl.cards.AbstractCard>();
                offered.add(one);
                offered.add(two);
                java.util.List<com.megacrit.cardcrawl.cards.AbstractCard> byPrint =
                        sts1solver.drive.Driver.picksFor(offered, one.cardID, null, null, p2);
                Probe.check(byPrint.size() == 1 && byPrint.get(0) == two,
                        "the matcher takes the copy whose state the plan recorded",
                        "picked=" + (byPrint.isEmpty() ? "none" : byPrint.get(0) == two ? "the named one" : "the other one"));

                com.megacrit.cardcrawl.cards.CardGroup hand =
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.player.hand;
                boolean addedOne = false;
                boolean addedTwo = false;
                try {
                    hand.group.add(one);
                    addedOne = true;
                    hand.group.add(two);
                    addedTwo = true;
                    String staleUuid = java.util.UUID.randomUUID().toString();
                    sts1solver.search.Action byState = sts1solver.search.Action.card(0, -1, 0, "probe",
                            one.name, "", one.cardID, staleUuid).withCardPrint(p2);
                    com.megacrit.cardcrawl.cards.AbstractCard got =
                            sts1solver.search.Legal.handCardFor(byState);
                    Probe.check(got == two,
                            "a uuid the live game never saw + the print resolves the planned copy",
                            "resolved to the " + (got == two ? "planned" : "other") + " copy");

                    java.util.Set<String> inHand = new java.util.HashSet<String>();
                    java.util.List<sts1solver.search.Action> acts = sts1solver.search.Legal.actions();
                    for (int i = 0; i < acts.size(); i++) {
                        if (one.cardID.equals(acts.get(i).cardId) && !acts.get(i).isEndTurn()) {
                            inHand.add(acts.get(i).cardPrint);
                        }
                    }
                    Probe.check(inHand.isEmpty() || inHand.contains(p1) && inHand.contains(p2),
                            "the search branches on BOTH copies (the dedupe key is the print)",
                            inHand.isEmpty() ? "not playable in this state (skipped)"
                                    : "branches=" + inHand.size());

                    sts1solver.search.Action ambiguous = sts1solver.search.Action.card(0, -1, 0, "probe",
                            one.name, "", one.cardID, staleUuid).withCardPrint(p1 + "|nope");
                    boolean refused = false;
                    try {
                        sts1solver.search.Legal.handCardFor(ambiguous);
                    } catch (Throwable t) {
                        refused = t instanceof sts1solver.search.ReplayException;
                    }
                    Probe.check(refused,
                            "several copies, none with the planned state -> the replay refuses to guess",
                            "refused=" + refused);
                    Log.info("  S150 state identity: 5 rule(s) pinned");
                } finally {
                    if (addedTwo) {
                        hand.group.remove(two);
                    }
                    if (addedOne) {
                        hand.group.remove(one);
                    }
                }
            }
        });
        Probe.core("S151 a mod potion drinks identically on the panel path and in the sandbox",
                new Runnable(){
            @Override
            public void run() {
                String[] mods = {"potions.AmoXilin", "potions.LexKelaPotion", "potions.NH42SO4"};
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 20261L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                World clean = World.captureLive();
                int exercised = 0;
                String bad = null;
                StringBuilder detail = new StringBuilder();
                try {
                    for (int i = 0; i < mods.length; i++) {
                        Class<?> k;
                        try {
                            k = Class.forName(mods[i]);
                        } catch (Throwable notLoaded) {
                            continue;
                        }
                        String simple = k.getSimpleName();
                        com.megacrit.cardcrawl.potions.AbstractPotion probe;
                        try {
                            probe = (com.megacrit.cardcrawl.potions.AbstractPotion)
                                    k.getConstructor().newInstance();
                        } catch (Throwable noCtor) {
                            detail.append(simple).append("=no-ctor ");
                            continue;
                        }
                        if (!sts1solver.search.PotionBook.usable(probe)) {
                            detail.append(simple).append("=not-usable ");
                            continue;
                        }
                        // (1) the search path: drink it on a mirrored copy of this fight.
                        String sand;
                        com.megacrit.cardcrawl.potions.AbstractPotion saved = AbstractDungeon.player.potions.get(0);
                        try {
                            AbstractDungeon.player.potions.set(0, probe);
                            World w = World.captureLive();
                            boolean installed = false;
                            try {
                                w.install();
                                installed = true;
                                Driver.begin();
                                try {
                                    Driver.usePotion(0, -1);
                                } finally {
                                    Driver.end();
                                }
                                sand = Digest.stable(Digest.ofCurrent());
                            } finally {
                                if (installed) {
                                    w.uninstall();
                                } else {
                                    AbstractDungeon.player.potions.set(0, saved);
                                }
                            }
                        } catch (Throwable t) {
                            detail.append(simple).append("=sandbox-threw:")
                                    .append(t.getClass().getSimpleName()).append(' ');
                            continue;
                        }
                        // (2) the panel path: the same potion, clicked in the pop-up.
                        boolean drank;
                        String live;
                        com.megacrit.cardcrawl.potions.AbstractPotion before = AbstractDungeon.player.potions.get(0);
                        try {
                            AbstractDungeon.player.potions.set(0,
                                    (com.megacrit.cardcrawl.potions.AbstractPotion)
                                            k.getConstructor().newInstance());
                            drank = Gameplay.submitPotionForTest(0, -1);
                            // The pop-up path QUEUES the potion's effect; the frame loop drains it.
                            // A gate that reads the digest right here would compare "queued" with
                            // "applied" and call a correct path a divergence (first run of S151 did
                            // exactly that: live q=1, power not yet applied).
                            for (int pump = 0; pump < 400 && !Gameplay.engineSettledForTest(); pump++) {
                                AbstractDungeon.actionManager.update();
                            }
                            live = Digest.stable(Digest.ofCurrent());
                        } catch (Throwable t) {
                            detail.append(simple).append("=live-threw:")
                                    .append(t.getClass().getSimpleName()).append(' ');
                            AbstractDungeon.player.potions.set(0, before);
                            continue;
                        }
                        AbstractDungeon.player.potions.set(0, before);
                        exercised++;
                        detail.append(simple).append(drank ? "=ok" : "=refused").append(' ');
                        if (!drank || !sand.equals(live)) {
                            if (bad == null) {
                                bad = simple + " drank=" + drank + " sand=" + sand + " live=" + live;
                            }
                        }
                    }
                } finally {
                    // Rewind the fight: capture-then-install-then-uninstall puts every root back the
                    // way it was before this gate drank anything.
                    boolean rewound = false;
                    try {
                        clean.install();
                        rewound = true;
                    } catch (Throwable ignored) {
                        // A failed rewind is the gate's own cleanup; the next gate builds its own
                        // fight, so there is nothing to report from here.
                    } finally {
                        if (rewound) {
                            clean.uninstall();
                        }
                    }
                }
                Log.info("  S151 mod potion parity: " + exercised + " potion(s) " + detail);
                Probe.check(bad == null,
                        "a mod potion leaves the same state behind on both paths",
                        bad == null ? (exercised + " potion(s) exercised") : bad);
            }
        });
