        Probe.core("S153 potions can be measured, not assumed: the same fight with and without the belt (P6-12)",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 77721L;
                spec.maxHealth = 25;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{
                    "com.megacrit.cardcrawl.monsters.exordium.JawWorm",
                    "com.megacrit.cardcrawl.monsters.exordium.Cultist"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                com.megacrit.cardcrawl.potions.AbstractPotion saved =
                        AbstractDungeon.player.potions.get(0);
                AbstractDungeon.player.potions.set(0,
                        new com.megacrit.cardcrawl.potions.FirePotion());
                Solver.Result withBelt;
                Solver.Result noBelt;
                try {
                    // 20s, not 8s: the belt search has a LARGER action set (every potion is a
                    // branch), so on a loaded machine the same wall-clock budget buys it fewer
                    // depths and it can miss a win the smaller search found. That is a budget
                    // effect, not a potion effect, and this gate must not report it as one
                    // (observed as a "with=false without=true" failure under CPU contention).
                    sts1solver.search.Limits.forcePotionsForTest(Boolean.TRUE);
                    withBelt = Solver.solvePortfolio(World.captureLive(), 20000L);
                    sts1solver.search.Limits.forcePotionsForTest(Boolean.FALSE);
                    noBelt = Solver.solvePortfolio(World.captureLive(), 20000L);
                } finally {
                    sts1solver.search.Limits.forcePotionsForTest(null);
                    AbstractDungeon.player.potions.set(0, saved);
                }
                Log.info("  S153 potion baseline: with belt hpLoss=" + withBelt.hpLoss
                        + " potions=" + withBelt.potionsUsed + " win=" + withBelt.win
                        + " | without hpLoss=" + noBelt.hpLoss
                        + " potions=" + noBelt.potionsUsed + " win=" + noBelt.win);
                Probe.check(noBelt.potionsUsed == 0,
                        "a banned belt is never drunk from", "potions=" + noBelt.potionsUsed);
                // Dominance only means something when both searches actually finished: a run that
                // stopped on its time/node limit compared depths, not strategies.
                boolean conclusive = !limited(withBelt) && !limited(noBelt);
                // B180: this gate also asserted "belt hpLoss <= no-belt hpLoss" even when both runs
                // were cut short, which contradicted its own comment. Measured on a loaded machine
                // (full suite, 2026-11-10): with belt hpLoss=14 potions=0 win=true vs without
                // hpLoss=11 -- the belt search has every potion as a branch, so the same wall-clock
                // budget buys it fewer depths. That is the budget asymmetry documented above, not a
                // potion verdict; dominance below is asserted only when both runs stopped for real.
                Probe.check(!conclusive || !withBelt.win || withBelt.hpLoss <= noBelt.hpLoss,
                        "a comparison cut short by its budget is not read as a potion verdict",
                        "with=" + withBelt.reason + " without=" + noBelt.reason);
                if (!conclusive) {
                    Log.info("  S153 inconclusive: the searches stopped on a limit ("
                            + withBelt.reason + "/" + noBelt.reason + "), so dominance is not asserted");
                } else {
                    Probe.check(withBelt.hpLoss <= noBelt.hpLoss,
                            "the belt never makes the same fight worse",
                            "with=" + withBelt.hpLoss + " without=" + noBelt.hpLoss);
                    Probe.check(withBelt.win || !noBelt.win,
                            "a fight the belt wins is not lost without it",
                            "with=" + withBelt.win + " without=" + noBelt.win);
                }
            }
        });
