            public void run() {
                if (AbstractDungeon.player == null) {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 60607L;
                    spec.maxHealth = 80;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                }
                // ---- part 1: the screen itself ------------------------------------------------
                com.megacrit.cardcrawl.screens.select.HandCardSelectScreen h =
                        AbstractDungeon.handCardSelectScreen;
                String opened;
                java.util.List<java.util.List<AbstractCard>> opts;
                try {
                    // Exactly how RetainCardsAction opens it: the integer is the CAP, anyNumber is
                    // false, canPickZero is true, upTo is true.
                    h.open("S157", 2, false, true, false, false, true);
                    opened = Driver.selectionState();
                    opts = Driver.selectionOptions(8);
                } catch (Throwable t) {
                    Probe.check(false, "the up-to screen can be opened", String.valueOf(t));
                    return;
                }
                Log.info("  S157 up-to screen: " + opened + " optionSizes=" + optionSizes(opts));
                Probe.check(Driver.selectionKind() == Driver.SelectionKind.HAND,
                        "an up-to screen reads as a hand selection", opened);
                Probe.check(Driver.isAwaitingSelection(),
                        "and it counts as waiting for an answer (the count is the cap, not the answer)",
                        opened);
                boolean zero = false;
                int biggest = 0;
                for (int i = 0; i < opts.size(); i++) {
                    if (opts.get(i).isEmpty()) {
                        zero = true;
                    }
                    biggest = Math.max(biggest, opts.get(i).size());
                }
                Probe.check(zero, "keeping zero cards is one of the answers the search may pick",
                        optionSizes(opts));
                Probe.check(biggest >= 2, "and keeping the full cap is another", optionSizes(opts));
                Driver.clearSelection();

                // ---- part 2: it is reached by ending a turn ------------------------------------
                World w = World.captureLive();
                boolean installed = false;
                String after = null;
                int branches = 0;
                boolean stopsAtScreen = false;
                try {
                    w.install();
                    installed = true;
                    Driver.begin();
                    AbstractDungeon.player.powers.add(
                            new com.megacrit.cardcrawl.powers.RetainCardPower(AbstractDungeon.player, 2));
                    Driver.drain(4000, 800L);
                    Driver.endTurn();
                    after = Driver.selectionState();
                    branches = Driver.selectionOptions(8).size();
                    stopsAtScreen = Driver.isAwaitingSelection();
                    Driver.clearSelection();
                } catch (Throwable t) {
                    Probe.check(false, "the end-of-turn retain screen can be reached in the sandbox",
                            String.valueOf(t));
                } finally {
                    try {
                        Driver.end();
                    } catch (Throwable ignored) {
                        // the world restore below is what matters
                    }
                    if (installed) {
                        try {
                            w.uninstall();
                        } catch (Throwable ignored) {
                            // reported by the checks above
                        }
                    } else {
                        World.forceRestore();
                    }
                }
                Log.info("  S157 end of turn: " + after + " branches=" + branches);
                Probe.check(stopsAtScreen,
                        "ending the turn stops AT the retain screen instead of skipping past it", after);
                Probe.check(branches >= 2,
                        "so keep-0 and keep-N are different decisions for the search",
                        String.valueOf(branches));
            }
