        Probe.core("S168 a card that ends the turn still runs the player end-of-turn powers (B113)",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 454545L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Vault", "Strike_R", "Defend_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.Cultist"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Driver.drain(4000, 800L);
                World w = World.captureLive();
                boolean installed = false;
                int blockAfter = -1;
                int turnBefore = -1;
                int turnAfter = -1;
                int hpBefore = -1;
                int hpAfter = -1;
                try {
                    w.install();
                    installed = true;
                    // Metallicize: "at the end of your turn, gain 3 Block". If a card-driven end turn
                    // skips the player's end-of-turn powers, this block never arrives.
                    // Combust loses 1 HP at the end of the turn: a persistent marker, unlike block
                    // (which the new turn resets to 0). The Cultist buffs on its first turn, so any HP
                    // loss here can only come from the end-of-turn power.
                    // Arg order is (owner, hpLoss, damageAmount); this gate wants the 1 HP loss, so
                    // hpLoss=1. Swapping them made the power take 5 HP while the gate expected 1 --
                    // a gate bug, not a sandbox bug (the forced end turn DID run atEndOfTurn).
                    AbstractDungeon.player.addPower(new com.megacrit.cardcrawl.powers.CombustPower(
                            AbstractDungeon.player, 1, 5));
                    com.megacrit.cardcrawl.cards.AbstractCard bide = null;
                    for (int i = 0; i < AbstractDungeon.player.hand.size(); i++) {
                        com.megacrit.cardcrawl.cards.AbstractCard c = AbstractDungeon.player.hand.getNCardFromTop(i);
                        if (c.cardID != null && c.cardID.equals("Vault")) {
                            bide = c;
                            break;
                        }
                    }
                    hpBefore = AbstractDungeon.player.currentHealth;
                    turnBefore = com.megacrit.cardcrawl.actions.GameActionManager.turn;
                    if (bide != null) {
                        sts1solver.drive.Driver.play(bide, null, 0);
                    }
                    turnAfter = com.megacrit.cardcrawl.actions.GameActionManager.turn;
                    blockAfter = AbstractDungeon.player.currentBlock;
                    hpAfter = AbstractDungeon.player.currentHealth;
                } catch (Throwable t) {
                    Probe.check(false, "the forced-end-turn probe ran", String.valueOf(t));
                } finally {
                    try {
                        if (installed) {
                            w.uninstall();
                        }
                    } catch (Throwable t) {
                        World.forceRestore();
                    }
                }
                Log.info("  S168 forced end turn: hp " + hpBefore + " -> " + hpAfter + " turn "
                        + turnBefore + " -> " + turnAfter);
                Probe.check(hpAfter == hpBefore - 1,
                        "Combust still burns 1 HP when the card itself ends the turn",
                        "hp=" + hpBefore + "->" + hpAfter + " turn=" + turnBefore + "->" + turnAfter);
            }
        });
