        // B120 (m02336): a route that wins without losing HP and without drinking a potion cannot be
        // improved, so there is nothing left to search. The unsliced solver and the portfolio always
        // stopped there; the sliced session the panel runs only set the flag and kept expanding, which
        // is what the player saw as 预计无伤 sitting next to 计算中 for minutes.
        Probe.core("S175 a proven zero-damage win ends the sliced search at once (B120)", new Runnable(){
            @Override
            public void run() {
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 5175L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R",
                            "Defend_R", "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                    World root = World.captureLive();
                    boolean installed = false;
                    try {
                        root.install();
                        installed = true;
                        // +60 Strength: the opening Strike one-shots the Jaw Worm, so the search's
                        // first winning line costs no HP at all and must be treated as final.
                        AbstractDungeon.player.addPower(new com.megacrit.cardcrawl.powers.StrengthPower(
                                AbstractDungeon.player, 60));
                        root.readBack();
                    } finally {
                        if (installed) {
                            try {
                                root.uninstall();
                            } catch (Throwable t) {
                                World.forceRestore();
                            }
                        }
                    }
                    Solver.Session s = new Solver.Session(root, 24, 96, 120000L, 0, 0);
                    long deadline = System.currentTimeMillis() + 90000L;
                    while (!s.finished() && System.currentTimeMillis() < deadline) {
                        s.advance(20L);
                    }
                    Solver.Result r = s.result();
                    Log.info("  S175 proof stop: finished=" + s.finished() + " nodes=" + s.nodes()
                            + " reason=" + (r == null ? "-" : r.reason)
                            + " win=" + (r != null && r.win)
                            + " proven=" + (r != null && r.provenOptimal));
                    Probe.check(s.finished() && r != null && r.win && r.provenOptimal,
                            "the sliced search proves a zero-damage win",
                            "finished=" + s.finished() + " reason="
                                    + (r == null ? "null" : r.reason));
                    // Without the stop this run keeps walking the whole frontier (beam x layers);
                    // the bound is far above a one-action win and far below that.
                    Probe.check(s.nodes() < 400,
                            "a proven zero-damage win stops the search instead of draining the frontier",
                            "nodes=" + s.nodes());
                } catch (Throwable t) {
                    Probe.check(false, "the proof-stop gate ran", String.valueOf(t));
                }
            }
        });
