                    int t0 = 1;
                    try {
                        t0 = Math.max(1, GameActionManager.turn);
                    } catch (Throwable ignored) {
                        // outside a fight the number is cosmetic
                    }
                    // ---- the finished plan: 打击 / 结束回合 in turn t0, then 昏睡 skipped t0+1 ----
                    Gameplay.reset();
                    List<Action> actions = new ArrayList<Action>();
                    actions.add(Action.card(0, 0, 0, "", "打击", ""));
                    actions.add(Action.endTurn());
                    actions.add(Action.card(0, 0, 0, "", "打击", ""));
                    int[] turns = new int[]{t0, t0, t0 + 2};
                    int[] hp = new int[]{80, 80, 80};
                    Gameplay.installPlanForTest(Solver.resultForTest(actions, turns, hp), 0);
                    List<sts1solver.ui.RouteRow> rows = Gameplay.route();
                    StringBuilder labels = new StringBuilder();
                    for (int i = 0; i < rows.size(); ++i) {
                        labels.append(rows.get(i).label).append("[").append(rows.get(i).pills).append("] ");
                    }
                    boolean autoRow = rows.size() == 3
                            && rows.get(1).label.equals("第 " + (t0 + 1) + " 回合")
                            && rows.get(1).pills.size() == 1
                            && rows.get(1).pills.get(0).equals("结束回合（自动）");
                    Probe.check(autoRow, "a turn the plan skipped gets its own 自动结束 row", labels.toString());
                    Probe.check(rows.size() == 3 && rows.get(0).pills.size() == 2
                                    && rows.get(2).pills.size() == 1
                                    && rows.get(2).label.equals("第 " + (t0 + 2) + " 回合"),
                            "the skipped turn does not swallow the actions around it", labels.toString());
                    // ---- the preview: same rule, driven by Action.turnBefore/turnAfter ----
                    List<Action> path = new ArrayList<Action>();
                    Action p1 = Action.card(0, 0, 0, "", "打击", "");
                    p1.turnBefore = t0;
                    p1.turnAfter = t0;
                    path.add(p1);
                    Action p2 = Action.card(1, 0, 0, "", "昏睡", "");
                    p2.turnBefore = t0;
                    p2.turnAfter = t0;
                    path.add(p2);
                    Action p3 = Action.endTurn();
                    p3.turnBefore = t0;
                    p3.turnAfter = t0 + 1;
                    path.add(p3);
                    Action p4 = Action.card(0, 0, 0, "", "打击", "");
                    p4.turnBefore = t0 + 2;
                    p4.turnAfter = t0 + 2;
                    path.add(p4);
                    Gameplay.reset();
                    Gameplay.setPreviewPathForTest(path);
                    List<sts1solver.ui.RouteRow> pv = Gameplay.previewRouteForTest();
                    StringBuilder shown = new StringBuilder();
                    for (int i = 0; i < pv.size(); ++i) {
                        shown.append(pv.get(i).label).append("[").append(pv.get(i).pills).append("] ");
                    }
                    Probe.check(Gameplay.previewActive() && pv.size() == 3
                                    && pv.get(0).label.equals("第 " + t0 + " 回合")
                                    && pv.get(0).pills.size() == 3
                                    && pv.get(1).label.equals("第 " + (t0 + 1) + " 回合")
                                    && pv.get(1).pills.size() == 1
                                    && pv.get(1).pills.get(0).equals("结束回合（自动）")
                                    && pv.get(2).label.equals("第 " + (t0 + 2) + " 回合")
                                    && pv.get(2).pills.size() == 1,
                            "the preview draws the same skipped turn (B122)", shown.toString());
                    // The pills of a skipped row carry step -1: clicking one must not jump the plan.
