                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 6178L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R",
                            "Defend_R", "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    w = World.captureLive();
                    w.install();
                    installed = true;
                    Driver.begin();
                    final boolean[] fired = new boolean[1];
                    com.megacrit.cardcrawl.powers.AbstractPower presser =
                            new com.megacrit.cardcrawl.powers.AbstractPower(){
                        {
                            this.owner = AbstractDungeon.player;
                            this.ID = "sts1solver:PresserProbe";
                            this.name = "presser probe";
                            this.description = "presses end turn once";
                            this.type = PowerType.BUFF;
                            this.isTurnBased = false;
                            this.img = null;
                        }
                        @Override
                        public void atStartOfTurn() {
                            if (!fired[0]) {
                                fired[0] = true;
                                addToTop(new com.megacrit.cardcrawl.actions.watcher.PressEndTurnButtonAction());
                            }
                        }
                    };
                    AbstractDungeon.player.addPower(presser);
                    int before = GameActionManager.turn;
                    Driver.Drain d = Driver.endTurn();
                    boolean queued = AbstractDungeon.player.endTurnQueued;
                    boolean ending = AbstractDungeon.player.isEndingTurn;
                    Log.info("  S178 forced end turn: turn " + before + " -> " + GameActionManager.turn
                            + " endTurnQueued=" + queued + " isEndingTurn=" + ending
                            + " settled=" + d.settled + " timedOut=" + d.timedOut
                            + " steps=" + d.steps);
