        // B128 (user m05245): 烟雾弹 leaves the fight through the PLAYER's own animation
        // (AbstractPlayer.updateEscapeAnimation -> room.endBattle). Nothing in the sandbox ran that
        // frame, so the escape never finished: the fight stayed live, the search kept planning after
        // the bomb, and a line could drink a second potion, keep fighting and be reported as a WIN.
        Probe.core("S186 a smoke bomb ends the fight in the sandbox and nothing is planned after it (B128)",
                new Runnable(){
            @Override
            public void run() {
                boolean installed = false;
                World w = null;
                boolean driverOn = false;
                EscapePolicy.Mode mode = EscapePolicy.mode();
                try {
                    EscapePolicy.setMode(EscapePolicy.Mode.ALLOW);
                    // The escape branch is a potion branch: pin the belt on (S160 owns the player's
                    // switch), otherwise a banned belt turns this gate into "no plan at all".
                    sts1solver.search.Limits.forcePotionsForTest(Boolean.TRUE);
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9186L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                    AbstractDungeon.player.potions.set(0, PotionHelper.getPotion("SmokeBomb"));
                    // A fight no reachable line can survive: the only ending that is not a death is
                    // the escape, which is exactly the branch that used to keep going. The mutant
                    // state has to be written INSIDE the sandbox and read back (S181 pattern):
                    // powers added to the live monster are not part of the captured world.
                    w = World.captureLive();
                    w.install();
                    installed = true;
                    com.megacrit.cardcrawl.monsters.AbstractMonster worm =
                            AbstractDungeon.getMonsters().monsters.get(0);
                    worm.maxHealth = 400;
                    worm.currentHealth = 400;
                    // B129 (m05700): leaving now pays for the loot it forfeits, so fleeing is only
                    // the best move when the alternative is dying -- which is exactly what
                    // ONLY_IF_LETHAL promises. A fight that is merely unwinnable is not enough any
                    // more (before B129 the flat escape bonus made any fight look flee-worthy).
                    // The lethal clock is CombustPower's own end-of-turn self damage (S168 already
                    // proved the sandbox runs it): the escape is the only ending that is not a death.
                    AbstractDungeon.player.currentHealth = 5;
                    AbstractDungeon.player.addPower(
                            new com.megacrit.cardcrawl.powers.CombustPower(AbstractDungeon.player, 20, 1));
                    w.readBack();
                    World root = World.captureLive();
                    w.uninstall();
                    installed = false;
                    Driver.begin();
                    driverOn = true;

                    Solver.Session s = new Solver.Session(root, 12, 40, 15000L, 0, 0);
                    long deadline = System.currentTimeMillis() + 15000L;
                    while (!s.finished() && System.currentTimeMillis() < deadline) {
                        s.advance(20L);
                    }
                    Solver.Result r = s.result();
                    boolean isEscapeResult = r != null && r.escaped && !r.win && !r.plan.isEmpty();
                    int last = isEscapeResult ? r.plan.size() - 1 : -1;
                    boolean endsWithPotion = isEscapeResult && r.plan.get(last).action.isPotion();
                    boolean smoked = false;
                    boolean stillLeaving = false;
                    boolean overAfter = false;
                    int offeredAfter = -1;
                    if (isEscapeResult) {
                        World walk = root.fork();
                        boolean walkOn = false;
                        try {
                            walk.install();
                            walkOn = true;
                            for (int i = 0; i < r.plan.size(); i++) {
                                Solver.Step st = r.plan.get(i);
                                Legal.applyOrRefuse(st.action);
                                Solver.answerForReplay(st.action);
                            }
                            smoked = AbstractDungeon.getCurrRoom().smoked;
                            stillLeaving = AbstractDungeon.player.isEscaping
                                    || AbstractDungeon.player.escapeTimer != 0.0f;
                            overAfter = Driver.combatOver();
                            offeredAfter = Legal.actions().size();
                        } finally {
                            if (walkOn) {
                                walk.uninstall();
                            }
                        }
                    }
                    Log.info("  S186 escape: escaped=" + (r == null ? "none" : String.valueOf(r.escaped))
                            + " win=" + (r == null ? "none" : String.valueOf(r.win))
                            + " steps=" + (r == null ? -1 : r.plan.size())
                            + " lastPotion=" + endsWithPotion + " smoked=" + smoked
                            + " leaving=" + stillLeaving + " over=" + overAfter
                            + " offeredAfter=" + offeredAfter);
                    Probe.check(isEscapeResult,
                            "the search reports the smoke bomb line as an escape, not a win",
                            r == null ? "no result" : ("escaped=" + r.escaped + " win=" + r.win
                                    + " steps=" + r.plan.size() + " reason=" + r.reason));
                    Probe.check(endsWithPotion,
                            "the plan ends on the smoke bomb",
                            isEscapeResult ? r.plan.get(last).action.label : "no escape plan");
                    Probe.check(smoked, "the sandbox room is marked smoked", "");
                    Probe.check(!stillLeaving,
                            "the escape animation finished in the sandbox",
                            "escaping=" + AbstractDungeon.player.isEscaping);
                    Probe.check(overAfter, "the fight is over once the escape lands", "");
                    Probe.check(offeredAfter == 0,
                            "an escaped fight offers no action after it",
                            "offered " + offeredAfter);
                } catch (Throwable t) {
                    Probe.check(false, "the smoke bomb escape gate ran", String.valueOf(t));
                } finally {
                    EscapePolicy.setMode(mode);
                    try {
                        if (driverOn) {
                            Driver.end();
                        }
                    } catch (Throwable ignored) {
                    }
                    if (installed && w != null) {
                        try {
                            w.readBack();
                            w.uninstall();
                        } catch (Throwable t) {
                            World.forceRestore();
                        }
                    }
                }
            }
        });

        // B130 (m06143): a monster killed in the sandbox kept every power it had when it died. The
