                    AbstractDungeon.player.currentHealth = 1;
                    AbstractDungeon.player.damage(new com.megacrit.cardcrawl.cards.DamageInfo(
                            AbstractDungeon.player, 99,
                            com.megacrit.cardcrawl.cards.DamageInfo.DamageType.HP_LOSS));
                    Probe.check(AbstractDungeon.deathScreen != null,
                            "the simulated death really builds the game's death screen", "");
                    Probe.check(com.megacrit.cardcrawl.core.CardCrawlGame.metricData.damage_taken.size() >= 1,
                            "the death's record lands in the sandbox record, not the live one",
                            "records=" + com.megacrit.cardcrawl.core.CardCrawlGame.metricData.damage_taken.size());
                    w.readBack();
                    w.trimPresentation();
                    w.uninstall();
                    installed = false;
                    Probe.check(com.megacrit.cardcrawl.core.CardCrawlGame.metricData.damage_taken.size() == liveRecords,
                            "the live run's metric record did not grow",
                            "before=" + liveRecords + " after="
                                    + com.megacrit.cardcrawl.core.CardCrawlGame.metricData.damage_taken.size());
                    Probe.check(com.megacrit.cardcrawl.core.Settings.UPLOAD_DATA == uploadAtInstall,
                            "uploading is back to the setting the window opened with",
                            "opened=" + uploadAtInstall + " now=" + com.megacrit.cardcrawl.core.Settings.UPLOAD_DATA);
                    // A search reuses one world for many nodes; the record must not ride along.
