        // B157 (user m14819): no wall clock on a step. The 20 s deadline used to throw a step away
        // while it was still progressing (a fight that skips turns takes several) and the dropped
        // pending is what then made the plan look stale and vanish. The rule now is state-based:
        // the live turn reached the turn the sandbox measured -> done; past it -> the two worlds
        // disagree, so the autopilot stops and everything is kept for the player to read.
        Probe.core("S209 a step the live fight already passed stops the autopilot (B157)", new Runnable(){
            @Override
            public void run() {
                try {
                    Gameplay.reset();
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9209L;
                    spec.maxHealth = 80;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Gameplay.tick();
                    for (int i = 0; i < 400 && !Gameplay.engineSettledForTest(); i++) {
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.actionManager.update();
                    }
                    int live = GameActionManager.turn;
                    java.util.List<Action> acts = new java.util.ArrayList<Action>();
                    Action a = Action.card(0, 0, 0, "", "打击", "");
                    a.turnAfter = Math.max(0, live - 1);
                    acts.add(a);
                    Gameplay.installPlanForTest(Solver.resultForTest(acts, new int[]{live},
                            new int[]{80}), 0);
                    Gameplay.startPendingForTest(Gameplay.currentPlan().plan.get(0), live);
                    Gameplay.tick();
                    String st = Gameplay.planStateForTest();
                    Log.info("  S209 overshoot: live=" + live + " " + st);
                    Probe.check(st.indexOf("autopilot=false") >= 0,
                            "a step the live turn already passed stops the autopilot", st);
                    Probe.check(st.indexOf("plan=-") < 0,
                            "the plan is kept for the player to read", st);
                    Probe.check(st.indexOf("pending=1") >= 0,
                            "the pending step is kept (nothing is thrown away)", st);
                } catch (Throwable t) {
                    Probe.check(false, "the overshoot gate ran", String.valueOf(t));
                } finally {
                    Gameplay.clearPendingForTest();
                    Gameplay.reset();
                }
            }
        });
