                    root.install();
                    String screenAfter = "" + AbstractDungeon.screen + " up=" + AbstractDungeon.isScreenUp
                            + " retrieved=" + AbstractDungeon.handCardSelectScreen.wereCardsRetrieved
                            + " awaiting=" + Driver.isAwaitingSelection();
                    root.uninstall();
                    Log.info("  S215 root screen before=" + screenBefore + " after=" + screenAfter);
