        Probe.core("S216 a picker answer can reorder the hand like a click pair (B163)", new Runnable(){
            @Override
            public void run() {
                // user m16041: standing in front of a pick screen the player can click a card and then
                // click it again, which leaves it at the END of the hand -- and the hand order is
                // engine state (唐 plays a uniformly random hand card, end-of-turn discards run in hand
                // order). The answer must be able to say that, and "move one to the back, pick nothing"
                // must be a legal answer on an any-number screen.
                boolean installed = false;
                try {
                    Gameplay.reset();
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9216L;
                    spec.maxHealth = 80;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                    Gameplay.tick();
                    for (int i = 0; i < 400 && !Gameplay.engineSettledForTest(); i++) {
                        AbstractDungeon.actionManager.update();
                    }
                    World w = World.captureLive();
                    w.install();
                    installed = true;
                    Driver.begin();
                    ReorderPickProbeAction.resetForTest();
                    AbstractDungeon.actionManager.addToBottom(
                            new ReorderPickProbeAction(AbstractDungeon.player));
                    for (int i = 0; i < 200 && !Driver.isAwaitingSelection(); i++) {
                        AbstractDungeon.actionManager.update();
                    }
                    boolean open = Driver.isAwaitingSelection();
                    Probe.check(open, "a real hand picker is open",
                            "open=" + open + " kind=" + Driver.selectionKind());
                    List<AbstractCard> hand = new java.util.ArrayList<AbstractCard>(
                            AbstractDungeon.player.hand.group);
                    AbstractCard pick = null;
                    AbstractCard move = null;
                    for (int i = 0; i < hand.size(); i++) {
                        AbstractCard c = hand.get(i);
                        if ("Bash".equals(c.cardID)) {
                            pick = c;
                        } else if (move == null) {
                            move = c;
                        }
                    }
                    if (pick == null || move == null) {
                        Probe.check(false, "the hand has a card to pick and one to move",
                                "hand=" + hand.size());
                        return;
                    }
                    String pickUuid = pick.uuid == null ? "" : pick.uuid.toString();
                    String moveUuid = move.uuid == null ? "" : move.uuid.toString();
                    Action sel = Action.selectionWithMoves(pick.cardID, pick.name, pickUuid, "",
                            move.cardID, moveUuid, move.name, "HAND");
                    Probe.check(sel.isSelection() && sel.label.indexOf("\u6362\u5e8f") >= 0,
                            "the answer writes the reorder down as part of the step", sel.label);
                    Legal.applyOrRefuse(sel);
                    Driver.drain(4000, 800L);
                    List<AbstractCard> after = new java.util.ArrayList<AbstractCard>(
                            AbstractDungeon.player.hand.group);
                    String lastId = after.isEmpty() ? "-" : after.get(after.size() - 1).cardID;
                    Probe.check(pick.cardID.equals(ReorderPickProbeAction.picked),
                            "the waiting action reads exactly the card the answer picked",
                            "picked=" + ReorderPickProbeAction.picked + " want=" + pick.cardID);
                    Probe.check(move.cardID.equals(lastId),
                            "the moved card is the LAST card in the hand, as a click pair leaves it",
                            "last=" + lastId + " moved=" + move.cardID + " hand=" + after.size());
                    // Second round: pick NOTHING and move one card. "Keep nothing" used to be
                    // un-replayable because an empty answer was read as "not offered".
                    ReorderPickProbeAction.resetForTest();
                    AbstractDungeon.actionManager.addToBottom(
                            new ReorderPickProbeAction(AbstractDungeon.player));
                    for (int i = 0; i < 200 && !Driver.isAwaitingSelection(); i++) {
                        AbstractDungeon.actionManager.update();
                    }
                    boolean open2 = Driver.isAwaitingSelection();
                    List<AbstractCard> hand2 = new java.util.ArrayList<AbstractCard>(
                            AbstractDungeon.player.hand.group);
                    AbstractCard move2 = hand2.get(0);
                    String move2Uuid = move2.uuid == null ? "" : move2.uuid.toString();
                    Action none = Action.selectionWithMoves("", "", "", "", move2.cardID,
                            move2Uuid, move2.name, "HAND");
                    boolean applied = false;
                    try {
                        Legal.applyOrRefuse(none);
                        Driver.drain(4000, 800L);
                        applied = true;
                    } catch (Throwable t) {
                        Log.warn("  S216 empty answer refused: " + t);
                    }
                    List<AbstractCard> after2 = new java.util.ArrayList<AbstractCard>(
                            AbstractDungeon.player.hand.group);
                    String last2 = after2.isEmpty() ? "-" : after2.get(after2.size() - 1).cardID;
                    Probe.check(open2 && applied && ReorderPickProbeAction.picked.isEmpty()
                            && move2.cardID.equals(last2) && !Driver.isAwaitingSelection(),
                            "an empty answer plus a reorder is a legal answer",
                            "open=" + open2 + " applied=" + applied + " picked=["
                                    + ReorderPickProbeAction.picked + "] last=" + last2
                                    + " stillOpen=" + Driver.isAwaitingSelection());
                } catch (Throwable t) {
                    Probe.check(false, "the reorder gate ran", String.valueOf(t));
                } finally {
                    if (installed) {
                        try { World.forceRestore(); } catch (Throwable t) { }
                        Driver.end();
                    }
                    Driver.clearSelection();
                    Gameplay.clearPendingForTest();
                    Gameplay.reset();
                }
            }
        });
        Probe.core("S201 out-of-combat gains can be switched off entirely (B143)", new Runnable(){
            @Override
            public void run() {
                // The switch is one flag over every source. Pinned budgets, pinned flag: nothing here
                // touches settings.txt or depends on what the player saved.
                sts1solver.search.GrowthBook.overrideForTest(new int[]{30, 20, 5, 50, 10, 10});
                sts1solver.search.GrowthBook.Facts start =
                        new sts1solver.search.GrowthBook.Facts(80, 80, 0, 0, 0);
                sts1solver.search.GrowthBook.Facts grew =
                        new sts1solver.search.GrowthBook.Facts(90, 130, 1, 2, 0);
                sts1solver.search.GrowthBook.overrideCountingForTest(Boolean.TRUE);
                boolean onFlag = sts1solver.search.GrowthBook.counting();
                boolean onEnabled = sts1solver.search.GrowthBook.enabled();
                int onCredit = sts1solver.search.GrowthBook.credit(null, grew, start);
                String onLabel = sts1solver.search.GrowthBook.countingLabel();
                sts1solver.search.GrowthBook.overrideCountingForTest(Boolean.FALSE);
                boolean offFlag = sts1solver.search.GrowthBook.counting();
                boolean offEnabled = sts1solver.search.GrowthBook.enabled();
                int offCredit = sts1solver.search.GrowthBook.credit(null, grew, start);
                String offLabel = sts1solver.search.GrowthBook.countingLabel();
                sts1solver.search.GrowthBook.overrideCountingForTest(null);
                sts1solver.search.GrowthBook.overrideForTest(null);
                String report = "on=" + onFlag + "/" + onEnabled + "/" + onCredit + "/" + onLabel
                        + " off=" + offFlag + "/" + offEnabled + "/" + offCredit + "/" + offLabel;
                Log.info("  S201 growth switch: " + report);
                Probe.check(onFlag && onEnabled && onCredit > 0,
                        "with the switch on, the same growth is still priced", report);
                Probe.check(!offFlag && !offEnabled && offCredit == 0,
                        "with the switch off, nothing is priced and no source claims to be enabled",
                        report);
                Probe.check("局外: 计".equals(onLabel) && "局外: 不计".equals(offLabel),
                        "the panel label says which way the switch is", report);
                // The saved value is the player's: 2026-11-06 12:32 they turned it off in game, and
                // the old hard-coded "true" then made this gate depend on that setting. Compare what
                // counting() reports after invalidate() against the file itself.
                sts1solver.search.GrowthBook.invalidate();
                Boolean fileValue = null;
                try {
                    java.io.File f = new java.io.File(sts1solver.SolverMod.dir(), "settings.txt");
                    if (f.isFile()) {
                        java.util.List<String> lines = java.nio.file.Files.readAllLines(f.toPath(),
                                java.nio.charset.StandardCharsets.UTF_8);
                        for (int i = 0; i < lines.size(); i++) {
                            String line = lines.get(i).replace(String.valueOf((char) 0xFEFF), "").trim();
                            if (line.startsWith("growth.count=")) {
                                String v = line.substring("growth.count=".length()).trim();
                                fileValue = Boolean.valueOf(!"0".equals(v) && !"false".equalsIgnoreCase(v));
                            }
                        }
                    }
                } catch (Throwable t) {
                    Log.warn("  S201 could not read settings.txt: " + t);
                }
                boolean want = fileValue == null || fileValue.booleanValue();
                boolean got = sts1solver.search.GrowthBook.counting();
                Probe.check(got == want,
                        "after the test the switch is read from settings.txt again",
                        "file=" + want + " got=" + got);
            }
        });
        Probe.core("S202 gold is a direct score term at 80 points a coin (B146)", new Runnable(){
            @Override
            public void run() {
                // user m11490: one gold = 80 points, and spending gold costs the same. Measured against
                // the fight's opening gold, so gaining raises the score and spending lowers it.
                // user m11767: gold is an OUT-OF-COMBAT gain -- the panel switch owns it, so with
                // "局外: 不计" a coin must be worth nothing at all.
                boolean was = sts1solver.search.GrowthBook.counting();
                sts1solver.search.GrowthBook.overrideCountingForTest(Boolean.TRUE);
                int base = Solver.scoreOf(0, 0, false, false, 0, 0, 0, 0, 0, 0);
                int gained = Solver.scoreOf(0, 0, false, false, 0, 0, 0, 0, 0, 5);
                int spent = Solver.scoreOf(0, 0, false, false, 0, 0, 0, 0, 0, -3);
                // The same coin must not be paid twice: the growth book's gold budget is retired.
                int growthGold = sts1solver.search.GrowthBook.credit(null,
                        new sts1solver.search.GrowthBook.Facts(80, 130, 0, 0, 0),
                        new sts1solver.search.GrowthBook.Facts(80, 80, 0, 0, 0));
                // Switch off: the same deltas must change nothing.
                sts1solver.search.GrowthBook.overrideCountingForTest(Boolean.FALSE);
                int offBase = Solver.scoreOf(0, 0, false, false, 0, 0, 0, 0, 0, 0);
                int offGained = Solver.scoreOf(0, 0, false, false, 0, 0, 0, 0, 0, 5);
                int offSpent = Solver.scoreOf(0, 0, false, false, 0, 0, 0, 0, 0, -3);
                sts1solver.search.GrowthBook.overrideCountingForTest(null);
                sts1solver.search.GrowthBook.invalidate();
                String report = "gained=" + (gained - base) + " spent=" + (spent - base)
                        + " growthGold=" + growthGold + " offGained=" + (offGained - offBase)
                        + " offSpent=" + (offSpent - offBase) + " was=" + was;
                Log.info("  S202 gold score: " + report);
                Probe.check(gained - base == 5 * Solver.GOLD_POINTS,
                        "five gold gained is worth five times the coin rate", report);
                Probe.check(base - spent == 3 * Solver.GOLD_POINTS,
                        "spending three gold costs the same rate", report);
                Probe.check(growthGold == 0,
                        "the growth book no longer pays for gold, so one coin is never counted twice",
                        report);
                Probe.check(offBase - offSpent == 0 && offGained - offBase == 0,
                        "with \"局外: 不计\" gold is worth nothing (the switch owns it)", report);
            }
        });
