        Probe.step("S41 budget reads are cached (no settings.txt IO per panel refresh)",
                new Runnable(){
            @Override
            public void run() {
                java.io.File f = new java.io.File(sts1solver.SolverMod.dir(), "settings.txt");
                byte[] original = null;
                try {
                    if (f.isFile()) {
                        original = java.nio.file.Files.readAllBytes(f.toPath());
                    }
                } catch (Throwable ignored) {
                    // the gate still runs without a backup
                }
                try {
                    sts1solver.ui.Budget.write(37, 55555);
                    Probe.check(sts1solver.ui.Budget.seconds() == 37
                            && sts1solver.ui.Budget.nodes() == 55555,
                            "a write invalidates the cache and is read back", "");
                    java.nio.file.Files.write(f.toPath(), "deepSeconds=41\ndeepNodes=66666\n".getBytes("UTF-8"));
                    Probe.check(sts1solver.ui.Budget.seconds() == 37,
                            "a cached read does not touch the file every time",
                            String.valueOf(sts1solver.ui.Budget.seconds()));
                    sts1solver.ui.Budget.invalidate();
                    Probe.check(sts1solver.ui.Budget.seconds() == 41
                            && sts1solver.ui.Budget.nodes() == 66666,
                            "invalidating re-reads the file", "");
                } catch (Throwable t) {
                    Probe.check(false, "the budget cache gate ran", String.valueOf(t));
                } finally {
                    sts1solver.ui.Budget.invalidate();
                    try {
                        if (original != null) {
                            java.nio.file.Files.write(f.toPath(), original);
                        } else if (f.isFile()) {
                            f.delete();
                        }
                    } catch (Throwable ignored) {
                        // nothing else to restore
                    }
                }
            }
        });

        // B165 (user m17933/m17993): an open-screen card choice draws ONCE per activation. Before
        // this, DiscoveryAction generated its three choices at the top of every update and threw
        // them away after the opening frame (3-6 draws each), and the live pump ticks the manager up
        // to 8 times while the screen is up -- so live play burned ~42 draws the sandbox never
        // spent and every later random card/potion diverged. This gate owns both facts: the patch
        // generates on the opening frame only, and a whole activation spends nothing afterwards.
        Probe.core("S221 an open-screen card choice draws once per activation (B165)", new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9221L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Bash", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                World w = World.captureLive();
                boolean installed = false;
                sts1solver.mirror.DiscoveryRandom.resetForTest();
                try {
                    w.install();
                    installed = true;
                    Class<?> act = com.megacrit.cardcrawl.actions.unique.DiscoveryAction.class;
                    Object typed = new com.megacrit.cardcrawl.actions.unique.DiscoveryAction(
                            AbstractCard.CardType.ATTACK, 1);
                    Object colorless = new com.megacrit.cardcrawl.actions.unique.DiscoveryAction(true, 1);
                    java.lang.reflect.Method typedGen = sts1solver.reflect.Reflect.findMethod(act,
                            "generateCardChoices", AbstractCard.CardType.class);
                    java.lang.reflect.Method colorlessGen = sts1solver.reflect.Reflect.findMethod(act,
                            "generateColorlessCardChoices");
                    Probe.check(typedGen != null && colorlessGen != null,
                            "both private generators are reachable", "");
                    if (typedGen == null || colorlessGen == null) {
                        return;
                    }
                    int before1 = draws();
                    List<?> typedFirst = (List<?>) sts1solver.reflect.Reflect.invoke(typedGen, typed,
                            new Object[]{AbstractCard.CardType.ATTACK});
                    int after1 = draws();
                    sts1solver.reflect.Reflect.set(act, "duration", typed, Float.valueOf(0.2f));
                    List<?> typedLater = (List<?>) sts1solver.reflect.Reflect.invoke(typedGen, typed,
                            new Object[]{AbstractCard.CardType.ATTACK});
                    int after2 = draws();
                    sts1solver.reflect.Reflect.set(act, "duration", colorless, Float.valueOf(0.25f));
                    int before3 = draws();
                    List<?> colorlessFirst = (List<?>) sts1solver.reflect.Reflect.invoke(colorlessGen,
                            colorless, new Object[0]);
                    int after3 = draws();
                    sts1solver.reflect.Reflect.set(act, "duration", colorless, Float.valueOf(0.2f));
                    List<?> colorlessLater = (List<?>) sts1solver.reflect.Reflect.invoke(colorlessGen,
                            colorless, new Object[0]);
                    int after4 = draws();
                    Log.info("  S221 typed: first=" + size(typedFirst) + " draws=" + (after1 - before1)
                            + " later=" + size(typedLater) + " extraDraws=" + (after2 - after1)
                            + " | colorless: first=" + size(colorlessFirst) + " draws="
                            + (after3 - before3) + " later=" + size(colorlessLater)
                            + " extraDraws=" + (after4 - after3)
                            + " | generations=" + sts1solver.mirror.DiscoveryRandom.count());
                    Probe.check(size(typedFirst) == 3 && after1 - before1 >= 3,
                            "the opening frame of a typed choice generates three cards and draws",
                            "cards=" + size(typedFirst) + " draws=" + (after1 - before1));
                    Probe.check(size(typedLater) == 0 && after2 == after1,
                            "a later frame of the same activation draws nothing",
                            "cards=" + size(typedLater) + " draws=" + (after2 - after1));
                    Probe.check(size(colorlessFirst) == 3 && after3 - before3 >= 3,
                            "the opening frame of a colorless choice generates three cards and draws",
                            "cards=" + size(colorlessFirst) + " draws=" + (after3 - before3));
                    Probe.check(size(colorlessLater) == 0 && after4 == after3,
                            "a later frame of the colorless choice draws nothing",
                            "cards=" + size(colorlessLater) + " draws=" + (after4 - after3));
                    Probe.check(sts1solver.mirror.DiscoveryRandom.count() == 2,
                            "each activation counted exactly one normalization",
                            "generations=" + sts1solver.mirror.DiscoveryRandom.count());
                } catch (Throwable t) {
                    Probe.check(false, "S221 ran without throwing", String.valueOf(t));
                } finally {
                    try {
                        if (installed) {
                            w.readBack();
                            w.uninstall();
                        }
                    } catch (Throwable ignored) {
                        World.forceRestore();
                    }
                }
            }

            private int draws() {
                int n = 0;
                if (AbstractDungeon.cardRandomRng != null) {
                    n += AbstractDungeon.cardRandomRng.counter;
                }
                if (AbstractDungeon.miscRng != null) {
                    n += AbstractDungeon.miscRng.counter;
                }
                return n;
            }

            private int size(List<?> list) {
                return list == null ? -1 : list.size();
            }
        });

        // The same defect one level up: a whole activation (opening frame + the frames the live pump
        // spends while the screen stays up) must show the SAME three cards and spend no extra draws.
        // This is the number that used to be ~42.
        Probe.core("S222 a Discovery screen keeps its three cards and spends no draws afterwards (B165)",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9222L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Bash", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                World w = World.captureLive();
                boolean installed = false;
                try {
                    w.install();
                    installed = true;
                    Driver.begin();
                    com.megacrit.cardcrawl.actions.unique.DiscoveryAction act =
                            new com.megacrit.cardcrawl.actions.unique.DiscoveryAction(true, 1);
                    int before = draws();
                    act.update();
                    int opened = draws();
                    boolean screen = AbstractDungeon.isScreenUp
                            && AbstractDungeon.screen == AbstractDungeon.CurrentScreen.CARD_REWARD;
                    List<String> first = shownIds();
                    for (int i = 0; i < 10; i++) {
                        act.update();
                    }
                    int after = draws();
                    List<String> later = shownIds();
                    Log.info("  S222 screenUp=" + screen + " openingDraws=" + (opened - before)
                            + " extraDraws=" + (after - opened) + " cards=" + first + " same="
                            + first.equals(later));
                    Probe.check(screen, "the activation opened the card-reward screen",
                            "screen=" + AbstractDungeon.screen);
                    Probe.check(opened - before >= 3,
                            "the opening frame spent the draws it needs",
                            "draws=" + (opened - before));
                    Probe.check(first.size() == 3, "three cards are on the screen", "cards=" + first);
                    Probe.check(after == opened,
                            "ten further frames spent zero draws (before this: three per frame)",
                            "extraDraws=" + (after - opened));
                    Probe.check(first.equals(later),
                            "the ten frames kept showing the same three cards", "later=" + later);
                    // The panel mark rides on the step itself: every copy made while the search
                    // carries the decision forward has to keep it, or the plan prints the '*' on
                    // some branches and not on others.
                    sts1solver.search.Action marked = sts1solver.search.Action.card(0, 0, 0, "Strike_R");
                    marked.rngNormalized = true;
                    Probe.check(marked.withChoice("a", "a").rngNormalized
                            && marked.withCardUuid("u").rngNormalized
                            && marked.withCardPrint("p").rngNormalized,
                            "the normalization mark travels with every copy of a step", "");
                } catch (Throwable t) {
                    Probe.check(false, "S222 ran without throwing", String.valueOf(t));
                } finally {
                    Driver.end();
                    try {
                        if (installed) {
                            w.readBack();
                            w.uninstall();
                        }
                    } catch (Throwable ignored) {
                        World.forceRestore();
                    }
                }
            }

            private int draws() {
                int n = 0;
                if (AbstractDungeon.cardRandomRng != null) {
                    n += AbstractDungeon.cardRandomRng.counter;
                }
                if (AbstractDungeon.miscRng != null) {
                    n += AbstractDungeon.miscRng.counter;
                }
                return n;
            }

            private List<String> shownIds() {
                List<String> out = new ArrayList<String>();
                if (AbstractDungeon.cardRewardScreen != null
                        && AbstractDungeon.cardRewardScreen.rewardGroup != null) {
                    for (AbstractCard c : AbstractDungeon.cardRewardScreen.rewardGroup) {
                        out.add(c == null ? "null" : c.cardID);
                    }
                }
                return out;
            }
        });

        // Flipping an intent badge is presentation, not state -- but the search moved the live one:
        // every won node pumps room.update() (PostCombatLoot) under the delta proxy, and BobEffect
        // was shared by ClonePolicy, so ONE pump teleported the LIVE badge by FAST_DELTA * speed =
        // 20 * 4 = 80 rad (~12.7 bobs). The user reported it as "the intent number bobs faster while
        // it is calculating" (m18398, B166).
        Probe.core("S223 a simulated frame does not move the live intent badge (B166)",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9223L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Defend_R"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                Object liveMonster = AbstractDungeon.getMonsters().monsters.get(0);
                World w = World.captureLive();
                boolean installed = false;
                try {
                    w.install();
                    installed = true;
                    Object sandboxMonster = AbstractDungeon.getMonsters().monsters.get(0);
                    Object liveBob = bobOf(liveMonster);
                    Object sandboxBob = bobOf(sandboxMonster);
                    Probe.check(liveBob != null && sandboxBob != null,
                            "both monsters carry a bobEffect",
                            "live=" + liveBob + " sandbox=" + sandboxBob);
                    Probe.check(liveBob != sandboxBob,
                            "the sandbox monster has its own bobEffect (sharing it let every won node"
                                    + " teleport the live intent badge)",
                            "shared=" + (liveBob == sandboxBob));
                    float liveBefore = timerOf(liveBob);
                    float sandboxBefore = timerOf(sandboxBob);
                    Driver.begin();
                    for (int i = 0; i < 8; i++) {
                        AbstractDungeon.getMonsters().update();
                    }
                    float sandboxAfter = timerOf(sandboxBob);
                    float liveAfter = timerOf(liveBob);
                    Log.info("  S223 sandboxAdvance=" + (sandboxAfter - sandboxBefore)
                            + " liveAdvance=" + (liveAfter - liveBefore));
                    Probe.check(bits(sandboxAfter) != bits(sandboxBefore),
                            "the eight simulated frames moved the SANDBOX badge",
                            "advance=" + (sandboxAfter - sandboxBefore));
                    Probe.check(bits(liveAfter) == bits(liveBefore),
                            "the eight simulated frames left the LIVE badge exactly where it was",
                            "live " + liveBefore + " -> " + liveAfter);
                } catch (Throwable t) {
                    Probe.check(false, "S223 ran without throwing", String.valueOf(t));
                } finally {
                    Driver.end();
                    try {
                        if (installed) {
                            w.readBack();
                            w.uninstall();
                        }
                    } catch (Throwable ignored) {
                        World.forceRestore();
                    }
                }
            }

            private Object bobOf(Object monster) {
                return sts1solver.reflect.Reflect.get(
                        sts1solver.reflect.Reflect.find(
                                com.megacrit.cardcrawl.monsters.AbstractMonster.class, "bobEffect"),
                        monster);
            }

            private float timerOf(Object bob) {
                Object v = sts1solver.reflect.Reflect.get(
                        sts1solver.reflect.Reflect.find(
                                com.megacrit.cardcrawl.vfx.BobEffect.class, "timer"),
                        bob);
                return v instanceof Number ? ((Number) v).floatValue() : 0f;
            }

            private int bits(float f) {
                return Float.floatToIntBits(f);
            }
        });

