        // The key used the raw digest, which carries the action manager's mid-flight fields. The
        // same board reloaded one frame later therefore had a different key -- a reload could not
        // reuse the plan even when nothing had moved (B167).
        Probe.core("S225 the plan cache keys two frames of one position the same (B167)",
                new Runnable(){
            @Override
            public void run() {
                String busy = "t=3 ph=EXECUTING_ACTIONS q=3/1/0 use=1 end=0 | P hp=70/80 b=0 e=3"
                        + " st=- pw=- rl=- or=- H=Strike_R D=Defend_R X= E=";
                String idle = "t=3 ph=WAITING_ON_USER q=0/0/0 use=0 end=0 | P hp=70/80 b=0 e=3"
                        + " st=- pw=- rl=- or=- H=Strike_R D=Defend_R X= E=";
                String hurt = idle.replace("hp=70/80", "hp=69/80");
                String k1 = sts1solver.search.PlanCache.key(busy, 0, "keep", "vanilla");
                String k2 = sts1solver.search.PlanCache.key(idle, 0, "keep", "vanilla");
                String k3 = sts1solver.search.PlanCache.key(hurt, 0, "keep", "vanilla");
                Log.info("  S225 stableBusy=[" + sts1solver.mirror.Digest.stable(busy)
                        + "] stableIdle=[" + sts1solver.mirror.Digest.stable(idle) + "]");
                Probe.check(k1.equals(k2), "a reload one frame later keys the same",
                        "k1=" + k1 + " k2=" + k2);
                Probe.check(!k1.equals(k3), "a different position keys differently",
                        "k1=" + k1 + " k3=" + k3);
            }
        });

        // submit() answered a selection step by calling resolveSelectionLive directly, around the
        // chain bookkeeping. The screen was answered, but the plan's answer stayed pending: every
        // later step warned "the rest were never used", and a later unrelated screen could be
        // answered with this step's cards (B167, user m18895).
        Probe.core("S226 a selection step consumes its planned answer (B167)",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9226L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                sts1solver.Gameplay.reset();
                World w = World.captureLive();
                boolean installed = false;
                try {
                    w.install();
                    installed = true;
                    Driver.begin();
                    Driver.resetOrphans();
                    com.megacrit.cardcrawl.characters.AbstractPlayer p =
                            com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                    while (!p.hand.group.isEmpty()) {
                        p.discardPile.addToTop(p.hand.group.remove(0));
                    }
                    while (p.discardPile.size() < 3 && !p.drawPile.group.isEmpty()) {
                        p.drawPile.moveToDiscardPile(
                                p.drawPile.group.get(p.drawPile.group.size() - 1));
                    }
                    com.megacrit.cardcrawl.cards.AbstractCard headbutt =
                            com.megacrit.cardcrawl.helpers.CardLibrary.getCopy("Headbutt");
                    p.hand.group.add(headbutt);
                    p.hand.refreshHandLayout();
                    com.megacrit.cardcrawl.ui.panels.EnergyPanel.setEnergy(3);
                    Driver.play(headbutt, com.megacrit.cardcrawl.dungeons.AbstractDungeon
                            .getMonsters().monsters.get(0), 1);
                    boolean opened = Driver.isAwaitingSelection();
                    sts1solver.search.Action sel = sts1solver.search.Action.selectionWithMoves(
                            "Strike_R", "", "", "", "", "", "", "GRID");
                    boolean answered = opened && sts1solver.Gameplay.answerSelectionForTest(sel);
                    String pending = sts1solver.Gameplay.pendingChoiceForTest();
                    Log.info("  S226 opened=" + opened + " answered=" + answered + " pending=["
                            + pending + "] consumed=" + Driver.lastSelectionConsumed());
                    Probe.check(opened, "the Headbutt play opened a picker", "opened=" + opened);
                    Probe.check(answered, "the selection step answered it", "answered=" + answered);
                    Probe.check(pending.isEmpty(),
                            "the step's answer is CONSUMED, not left pending for a later screen",
                            "pending=[" + pending + "]");
                } catch (Throwable t) {
                    Probe.check(false, "S226 ran without throwing", String.valueOf(t));
                } finally {
                    try {
                        if (Driver.isAwaitingSelection()) {
                            Driver.clearSelection();
                        }
                    } catch (Throwable ignored) {
                        // the world is restored below
                    }
                    Driver.end();
                    try {
                        if (installed) {
                            w.readBack();
                            w.uninstall();
                        }
                    } catch (Throwable ignored) {
                        World.forceRestore();
                    }
                }
            }
        });

        // B168 (user m18398 / m19477): a sandbox window must not DISPATCH the engine's presentation
        // events. YuAi starts its half-health effect off healthBarUpdatedEvent, and the search
        // evaluates thousands of nodes on the render thread, so every window that crossed half
        // health ran that listener again -- the measured 500-600 ms frames. The gate pins the
        // mechanism, not the mod: a damage() still lands, but the timer the event sets stays put;
        // a direct call still works (only the dispatch is muted).
        Probe.core("S227 a sandbox window does not dispatch healthBarUpdatedEvent (B168)",
                new Runnable(){
            @Override
            public void run() {
                int sites = sts1solver.mirror.PresentationQuiet.patchedSites();
                Log.info("  S227 patchedSites=" + sites + " expected="
                        + sts1solver.mirror.PresentationQuiet.EXPECTED_SITES);
                Probe.check(sites == sts1solver.mirror.PresentationQuiet.EXPECTED_SITES,
                        "the load-time rewrite replaced every healthBarUpdatedEvent call site",
                        "patchedSites=" + sites);
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 9227L;
                spec.maxHealth = 80;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                sts1solver.Gameplay.reset();
                World w = World.captureLive();
                boolean installed = false;
                try {
                    java.lang.reflect.Field timer = sts1solver.reflect.Reflect.find(
                            com.megacrit.cardcrawl.core.AbstractCreature.class,
                            "healthBarAnimTimer");
                    w.install();
                    installed = true;
                    boolean quiet = sts1solver.mirror.PresentationQuiet.quiet();
                    Probe.check(quiet, "the window reports itself quiet", "quiet=" + quiet);
                    com.megacrit.cardcrawl.characters.AbstractPlayer p =
                            com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                    int hpBefore = p.currentHealth;
                    sts1solver.reflect.Reflect.set(timer, p, Float.valueOf(0.0f));
                    p.damage(new com.megacrit.cardcrawl.cards.DamageInfo(p, 3,
                            com.megacrit.cardcrawl.cards.DamageInfo.DamageType.NORMAL));
                    int hpAfter = p.currentHealth;
                    float afterDamage =
                            ((Float) sts1solver.reflect.Reflect.get(timer, p)).floatValue();
                    p.healthBarUpdatedEvent();
                    float afterDirect =
                            ((Float) sts1solver.reflect.Reflect.get(timer, p)).floatValue();
                    Log.info("  S227 hp=" + hpBefore + "->" + hpAfter + " timerAfterDamage="
                            + afterDamage + " timerAfterDirect=" + afterDirect);
                    Probe.check(hpAfter < hpBefore,
                            "the simulated damage still lands (only the dispatch is muted)",
                            "hp=" + hpBefore + "->" + hpAfter);
                    Probe.check(Float.floatToIntBits(afterDamage) == Float.floatToIntBits(0.0f),
                            "the muted dispatch left the health-bar timer alone",
                            "timerAfterDamage=" + afterDamage);
                    Probe.check(Float.floatToIntBits(afterDirect) == Float.floatToIntBits(1.2f),
                            "a direct call still runs (the method itself is untouched)",
                            "timerAfterDirect=" + afterDirect);
                } catch (Throwable t) {
                    Probe.check(false, "S227 ran without throwing", String.valueOf(t));
                } finally {
                    try {
                        if (installed) {
                            w.readBack();
                            w.uninstall();
                        }
                    } catch (Throwable ignored) {
                        World.forceRestore();
                    }
                }
                boolean quietAfter = sts1solver.mirror.PresentationQuiet.quiet();
                Probe.check(!quietAfter, "the live game is not quiet once the window is gone",
                        "quiet=" + quietAfter);
            }
        });

        // B169 (user m20148): a window is not the only writer of a live mod static. The measured case
        // is an audio callback thread clearing a mod's "current clip" field while a window happened to
        // be open. Putting the snapshot back handed the mod a reference to an already-closed clip, so
        // its isPlaying() answered true forever and the music never came back. A release cannot leak a
        // sandbox object into the live game, so it is left as it is -- everything else is still put
        // back (the leak this watch exists for, P2-62).
        Probe.core("S228 a window that only releases a live static leaves it released (B169)",
                new Runnable(){
            @Override
            public void run() {
                if (AbstractDungeon.player == null) {
                    Synthetic.Spec boot = new Synthetic.Spec();
                    boot.seed = 9228L;
                    boot.maxHealth = 80;
                    boot.deck = new String[]{"Strike_R", "Defend_R"};
                    boot.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(boot, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                }
                java.lang.reflect.Field fReleased;
                java.lang.reflect.Field fLeaked;
                try {
                    fReleased = Probe.class.getDeclaredField("S228_RELEASED");
                    fReleased.setAccessible(true);
                    fLeaked = Probe.class.getDeclaredField("S228_LEAKED");
                    fLeaked.setAccessible(true);
                } catch (Throwable t) {
                    Probe.check(false, "the gate can reach its own statics", String.valueOf(t));
                    return;
                }
                sts1solver.mirror.StaticWatch.resetForTest();
                sts1solver.mirror.StaticWatch.watchForTest(fReleased);
                sts1solver.mirror.StaticWatch.watchForTest(fLeaked);
                S228_RELEASED = "live";
                S228_LEAKED = null;
                boolean installed = false;
                try {
                    World w = World.captureLive();
                    w.install();
                    installed = true;
                    // A callback thread releasing the field: this is what the audio LineListener does.
                    S228_RELEASED = null;
                    // And the shape the watch must still catch: the sandbox object left in a live field.
                    S228_LEAKED = new Object();
                    w.uninstall();
                    installed = false;
                    java.util.List<String> written = sts1solver.mirror.StaticWatch.writtenForTest();
                    Log.info("  S228 released=" + S228_RELEASED + " leaked=" + S228_LEAKED
                            + " putBack=" + (S228_LEAKED == null) + " written=" + written
                            + " leftAlone=" + sts1solver.mirror.StaticWatch.releasedForTest());
                    Probe.check(S228_RELEASED == null,
                            "a reference a window only released is left released, not put back",
                            "released=" + S228_RELEASED);
                    Probe.check(S228_LEAKED == null,
                            "a sandbox object left in a live static is still put back",
                            "leaked=" + S228_LEAKED);
                    Probe.check(!written.contains("sts1solver.probe.Probe#S228_RELEASED"),
                            "a release is not reported as a sandbox write",
                            written.toString());
                    Probe.check(written.contains("sts1solver.probe.Probe#S228_LEAKED"),
                            "the real leak is still named",
                            written.toString());
                    Probe.check(sts1solver.mirror.StaticWatch.releasedForTest() == 1,
                            "the window counted exactly one release",
                            String.valueOf(sts1solver.mirror.StaticWatch.releasedForTest()));
                } catch (Throwable t) {
                    Probe.check(false, "S228 ran without throwing", String.valueOf(t));
                } finally {
                    try {
                        if (installed) {
                            World.forceRestore();
                        }
                    } catch (Throwable ignored) {
                        // the live game is restored as far as it can be
                    }
                    S228_RELEASED = "live";
                    S228_LEAKED = null;
                    sts1solver.mirror.StaticWatch.resetForTest();
                }
            }
        });

        // B170 (user m20574): the one mod static big enough to matter. YuAiMusic keeps its whole 8 MB
        // wav in a static byte[], which ModStatics hands to this watch. An element-by-element snapshot
        // boxes 8,000,000 elements into an Object[] and pays the same walk again on compare, on every
        // sampled window (installs 1-4, then every 128th): that is the 500-700 ms frame the player sees
        // only when that mod is installed. A big array has to be copied with System.arraycopy and
        // compared with a primitive Arrays.equals, and a write deep inside it must still be put back.
        Probe.core("S229 a big mod array is snapshotted without boxing every element (B170)",
                new Runnable(){
            @Override
            public void run() {
                try {
                    java.lang.reflect.Field fBig = Probe.class.getDeclaredField("S229_BIG");
                    fBig.setAccessible(true);
                    S229_BIG = new byte[8000000];
                    sts1solver.mirror.StaticWatch.resetForTest();
                    sts1solver.mirror.StaticWatch.watchForTest(fBig);
                    // Three windows: the first one pays the class initialisation and the cold copy,
                    // the later ones are what a search actually repeats (installs 1-4, then every
                    // 128th). A frame spike only matters if it repeats, so the warm windows are what
                    // this gate holds to a budget; the first one is reported next to them.
                    long[] snapshotMs = new long[3];
                    long[] compareMs = new long[3];
                    String shape = "";
                    for (int i = 0; i < 3; i++) {
                        long t0 = System.nanoTime();
                        sts1solver.mirror.StaticWatch.afterInstall();
                        long t1 = System.nanoTime();
                        shape = sts1solver.mirror.StaticWatch.shapeForTest(fBig);
                        S229_BIG[4000000] = 42;
                        sts1solver.mirror.StaticWatch.beforeUninstall();
                        long t2 = System.nanoTime();
                        snapshotMs[i] = (t1 - t0) / 1000000L;
                        compareMs[i] = (t2 - t1) / 1000000L;
                    }
                    java.util.List<String> written =
                            sts1solver.mirror.StaticWatch.writtenForTest();
                    long warmSnapshot = Math.min(snapshotMs[1], snapshotMs[2]);
                    long warmCompare = Math.min(compareMs[1], compareMs[2]);
                    Log.info("  S229 shape=" + shape + " snapshotMs="
                            + java.util.Arrays.toString(snapshotMs) + " compareMs="
                            + java.util.Arrays.toString(compareMs) + " element4000000="
                            + S229_BIG[4000000] + " written=" + written);
                    Probe.check("large array".equals(shape),
                            "a big array is snapshotted as one array, not an Object[] of elements",
                            "shape=" + shape);
                    Probe.check(written.contains("sts1solver.probe.Probe#S229_BIG"),
                            "a write deep inside the big array is still caught", written.toString());
                    Probe.check(S229_BIG[4000000] == 0,
                            "the written element is put back", "v=" + S229_BIG[4000000]);
                    Probe.check(warmSnapshot + warmCompare < 150L,
                            "a repeated (warm) window over the big array stays under 150 ms",
                            "snapshot=" + warmSnapshot + "ms compare=" + warmCompare + "ms");
                } catch (Throwable t) {
                    Probe.check(false, "S229 ran without throwing", String.valueOf(t));
                } finally {
                    S229_BIG = new byte[16];
                    sts1solver.mirror.StaticWatch.resetForTest();
                }
            }
        });

        // B187 (user m01082/m01098): B185 let the window really run mod audio and then closed what
        // the window left behind. That cleanup wrote an already-closed live clip back into the mod
        // field, and the next window's stop()->flush() killed the JVM inside
        // DirectAudioDevice.nFlush (hs_err_pid17280, 2026-11-15 21:22:02). The contract is now
        // inverted: the window parks an inert stand-in (SandboxClip) in every clip-typed mod static,
        // so a mod's play() early-outs and no line is opened at all; uninstall puts the live
        // reference back only when its line is still open, and writes null when it is not.
        // Clip proxies pin that contract without a device -- they prove nothing about the native
        // layer, which is what S257 is for (rule I1).
        Probe.core("S255 a window parks a stand-in clip instead of running mod audio (B187)",
                new Runnable(){
            @Override
            public void run() {
                java.lang.reflect.Field fLive;
                java.lang.reflect.Field fSandbox;
                try {
                    fLive = Probe.class.getDeclaredField("S255_LIVE");
                    fLive.setAccessible(true);
                    fSandbox = Probe.class.getDeclaredField("S255_SANDBOX");
                    fSandbox.setAccessible(true);
                } catch (Throwable t) {
                    Probe.check(false, "S255 can reach its own statics", String.valueOf(t));
                    return;
                }
                sts1solver.mirror.AudioQuiet.resetForTest();
                sts1solver.mirror.StaticWatch.resetForTest();
                sts1solver.mirror.AudioQuiet.watchForTest(fLive);
                sts1solver.mirror.AudioQuiet.watchForTest(fSandbox);
                sts1solver.mirror.StaticWatch.watchForTest(fLive);
                S255Clip live = new S255Clip("live");
                javax.sound.sampled.Clip liveClip = S255Clip.proxy(live);
                live.running = true;
                S255_LIVE = liveClip;
                S255_SANDBOX = null;
                try {
                    // ---- Window A: the stand-in contract ------------------------------------
                    int swapped0 = sts1solver.mirror.AudioQuiet.swappedForTest();
                    int closed0 = sts1solver.mirror.AudioQuiet.closedForTest();
                    int cleared0 = sts1solver.mirror.AudioQuiet.clearedForTest();
                    int putBack0 = sts1solver.mirror.AudioQuiet.putBackForTest();
                    World a = World.captureLive();
                    a.install();
                    Object parked = S255_LIVE;
                    Probe.check(sts1solver.mirror.SandboxClip.isSandbox(parked),
                            "the window parks the inert stand-in in the clip static",
                            String.valueOf(parked));
                    Probe.check(parked != liveClip,
                            "the stand-in is not the live clip", String.valueOf(parked));
                    Probe.check(!live.closed && live.running,
                            "the live clip is not touched by install",
                            "closed=" + live.closed + " running=" + live.running);
                    // This is exactly YuAiMusic.play()'s first instruction: a non-null field means
                    // "already playing", so the real AudioSystem.getClip() is never reached.
                    Probe.check(S255_LIVE != null,
                            "a mod's play() early-outs on the stand-in and opens no line",
                            String.valueOf(S255_LIVE));
                    boolean standUp = false;
                    if (sts1solver.mirror.SandboxClip.isSandbox(S255_LIVE)) {
                        javax.sound.sampled.Clip stand = (javax.sound.sampled.Clip) S255_LIVE;
                        stand.stop();
                        stand.flush();
                        stand.close();
                        standUp = stand.isOpen() && stand.isRunning();
                        Probe.check(stand.getFramePosition() == 0
                                        && stand.getMicrosecondPosition() == 0L,
                                "the stand-in reports a zero position",
                                stand.getFramePosition() + " frame(s)");
                        Probe.check(stand.getFormat() != null,
                                "the stand-in reports a usable audio format",
                                String.valueOf(stand.getFormat()));
                        Probe.check(stand.getControl(javax.sound.sampled.FloatControl.Type.MASTER_GAIN)
                                        instanceof javax.sound.sampled.FloatControl,
                                "the stand-in answers a gain control a mod can cast",
                                String.valueOf(stand.getControl(
                                        javax.sound.sampled.FloatControl.Type.MASTER_GAIN)));
                    } else {
                        Probe.check(false, "the stand-in is a SandboxClip", String.valueOf(S255_LIVE));
                    }
                    Probe.check(!live.closed && live.running,
                            "stop/flush/close on the stand-in never reach the live clip",
                            "closed=" + live.closed + " running=" + live.running);
                    Probe.check(standUp,
                            "the stand-in still reports open/running after close()",
                            String.valueOf(standUp));
                    // The watch samples in afterInstall(), which now runs BEFORE the swap: it must
                    // have recorded the live clip, or uninstall would write the stand-in into the
                    // live game.
                    Probe.check(sts1solver.mirror.StaticWatch.snapshotValueForTest(fLive) == liveClip,
                            "StaticWatch snapshotted the live clip, not the stand-in (ordering)",
                            String.valueOf(
                                    sts1solver.mirror.StaticWatch.snapshotValueForTest(fLive)));
                    // A clip the window opened for itself must still be closed (B185's half of the
                    // mechanism stays).
                    S255Clip leaked = new S255Clip("leaked");
                    leaked.running = true;
                    S255_SANDBOX = S255Clip.proxy(leaked);
                    a.uninstall();
                    Log.info("  S255 A parked=" + parked + " leakedClosed=" + leaked.closed
                            + " liveClosed=" + live.closed + " liveRestored=" + (S255_LIVE == liveClip)
                            + " sandboxCleared=" + (S255_SANDBOX == null) + " report="
                            + sts1solver.mirror.AudioQuiet.report());
                    Probe.check(leaked.closed,
                            "a clip the window opened itself is closed", "closed=" + leaked.closed);
                    Probe.check(S255_LIVE == liveClip,
                            "the live reference is put back", String.valueOf(S255_LIVE));
                    Probe.check(S255_SANDBOX == null,
                            "a field the window filled is put back to null",
                            String.valueOf(S255_SANDBOX));
                    Probe.check(!live.closed && live.running,
                            "the live clip survived the window untouched",
                            "closed=" + live.closed + " running=" + live.running);
                    Probe.check(sts1solver.mirror.AudioQuiet.swappedForTest() - swapped0 >= 2,
                            "both watched fields were parked on the stand-in",
                            String.valueOf(
                                    sts1solver.mirror.AudioQuiet.swappedForTest() - swapped0));
                    Probe.check(sts1solver.mirror.AudioQuiet.closedForTest() - closed0 == 1,
                            "the window counts exactly the clip it opened",
                            String.valueOf(
                                    sts1solver.mirror.AudioQuiet.closedForTest() - closed0));
                    Probe.check(sts1solver.mirror.AudioQuiet.putBackForTest() - putBack0 >= 1,
                            "the live reference was put back",
                            String.valueOf(
                                    sts1solver.mirror.AudioQuiet.putBackForTest() - putBack0));
                    Probe.check(sts1solver.mirror.AudioQuiet.clearedForTest() - cleared0 >= 1,
                            "the field the window filled is counted as cleared",
                            String.valueOf(
                                    sts1solver.mirror.AudioQuiet.clearedForTest() - cleared0));
                    Probe.check(!sts1solver.mirror.StaticWatch.writtenForTest().contains(
                                    "sts1solver.probe.Probe#S255_LIVE"),
                            "the static watch did not report a write to the clip static (the field"
                                    + " only ever held the stand-in AudioQuiet parked there)",
                            sts1solver.mirror.StaticWatch.writtenForTest().toString());

                    // ---- Window B: a release is restored (overturns B169) -------------------
                    int putBack1 = sts1solver.mirror.AudioQuiet.putBackForTest();
                    int released1 = sts1solver.mirror.AudioQuiet.releasedForTest();
                    World b = World.captureLive();
                    b.install();
                    Probe.check(sts1solver.mirror.SandboxClip.isSandbox(S255_LIVE),
                            "the second window parks the stand-in again",
                            String.valueOf(S255_LIVE));
                    // The mod's LineListener clears the field on the audio thread: exactly what B169
                    // used to leave released.
                    S255_LIVE = null;
                    b.uninstall();
                    Probe.check(S255_LIVE == liveClip,
                            "a reference the window released is put back (B187 overturns B169)",
                            String.valueOf(S255_LIVE));
                    Probe.check(sts1solver.mirror.AudioQuiet.releasedForTest() - released1 == 1,
                            "the window counted exactly one release",
                            String.valueOf(
                                    sts1solver.mirror.AudioQuiet.releasedForTest() - released1));
                    Probe.check(sts1solver.mirror.AudioQuiet.putBackForTest() - putBack1 >= 1,
                            "a release is restored, not dropped",
                            String.valueOf(
                                    sts1solver.mirror.AudioQuiet.putBackForTest() - putBack1));

                    // ---- Window C: a live clip that really died is not put back -------------
                    int dead1 = sts1solver.mirror.AudioQuiet.closedSnapshotForTest();
                    S255Clip dying = new S255Clip("dying");
                    dying.running = true;
                    S255_LIVE = S255Clip.proxy(dying);
                    World c = World.captureLive();
                    c.install();
                    Probe.check(sts1solver.mirror.SandboxClip.isSandbox(S255_LIVE),
                            "the third window parks the stand-in", String.valueOf(S255_LIVE));
                    // The player quit the track on another thread: the line behind the snapshot is
                    // gone. Writing it back is what crashed the JVM (B187).
                    dying.closed = true;
                    dying.running = false;
                    c.uninstall();
                    Probe.check(S255_LIVE == null,
                            "a live clip that died while the window was open is not put back (B187)",
                            String.valueOf(S255_LIVE));
                    Probe.check(sts1solver.mirror.AudioQuiet.closedSnapshotForTest() - dead1 == 1,
                            "the dead live reference is counted and reported",
                            String.valueOf(sts1solver.mirror.AudioQuiet.closedSnapshotForTest()
                                    - dead1));

                    // ---- Window D: a stop() the stand-in cannot intercept is reported ------
                    int stops1 = sts1solver.mirror.AudioQuiet.liveStopsForTest();
                    S255Clip stopped = new S255Clip("stopped");
                    stopped.running = true;
                    javax.sound.sampled.Clip stoppedClip = S255Clip.proxy(stopped);
                    S255_LIVE = stoppedClip;
                    World d = World.captureLive();
                    d.install();
                    // A field the window rewrites to the live clip itself (a final field would look
                    // the same): the stand-in is no longer in the way, so the stop must be reported.
                    S255_LIVE = stoppedClip;
                    stoppedClip.stop();
                    d.uninstall();
                    Probe.check(sts1solver.mirror.AudioQuiet.liveStopsForTest() - stops1 == 1,
                            "a sandbox stop() of the LIVE clip is detected and reported",
                            "liveStops=" + (sts1solver.mirror.AudioQuiet.liveStopsForTest()
                                    - stops1));
                    Probe.check(S255_LIVE == stoppedClip,
                            "the stopped live clip is still the field's value",
                            String.valueOf(S255_LIVE));

                    // ---- Window E: a stand-in left by a window that never ended ------------
                    int stale1 = sts1solver.mirror.AudioQuiet.staleForTest();
                    S255_SANDBOX = sts1solver.mirror.SandboxClip.shared();
                    World e = World.captureLive();
                    e.install();
                    Probe.check(sts1solver.mirror.AudioQuiet.staleForTest() - stale1 == 1,
                            "a stand-in left by a window that never ended is reported as stale",
                            String.valueOf(
                                    sts1solver.mirror.AudioQuiet.staleForTest() - stale1));
                    e.uninstall();
                    Probe.check(S255_SANDBOX == null,
                            "a stale stand-in is cleared instead of looped into the live game",
                            String.valueOf(S255_SANDBOX));

                    // The gate is about the REAL leak: when YuAi is loaded, its field must be found.
                    boolean hasYuai = false;
                    try {
                        Class.forName("yuaimod.YuAiMusic", false, Probe.class.getClassLoader());
                        hasYuai = true;
                    } catch (Throwable ignored) {
                        // that mod is not installed in this run
                    }
                    java.util.List<String> watched = sts1solver.mirror.AudioQuiet.watchedForTest();
                    Log.info("  S255 watched=" + watched + " yuaiInstalled=" + hasYuai);
                    Probe.check(!hasYuai || watched.contains("yuaimod.YuAiMusic#currentClip"),
                            "the mod static that actually leaked is watched when that mod is loaded",
                            watched.toString());
                    Probe.check(watched.contains("sts1solver.probe.Probe#S255_LIVE"),
                            "the gate's own clip static is watched", watched.toString());
                    // A discovered field that reflection cannot open guards NOTHING. The real YuAi
                    // field is private static, so this is the assertion that would have caught the
                    // first version (it logged IllegalAccessException and protected nothing).
                    Probe.check(!hasYuai || sts1solver.mirror.AudioQuiet.readableForTest(
                                    "yuaimod.YuAiMusic#currentClip"),
                            "the mod static that actually leaked is actually readable",
                            sts1solver.mirror.AudioQuiet.blindForTest().toString());
                    Probe.check(sts1solver.mirror.AudioQuiet.blindForTest().isEmpty(),
                            "no watched clip static is left locked",
                            sts1solver.mirror.AudioQuiet.blindForTest().toString());
                } catch (Throwable t) {
                    Probe.check(false, "S255 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                    S255_LIVE = null;
                    S255_SANDBOX = null;
                    sts1solver.mirror.StaticWatch.resetForTest();
                    sts1solver.mirror.AudioQuiet.resetForTest();
                }
            }
        });

        // B187 + rule I1: the proxy gate above cannot prove that a REAL DirectAudioDevice line
        // survives the same open/loop/stop/close sequence -- a fake Clip was exactly what stayed
        // green while the game crashed (S255 v1). This one touches the real mixer. With no usable
        // output device (headless/muted host) it logs SKIP and counts NOTHING: a skip is not a pass.
        Probe.core("S257 a real javax.sound clip survives open/loop/stop/close (B187 device smoke)",
                new Runnable(){
            @Override
            public void run() {
                javax.sound.sampled.Clip clip = null;
                try {
                    javax.sound.sampled.AudioFormat fmt =
                            new javax.sound.sampled.AudioFormat(8000.0f, 8, 1, false, false);
                    javax.sound.sampled.DataLine.Info info =
                            new javax.sound.sampled.DataLine.Info(
                                    javax.sound.sampled.Clip.class, fmt);
                    clip = (javax.sound.sampled.Clip)
                            javax.sound.sampled.AudioSystem.getLine(info);
                    byte[] silence = new byte[400];
                    clip.open(fmt, silence, 0, silence.length);
                    clip.loop(1);
                    clip.stop();
                    Probe.check(clip.isOpen(),
                            "S257 the real clip is open after open/loop/stop",
                            "open=" + clip.isOpen());
                    clip.close();
                    Probe.check(!clip.isOpen(),
                            "S257 the real clip closes cleanly on a real device",
                            "open=" + clip.isOpen());
                } catch (Throwable t) {
                    Log.warn("S257 SKIP: no usable javax.sound output device (" + t + "); the"
                            + " native DirectAudioDevice layer is NOT covered by this run (rule I1)");
                } finally {
                    if (clip != null) {
                        try {
                            clip.close();
                        } catch (Throwable ignored) {
                            // already closed or never opened
                        }
                    }
                }
            }
        });

        // B171 (user m20878): the boss quick path must keep searching while the budget lasts. It used
        // to run beam=10 once and stop the moment that pass held ANY win -- even with an unlimited
        // budget, and even though beam=10 had already parked most of the frontier. The player saw
        // 「最好路线 -33」on a fight where a 24-damage line existed one beam wider.
        Probe.core("S230 an unlimited budget keeps widening after the first win (B171)", new Runnable(){
            @Override
            public void run() {
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 5230L;
                    // A Gremlin Nob cannot be beaten by this deck without taking damage, so the narrow
                    // pass finds a win that is NOT provably free -- exactly the case where the old code
                    // stopped after one pass.
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Strike_R", "Strike_R", "Strike_R", "Strike_R",
                            "Defend_R", "Defend_R", "Defend_R", "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.GremlinNob"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                    World root = World.captureLive();
                    sts1solver.search.QuickSession quick = new sts1solver.search.QuickSession(
                            root, sts1solver.ui.DeepBudget.UNLIMITED, true);
                    // B173 note (2026-11-10): this used to be 300 s. On a loaded machine (the same box
                    // that reported ~700 worldlines/s instead of ~1300) the pass needs ~400 s for the
                    // SAME node counts (narrow 35863, wide 71726 each), so the deadline is a safety net,
                    // not the criterion -- finished + passes>=2 + win below are.
                    long deadline = System.currentTimeMillis() + 900000L;
                    while (!quick.finished() && System.currentTimeMillis() < deadline) {
                        quick.advance(20L);
                    }
                    Solver.Result r = quick.result();
                    Log.info("  S230 quick: finished=" + quick.finished() + " passes=" + quick.passes()
                            + " win=" + (r != null && r.win) + " hpLoss=" + (r == null ? -1 : r.hpLoss)
                            + " proven=" + (r != null && r.provenOptimal) + " nodes=" + quick.nodes());
                    Probe.check(quick.finished() && r != null && r.win,
                            "the widened search still finds a winning line",
                            "finished=" + quick.finished() + " result="
                                    + (r == null ? "null" : r.reason));
                    Probe.check(quick.passes() >= 2,
                            "a win from the narrow pass does not end the job while budget remains",
                            "passes=" + quick.passes());
                    Solver.Session narrowOnly = new Solver.Session(
                            root, 10, sts1solver.search.Limits.layers(), 120000L, 0, 0);
                    long deadline2 = System.currentTimeMillis() + 120000L;
                    while (!narrowOnly.finished() && System.currentTimeMillis() < deadline2) {
                        narrowOnly.advance(20L);
                    }
                    Solver.Result n = narrowOnly.result();
                    Log.info("  S230 narrow only: win=" + (n != null && n.win) + " hpLoss="
                            + (n == null ? -1 : n.hpLoss) + " nodes=" + narrowOnly.nodes());
                    Probe.check(r != null && n != null && r.hpLoss <= n.hpLoss,
                            "the widened answer is never worse than the narrow pass alone",
                            "quick=" + (r == null ? -1 : r.hpLoss)
                                    + " narrow=" + (n == null ? -1 : n.hpLoss));
                } catch (Throwable t) {
                    Probe.check(false, "S230 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                }
            }
        });
