        Probe.core("S238 what one Artifact is worth against the gremlin gang (B174)", new Runnable(){
            @Override
            public void run() {
                // B174 diagnostic, not a fix: the same six end-turns with and without an Ancient Potion,
                // printing hp/blk/powers per turn, so the 9 HP the search pays can be compared with what
                // the model thinks one Artifact buys.
                try {
                    int[] hp = new int[2 * 8];
                    int[] weak = new int[2 * 8];
                    for (int withPotion = 0; withPotion < 2; ++withPotion) {
                        Synthetic.Spec spec = new Synthetic.Spec();
                        spec.seed = 9238L;
                        spec.maxHealth = 320;
                        spec.ascension = 20;
                        spec.deck = new String[]{"Defend_R", "Defend_R", "Defend_R", "Defend_R", "Defend_R"};
                        spec.monsters = new String[]{
                                "com.megacrit.cardcrawl.monsters.exordium.GremlinThief",
                                "com.megacrit.cardcrawl.monsters.exordium.GremlinFat",
                                "com.megacrit.cardcrawl.monsters.exordium.GremlinWizard",
                                "com.megacrit.cardcrawl.monsters.exordium.GremlinFat"};
                        Synthetic.build(spec, new Synthetic.SyntheticStep());
                        AbstractDungeon.player.currentHealth = 320;
                        AbstractDungeon.player.potions.set(0,
                                com.megacrit.cardcrawl.helpers.PotionHelper.getPotion("Ancient Potion"));
                        World w = World.captureLive();
                        w.install();
                        Driver.begin();
                        try {
                            if (withPotion == 1) {
                                Driver.usePotion(0, -1);
                            }
                            StringBuilder sb = new StringBuilder();
                            sb.append("  S238 ").append(withPotion == 1 ? "potion" : "plain").append(":");
                            for (int t = 0; t < 8; ++t) {
                                sb.append(" |t").append(t + 1).append(" in=")
                                        .append(AbstractDungeon.player.currentHealth).append(" ")
                                        .append(powerText()).append(" art=")
                                        .append(artifactAmount());
                                Driver.endTurn();
                                hp[withPotion * 8 + t] = AbstractDungeon.player.currentHealth;
                                com.megacrit.cardcrawl.powers.AbstractPower wk =
                                        AbstractDungeon.player.getPower("Weakened");
                                weak[withPotion * 8 + t] = wk == null ? 0 : wk.amount;
                                sb.append(" out=")
                                        .append(AbstractDungeon.player.currentHealth).append(" ")
                                        .append(powerText()).append(" art=")
                                        .append(artifactAmount());
                            }
                            Log.info(sb.toString());
                        } finally {
                            Driver.end();
                            w.trimPresentation();
                            w.readBack();
                            w.uninstall();
                        }
                    }
                    // What one Artifact buys against the gremlin gang: one layer of Weak less for the
                    // rest of the fight, and (with nothing blocking) not one HP. That is the number the
                    // 9 HP price has to be compared with.
                    boolean sameHp = true;
                    boolean oneBehind = true;
                    for (int t = 1; t < 8; ++t) {
                        if (hp[t] != hp[8 + t]) {
                            sameHp = false;
                        }
                        if (weak[t] != weak[8 + t] + 1) {
                            oneBehind = false;
                        }
                    }
                    Probe.check(sameHp, "an Artifact does not change HP when nothing blocks",
                            "plain=" + hp[1] + "," + hp[2] + " potion=" + hp[9] + "," + hp[10]);
                    Probe.check(oneBehind, "an Artifact leaves the player one layer of Weak behind",
                            "plain=" + weak[1] + "," + weak[2] + " potion=" + weak[9] + "," + weak[10]);
                } catch (Throwable t) {
                    Probe.check(false, "S238 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                }
            }
        });
