        // B177 wiring pin: S244 proves Session.planWidening() works, but not that the quick search
        // actually calls it. This gate drives the real QuickSession, so commenting the planWidening()
        // call out turns it red (session stays on rung 0).
        Probe.core("S245 the quick search itself uses the widening ladder (B177)",
                new Runnable(){
            @Override
            public void run() {
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9246L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Defend_R", "Defend_R", "Defend_R", "Defend_R",
                            "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                    World root = World.captureLive();
                    sts1solver.search.QuickSession quick =
                            new sts1solver.search.QuickSession(root, 12000L, true);
                    long deadline = System.currentTimeMillis() + 120000L;
                    while (!quick.finished() && System.currentTimeMillis() < deadline) {
                        quick.advance(20L);
                    }
                    Log.info("  S245 finished=" + quick.finished() + " passes=" + quick.passes()
                            + " rungs=" + quick.rungsForTest() + " rung=" + quick.rungForTest()
                            + " nodes=" + quick.nodes());
                    Probe.check(quick.finished(), "the quick search ran to the end",
                            "finished=" + quick.finished());
                    Probe.check(quick.rungsForTest() > 1,
                            "the quick search gave its session a widening ladder",
                            "rungs=" + quick.rungsForTest());
                    Probe.check(quick.rungForTest() >= 1,
                            "and the ladder actually advanced past the narrow rung",
                            "rung=" + quick.rungForTest() + " passes=" + quick.passes());
                } catch (Throwable t) {
                    Probe.check(false, "S245 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                }
            }
        });

