        // B180 (user m24185, option A): with the time budget set to "unlimited" the LAST widening
        // rung must not carry a node cap. The log showed four rungs each spending 25,514 nodes and
        // finishing with 169 positions open while the panel said the player had set no limit -- that
        // 169 was a per-rung node budget, not the fight's complexity. A finite budget keeps the cap
        // (S246 relies on it). The pin only reads the cap each rung arms; it does not run the
        // uncapped rung to completion.
        Probe.core("S247 an unlimited job gives its last rung no node cap (B180)", new Runnable(){
            @Override
            public void run() {
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9248L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Defend_R", "Defend_R", "Defend_R", "Defend_R",
                            "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                    World root = World.captureLive();

                    Solver.Session open =
                            new Solver.Session(root, 10, 6, sts1solver.ui.DeepBudget.UNLIMITED, 0, 0);
                    open.planWidening(new int[]{20, 40});
                    long deadline = System.currentTimeMillis() + 120000L;
                    while (!open.finished() && open.rung() < 2
                            && System.currentTimeMillis() < deadline) {
                        open.advance(20L);
                    }
                    int openCap = open.maxNodesForTest();
                    int openRung = open.rung();
                    open.requestStop();
                    open.advance(20L);

                    Solver.Session finite = new Solver.Session(root, 10, 6, 12000L, 0, 0);
                    finite.planWidening(new int[]{20, 40});
                    deadline = System.currentTimeMillis() + 120000L;
                    while (!finite.finished() && finite.rung() < 2
                            && System.currentTimeMillis() < deadline) {
                        finite.advance(20L);
                    }
                    int finiteCap = finite.maxNodesForTest();
                    int finiteRung = finite.rung();
                    finite.requestStop();
                    finite.advance(20L);
                    Log.info("  S247 unlimitedCap=" + openCap + " rung=" + openRung
                            + " finiteCap=" + finiteCap + " finiteRung=" + finiteRung);
                    Probe.check(openRung >= 2, "the unlimited ladder reached its last rung",
                            "rung=" + openRung);
                    Probe.check(openCap == 0, "the last rung of an unlimited job carries no node cap",
                            "cap=" + openCap);
                    Probe.check(finiteCap > 0, "a finite budget keeps the per-rung node cap",
                            "cap=" + finiteCap);
                } catch (Throwable t) {
                    Probe.check(false, "S247 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                }
            }
        });

