        // B181 (user m24423/m24488): the sandbox used to hand the engine a 20 s frame between steps.
        // An action that changes state in a LATER time window than the one its first update enters
        // therefore never got that second window: Hexaghost's Inferno queues one BurnIncreaseAction
        // whose first update (duration == 3.0) upgrades the burns already in the piles and whose later
        // update (duration < 1.5) creates three new ones. With a single 20 s tick the duration jumped
        // 3.0 -> -17, the action marked itself done, and the fight went on three burns short -- the
        // turn 10 hand the panel predicted was not the hand the game dealt (solver.log 22:11:37).
        Probe.core("S249 a staged action gets its later time window too (B181)", new Runnable(){
            @Override
            public void run() {
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9249L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Defend_R"};
                    spec.monsters = new String[]{
                            "com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    World w = World.captureLive();
                    w.install();
                    Driver.begin();
                    try {
                        com.megacrit.cardcrawl.characters.AbstractPlayer p =
                                com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                        p.discardPile.clear();
                        p.drawPile.clear();
                        com.megacrit.cardcrawl.cards.status.Burn first =
                                new com.megacrit.cardcrawl.cards.status.Burn();
                        com.megacrit.cardcrawl.cards.status.Burn second =
                                new com.megacrit.cardcrawl.cards.status.Burn();
                        com.megacrit.cardcrawl.cards.status.Burn third =
                                new com.megacrit.cardcrawl.cards.status.Burn();
                        p.discardPile.addToTop(first);
                        p.discardPile.addToTop(second);
                        p.drawPile.addToTop(third);
                        int before = Probe.burnCount(p);
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.actionManager.addToBottom(
                                new com.megacrit.cardcrawl.actions.unique.BurnIncreaseAction());
                        Driver.Drain d = Driver.drain(4000, 800L);
                        int after = Probe.burnCount(p);
                        int upgradedOriginals = (first.upgraded ? 1 : 0)
                                + (second.upgraded ? 1 : 0) + (third.upgraded ? 1 : 0);
                        Log.info("  S249 burns=" + before + "->" + after
                                + " upgradedOriginals=" + upgradedOriginals
                                + " timedOut=" + d.timedOut);
                        Probe.check(before == 3,
                                "the gate starts from three plain burns", "before=" + before);
                        Probe.check(upgradedOriginals == 3,
                                "the first time window upgrades every burn already in the piles",
                                "upgradedOriginals=" + upgradedOriginals);
                        Probe.check(after == before + 3,
                                "the later time window still adds its three new burns",
                                "after=" + after + " before=" + before);
                    } finally {
                        Driver.end();
                        w.readBack();
                        w.uninstall();
                    }
                } catch (Throwable t) {
                    Probe.check(false, "S249 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                }
            }
        });

        // B182 (user m00001/m00148): the glow ring on a hand card is live-session presentation, and
        // the sandbox has no use for a copy of it. CardGlowBorder objects are AbstractGameEffects,
        // which ClonePolicy shares by reference, so the sandbox's glowList pointed at the LIVE rings
        // and AbstractCard.stopGlowing() (:1140) divided their duration by 5 during a search
        // (1.2 s -> 0.24 s -> gone). The sandbox never renders them (updateGlow only runs from
        // renderCard/renderInLibrary), so install() empties the sandbox's queues instead.
        Probe.core("S250 a simulated stopGlowing leaves the live glow ring alone (B182)", new Runnable(){
            @Override
            public void run() {
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9250L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Defend_R"};
                    spec.monsters = new String[]{
                            "com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    AbstractCard liveCard = new Strike_Red();
                    AbstractDungeon.player.hand.clear();
                    AbstractDungeon.player.hand.addToTop(liveCard);
                    Field glow = Reflect.find(AbstractCard.class, "glowList");
                    List<Object> liveList = (List<Object>) Reflect.get(glow, liveCard);
                    com.megacrit.cardcrawl.vfx.cardManip.CardGlowBorder border =
                            new com.megacrit.cardcrawl.vfx.cardManip.CardGlowBorder(
                                    liveCard, liveCard.glowColor);
                    liveList.add(border);
                    float before = ((com.megacrit.cardcrawl.vfx.AbstractGameEffect) border).duration;
                    World w = World.captureLive();
                    w.install();
                    int dropped = sts1solver.mirror.GlowReset.dropped();
                    int scanned = sts1solver.mirror.GlowReset.scanned();
                    boolean liveSame;
                    boolean liveHasBorder;
                    boolean sameCard;
                    float after;
                    int sandboxSize;
                    try {
                        AbstractCard sandboxCard = AbstractDungeon.player.hand.group.get(0);
                        sameCard = sandboxCard != liveCard
                                && "Strike_R".equals(sandboxCard.cardID);
                        sandboxSize = ((List<?>) Reflect.get(glow, sandboxCard)).size();
                        // What a search runs on every draw and every energy gain.
                        sandboxCard.stopGlowing();
                        AbstractDungeon.player.hand.glowCheck();
                        after = ((com.megacrit.cardcrawl.vfx.AbstractGameEffect) border).duration;
                        liveSame = Reflect.get(glow, liveCard) == liveList;
                        liveHasBorder = liveList.size() == 1 && liveList.get(0) == border;
                    } finally {
                        w.readBack();
                        w.uninstall();
                    }
                    boolean liveAfter = Reflect.get(glow, liveCard) == liveList
                            && liveList.size() == 1 && liveList.get(0) == border;
                    Log.info("  S250 glow before=" + before + " after=" + after
                            + " liveSize=" + liveList.size() + " sandboxSize=" + sandboxSize
                            + " scanned=" + scanned + " dropped=" + dropped
                            + " sameCard=" + sameCard + " liveSame=" + liveSame
                            + " liveAfter=" + liveAfter);
                    Probe.check(Math.abs(before - 1.2f) < 1e-4f,
                            "the gate starts from a full-length ring", "before=" + before);
                    Probe.check(dropped > 0 && sandboxSize == 0 && sameCard,
                            "the sandbox copy carried the ring and install dropped it there",
                            "dropped=" + dropped + " sandboxSize=" + sandboxSize
                                    + " sameCard=" + sameCard);
                    Probe.check(Math.abs(after - before) < 1e-6f,
                            "a simulated stopGlowing does not shorten the live ring",
                            "before=" + before + " after=" + after
                                    + " (the old code gave " + (before / 5.0f) + ")");
                    Probe.check(liveSame && liveHasBorder && liveAfter,
                            "the live queue is still the same object holding the same ring",
                            "liveSame=" + liveSame + " liveHasBorder=" + liveHasBorder
                                    + " liveAfter=" + liveAfter);
                } catch (Throwable t) {
                    Probe.check(false, "S250 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                }
            }
        });

