        // B184: the screen rule stays FIRST. A frame that opens a card picker has to hand the picker
        // the game's own 1/60 s, so with "a screen is up" forced on, the plan must lose and the step
        // must cost the full sixty frames -- the ordering that keeps B83/B84 (the picker's action
        // marking itself done before the answer exists) fixed while the tiering is on.
        Probe.core("S253 a screen-up frame overrides the plan (B184)", new Runnable(){
            @Override
            public void run() {
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9253L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    spec.deck = new String[]{"Strike_R", "Defend_R"};
                    spec.monsters = new String[]{
                            "com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    FramePlan.setEnabledForTest(Boolean.TRUE);
                    FramePlan.resetCounters();
                    Driver.resetScreenFrames();
                    World w = World.captureLive();
                    w.install();
                    Driver.begin();
                    try {
                        com.megacrit.cardcrawl.characters.AbstractPlayer p =
                                com.megacrit.cardcrawl.dungeons.AbstractDungeon.player;
                        p.discardPile.clear();
                        p.drawPile.clear();
                        com.megacrit.cardcrawl.cards.status.Burn first =
                                new com.megacrit.cardcrawl.cards.status.Burn();
                        com.megacrit.cardcrawl.cards.status.Burn second =
                                new com.megacrit.cardcrawl.cards.status.Burn();
                        com.megacrit.cardcrawl.cards.status.Burn third =
                                new com.megacrit.cardcrawl.cards.status.Burn();
                        p.discardPile.addToTop(first);
                        p.discardPile.addToTop(second);
                        p.drawPile.addToTop(third);
                        int before = Probe.burnCount(p);
                        Driver.setScreenDeltaForTest(Boolean.TRUE);
                        com.megacrit.cardcrawl.dungeons.AbstractDungeon.actionManager.addToBottom(
                                new com.megacrit.cardcrawl.actions.unique.BurnIncreaseAction());
                        Driver.Drain d = Driver.drain(4000, 800L);
                        Driver.setScreenDeltaForTest(null);
                        int after = Probe.burnCount(p);
                        long screenFrames = Driver.screenFrames();
                        long fast = FramePlan.fastFrames();
                        Log.info("  S253 burns=" + before + "->" + after + " steps=" + d.steps
                                + " screenFrames=" + screenFrames + " fast=" + fast
                                + " settled=" + d.settled + " stalled=" + d.stalled
                                + " timedOut=" + d.timedOut + " awaitingSelection="
                                + d.awaitingSelection);
                        Probe.check(screenFrames >= 40,
                                "every frame of the step was the screen frame, not the plan",
                                "screenFrames=" + screenFrames + " steps=" + d.steps);
                        // The plan did offer a jump on this action (it is on the whitelist and the
                        // duration is past its 1.5 s window) -- so the only reason the action is
                        // still short of that window is that the screen rule answered first.
                        Probe.check(fast >= 1,
                                "the plan had a fast frame ready for this action",
                                "fast=" + fast);
                        Probe.check(after == before,
                                "the screen frame won: the 1.5 s window was never reached",
                                "after=" + after + " before=" + before
                                        + " (a planned jump would have created three burns)");
                    } finally {
                        Driver.setScreenDeltaForTest(null);
                        FramePlan.setEnabledForTest(null);
                        Driver.end();
                        w.readBack();
                        w.uninstall();
                    }
                } catch (Throwable t) {
                    Driver.setScreenDeltaForTest(null);
                    FramePlan.setEnabledForTest(null);
                    Probe.check(false, "S253 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                }
            }
        });

        // B177 (user m23168, option C): the widening ladder must run inside ONE session. Each wider
        // rung used to be built from the same root, so the layers the narrow rung had already run were
        // expanded again -- the wasted work the user reported. Widening now keeps the frontier/layer
        // and brings the parked lines back instead of re-deriving them.
        // 1.0.0 feedback: the panel's 导出报告 button has to produce a bundle that is small, complete
        // and free of the player's Windows account name -- a bundle that leaks a home path cannot be
        // attached to a public issue, which is the only reason the button exists.
        Probe.core("S254 the report bundle packs what an issue needs and names no user", new Runnable() {
            @Override
            public void run() {
                java.io.File tmp = new java.io.File(System.getProperty("java.io.tmpdir"),
                        "sts1-report-gate-" + System.nanoTime());
                java.io.File reports = new java.io.File(tmp, "reports");
                java.io.File zip = null;
                try {
                    if (!tmp.mkdirs() && !tmp.isDirectory()) {
                        Probe.check(false, "S254 temp dir", tmp.getPath());
                        return;
                    }
                    java.io.File settings = new java.io.File(tmp, "settings.txt");
                    java.io.FileOutputStream sfo = new java.io.FileOutputStream(settings);
                    sfo.write("autoplayDelayMs=750\n".getBytes("UTF-8"));
                    sfo.close();
                    zip = sts1solver.diag.BugReport.writeBundle(reports);
                    java.util.Map<String, String> entries = new java.util.LinkedHashMap<String, String>();
                    java.util.zip.ZipFile zf = new java.util.zip.ZipFile(zip);
                    try {
                        java.util.Enumeration<? extends java.util.zip.ZipEntry> en = zf.entries();
                        while (en.hasMoreElements()) {
                            java.util.zip.ZipEntry e = en.nextElement();
                            java.io.InputStream in = zf.getInputStream(e);
                            java.io.ByteArrayOutputStream bo = new java.io.ByteArrayOutputStream();
                            byte[] buf = new byte[4096];
                            int n;
                            while ((n = in.read(buf)) > 0) {
                                bo.write(buf, 0, n);
                            }
                            in.close();
                            entries.put(e.getName(), new String(bo.toByteArray(), "UTF-8"));
                        }
                    } finally {
                        zf.close();
                    }
                    Log.info("  S254 zip=" + zip.length() + " entries=" + entries.keySet());
                    Probe.check(entries.containsKey("info.txt") && entries.containsKey("state.txt")
                                    && entries.containsKey("README.txt")
                                    && entries.containsKey("settings.txt")
                                    && entries.containsKey("panel.txt")
                                    && entries.containsKey("solver.log"),
                            "S254 the bundle carries info, state, settings, panel and the log",
                            String.valueOf(entries.keySet()));
                    Probe.check(zip.length() < sts1solver.diag.BugReport.BUNDLE_LIMIT_BYTES,
                            "S254 the bundle stays under the attach limit",
                            zip.length() + " bytes");
                    String home = System.getProperty("user.home", "");
                    boolean leaked = false;
                    for (String text : entries.values()) {
                        if (home.length() > 2 && text.contains(home)) {
                            leaked = true;
                        }
                    }
                    Probe.check(!leaked, "S254 no entry carries the absolute home path", "leaked=" + leaked);
                    Probe.check(entries.get("info.txt").contains("%USERPROFILE%"),
                            "S254 the home path is replaced, not dropped silently",
                            entries.get("info.txt"));
                    Probe.check(entries.get("settings.txt").contains("autoplayDelayMs"),
                            "S254 the settings file is copied, not stubbed",
                            entries.get("settings.txt"));
                    Probe.check(entries.get("info.txt").contains("mod version: 1."),
                            "S254 the bundle names OUR version, not another mod's manifest",
                            entries.get("info.txt"));
                } catch (Throwable t) {
                    Probe.check(false, "S254 ran without throwing", String.valueOf(t));
                } finally {
                    try {
                        if (zip != null) {
                            zip.delete();
                        }
                        java.io.File[] kids = tmp.listFiles();
                        if (kids != null) {
                            for (java.io.File k : kids) {
                                if (k.isDirectory()) {
                                    java.io.File[] inner = k.listFiles();
                                    if (inner != null) {
                                        for (java.io.File i : inner) {
                                            i.delete();
                                        }
                                    }
                                }
                                k.delete();
                            }
                        }
                        tmp.delete();
                    } catch (Throwable ignored) {
                    }
                }
            }
        });

        Probe.core("S244 a widening rung continues the same session instead of restarting (B177)",
                new Runnable(){
            @Override
            public void run() {
                try {
                    Synthetic.Spec spec = new Synthetic.Spec();
                    spec.seed = 9245L;
                    spec.maxHealth = 80;
                    spec.ascension = 0;
                    // No damage: the narrow rung cannot prove a win, so it runs out of frontier
                    // instead of finishing early -- that is the point where the ladder must widen.
                    spec.deck = new String[]{"Defend_R", "Defend_R", "Defend_R", "Defend_R",
                            "Defend_R"};
                    spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                    Synthetic.build(spec, new Synthetic.SyntheticStep());
                    Driver.drain(4000, 800L);
                    World root = World.captureLive();
                    sts1solver.search.Solver.Session held =
                            new sts1solver.search.Solver.Session(root, 10,
                                    sts1solver.search.Limits.layers(), 12000L, 0, 0);
                    held.planWidening(new int[]{20, 40});
                    long deadline = System.currentTimeMillis() + 120000L;
                    while (!held.finished() && System.currentTimeMillis() < deadline) {
                        held.advance(20L);
                    }
                    Log.info("  S244 finished=" + held.finished() + " rungs=" + held.rungs()
                            + " rung=" + held.rung() + " beam=" + held.beamWidth()
                            + " widenedAt=" + held.widenedAtLayerForTest()
                            + " expansions=" + held.expansions()
                            + " atWiden=" + held.expansionsAtWidenForTest()
                            + " promoted=" + held.promotedForTest()
                            + " parked=" + held.deferredCountForTest()
                            + " reason=" + (held.finished() ? held.result().reason : "-"));
                    Probe.check(held.finished() && held.rung() >= 1,
                            "a ladder wider than the first rung actually widens",
                            "finished=" + held.finished() + " rung=" + held.rung());
                    Probe.check(held.rung() == 2 && held.beamWidth() == 40,
                            "both widening rungs ran, in order, inside this one session",
                            "rung=" + held.rung() + " beam=" + held.beamWidth());
                    Probe.check(held.widenedAtLayerForTest() >= 1,
                            "the first widening happens below the root, not by restarting from it",
                            "widenedAt=" + held.widenedAtLayerForTest());
                    Probe.check(held.expansionsAtWidenForTest() > 0,
                            "the narrow rung had expanded boards before the wider rung began",
                            "atWiden=" + held.expansionsAtWidenForTest());
                    Probe.check(held.promotedForTest() > 0,
                            "the wider rungs picked up lines the narrow beam had parked",
                            "promoted=" + held.promotedForTest()
                                    + " parked=" + held.deferredCountForTest());
                } catch (Throwable t) {
                    Probe.check(false, "S244 ran without throwing", String.valueOf(t));
                } finally {
                    if (World.anyInstalled()) {
                        World.forceRestore();
                    }
                }
            }
        });

