                Probe.check(sts1solver.search.StrategicDeficit.compare(true, 5, 3, false, 0, 1) < 0,
                        "a win beats a lower deficit", "");
                Probe.check(sts1solver.search.StrategicDeficit.compare(true, 5, 6, true, 7, 3) < 0,
                        "among wins the lower deficit wins", "");
                Probe.check(sts1solver.search.StrategicDeficit.compare(true, 5, 6, true, 5, 3) > 0,
                        "equal deficit prefers the quicker win", "");
