        Probe.step("S30 worker protocol: a spec-rebuilt worker line is verified by the real engine",
                new Runnable(){
            @Override
            public void run() {
                // 1. instance isolation: a worker process must not share the main process files
                System.setProperty("sts1solver.instance", "t1");
                String reqPath = sts1solver.util.Log.pathFor("autotest.request");
                String logPath = sts1solver.util.Log.pathFor("solver.log");
                Probe.check(reqPath.endsWith("autotest-t1.request")
                        && logPath.endsWith("solver-t1.log"),
                        "a worker instance gets its own request and log paths",
                        reqPath + " / " + logPath);
                System.clearProperty("sts1solver.instance");
                Probe.check(sts1solver.util.Log.pathFor("autotest.request")
                        .endsWith("autotest.request"),
                        "the main process keeps the default paths", "");

                // 2. the worker solves a fight rebuilt from a compact request
                java.io.File dir = new java.io.File(sts1solver.util.Log.dir());
                java.io.File request = new java.io.File(dir, "wtest.request");
                java.io.File result = new java.io.File(dir, "wtest-result.txt");
                try {
                    java.io.PrintWriter w = new java.io.PrintWriter(request, "UTF-8");
                    try {
                        w.println("worker");
                        w.println("seed=911");
                        w.println("class=com.megacrit.cardcrawl.characters.Ironclad");
                        w.println("maxHealth=90");
                        w.println("deck=Strike_R,Strike_R,Strike_R,Defend_R,Bash");
                        w.println("relics=Burning Blood");
                        w.println("monsters=com.megacrit.cardcrawl.monsters.exordium.JawWorm");
                        w.println("budgetMs=4000");
                        w.println("beam=24");
                        w.println("layers=40");
                        w.println("out=wtest-result.txt");
                    } finally {
                        w.close();
                    }
                    java.io.File out = sts1solver.worker.Worker.run(request);
                    Probe.check(out != null && out.isFile(),
                            "the worker writes a result file", String.valueOf(out));
                    java.util.Map<String, String> res =
                            sts1solver.worker.Worker.readResult(result);
                    int steps = Integer.parseInt(res.get("steps"));
                    Log.info("  S30 worker: win=" + res.get("win") + " hpLoss=" + res.get("hpLoss")
                            + " steps=" + steps + " reason=" + res.get("reason"));
                    Probe.check(steps > 0, "the worker returns a playable line",
                            "steps=" + steps);
                    String mismatch = sts1solver.worker.Worker.verify(request, result);
                    Probe.check(mismatch == null,
                            "the real engine reproduces the worker line",
                            String.valueOf(mismatch));
                } catch (Throwable t) {
                    Probe.check(false, "the worker gate ran", String.valueOf(t));
                } finally {
                    request.delete();
                    result.delete();
                    System.clearProperty("sts1solver.instance");
                }
            }
        });

        Probe.step("S48 worker pool: a warm process pulls queued tasks and stops on a stop file",
                new Runnable(){
            @Override
            public void run() {
                java.io.File root = new java.io.File(sts1solver.util.Log.dir(), "pool-s48");
                deleteTree(root);
                root.mkdirs();
                try {
                    sts1solver.worker.WorkerPool.markReady(root, 1234L);
                    java.io.File ready = sts1solver.worker.WorkerPool.readyFile(root);
                    String text = sts1solver.worker.WorkerPool.textOf(ready);
                    Probe.check(ready.isFile() && text.indexOf("warmMs=1234") >= 0
                                    && text.indexOf("pid=") >= 0,
                            "a warm worker announces itself with a ready file",
                            ready.getName() + " " + text.replace('\n', ' '));
                    writePoolRequest(root, "task-0001.request", "pool-r1.txt", 400L);
                    writePoolRequest(root, "task-0002.request", "pool-r2.txt", 400L);
                    java.io.File r1 = sts1solver.worker.WorkerPool.serveOnce(root);
                    java.io.File r2 = sts1solver.worker.WorkerPool.serveOnce(root);
                    Probe.check(r1 != null && "pool-r1.txt".equals(r1.getName())
                                    && r2 != null && "pool-r2.txt".equals(r2.getName()),
                            "queued tasks are served oldest first",
                            String.valueOf(r1) + " / " + r2);
                    java.io.File done = sts1solver.worker.WorkerPool.doneDir(root);
                    java.io.File[] filed = done.listFiles();
                    Probe.check(sts1solver.worker.WorkerPool.queued(root).isEmpty()
                                    && filed != null && filed.length == 2,
                            "finished tasks leave the queue and are filed for inspection",
                            "queued=" + sts1solver.worker.WorkerPool.queued(root).size()
                                    + " done=" + (filed == null ? -1 : filed.length));
                    Probe.check(sts1solver.worker.WorkerPool.serveOnce(root) == null,
                            "an empty queue is not an error (no answer invented)", "");
                    writePoolRequest(root, "task-0003.request", "pool-r3.txt", 200L);
                    java.io.File c1 = sts1solver.worker.WorkerPool.claim(root);
                    java.io.File c2 = sts1solver.worker.WorkerPool.claim(root);
                    Probe.check(c1 != null && c2 == null,
                            "a claimed task is never handed to a second worker", String.valueOf(c1));
                    sts1solver.worker.WorkerPool.archive(root, c1, true);
                    Probe.check(!sts1solver.worker.WorkerPool.stopRequested(root),
                            "a fresh pool is not asked to stop", "");
                    java.io.PrintWriter stop = new java.io.PrintWriter(
                            sts1solver.worker.WorkerPool.stopFile(root), "UTF-8");
                    try {
                        stop.println("stop");
                    } finally {
                        stop.close();
                    }
                    Probe.check(sts1solver.worker.WorkerPool.stopRequested(root),
                            "the stop file ends the pool",
                            sts1solver.worker.WorkerPool.stopFile(root).getName());
                    Log.info("  S48 pool: ready=" + ready.getName() + " warm=1234ms"
                            + " r1=" + (r1 == null ? "-" : r1.length() + "B")
                            + " r2=" + (r2 == null ? "-" : r2.length() + "B")
                            + " filed=2 queued=0");
                } catch (Throwable t) {
                    Probe.check(false, "the pool gate ran", String.valueOf(t));
                } finally {
                    deleteTree(root);
                }
            }
        });

        Probe.step("S29 the deep-search budget is editable in game (settings.txt round trip)",
                new Runnable(){
            @Override
            public void run() {
                java.io.File f = new java.io.File(sts1solver.SolverMod.dir(), "settings.txt");
                byte[] original = null;
                try {
                    if (f.isFile()) {
                        original = java.nio.file.Files.readAllBytes(f.toPath());
                    }
                } catch (Throwable ignored) {
                    // the gate still runs without a backup
                }
                try {
                    sts1solver.ui.Budget.write(45, 77777);
                    Probe.check(sts1solver.ui.Budget.seconds() == 45
                            && sts1solver.ui.Budget.nodes() == 77777,
                            "the budget round-trips through settings.txt", "");
                    java.nio.file.Files.write(f.toPath(),
                            "deepSeconds=45\ncustom=keep-me\n".getBytes("UTF-8"));
                    sts1solver.ui.Budget.write(60, 120000);
                    String text = new String(java.nio.file.Files.readAllBytes(f.toPath()), "UTF-8");
                    Probe.check(text.contains("custom=keep-me") && text.contains("deepSeconds=60")
                            && text.contains("deepNodes=120000"),
                            "other settings keys are preserved", "");
                    sts1solver.ui.Budget.write(60, 120000);
                    Probe.check(sts1solver.ui.Budget.cycleSeconds() == 120,
                            "F5 steps the seconds profile", "");
                    sts1solver.ui.Budget.write(60, 120000);
                    Probe.check(sts1solver.ui.Budget.cycleNodes() == 200000,
                            "Shift+F5 steps the node profile", "");
                    f.delete();
                    sts1solver.ui.Budget.invalidate();
                    Probe.check(sts1solver.ui.Budget.seconds() == 0
                            && sts1solver.ui.Budget.nodes() == 0,
                            "unlimited is the default when no settings file exists",
                            sts1solver.ui.Budget.describe());
                } catch (Throwable t) {
                    Probe.check(false, "the budget gate ran", String.valueOf(t));
                } finally {
                    try {
                        if (original != null) {
                            java.nio.file.Files.write(f.toPath(), original);
                        } else if (f.isFile()) {
                            f.delete();
                        }
                    } catch (Throwable ignored) {
                        // nothing else to restore
                    }
                }
            }
        });

