        Probe.step("S27 potion outlook: replays the game's own reward roll",
                new Runnable(){
            @Override
            public void run() {
                Synthetic.Spec spec = new Synthetic.Spec();
                spec.seed = 901L;
                spec.maxHealth = 90;
                spec.deck = new String[]{"Strike_R", "Strike_R", "Defend_R", "Bash"};
                spec.monsters = new String[]{"com.megacrit.cardcrawl.monsters.exordium.JawWorm"};
                Synthetic.build(spec, new Synthetic.SyntheticStep());
                for (int i = 0; i < AbstractDungeon.player.potions.size(); i++) {
                    AbstractDungeon.player.potions.set(i,
                            new com.megacrit.cardcrawl.potions.FirePotion());
                }
                sts1solver.search.PotionOutlook.reset();
                sts1solver.search.PotionOutlook.capture();
                boolean known = sts1solver.search.PotionOutlook.known();
                boolean drop = sts1solver.search.PotionOutlook.forecastDrop();
                String id = sts1solver.search.PotionOutlook.forecastPotionId();
                Log.info("  S27 outlook: known=" + known + " beltFull="
                        + sts1solver.search.PotionOutlook.beltFull() + " drop=" + drop
                        + " potion=" + id);
                Probe.check(known, "the reward replay runs on a copy of the fight", "");
                Probe.check(sts1solver.search.PotionOutlook.beltFull(),
                        "a full potion belt is detected", "");
                Probe.check(sts1solver.search.PotionOutlook.replacementHpCredit(0) == 0,
                        "no credit when no potion is spent", "");
                int credit = sts1solver.search.PotionOutlook.replacementHpCredit(1);
                Probe.check(drop ? credit == sts1solver.search.PotionOutlook.POTION_HP_CREDIT
                        : credit == 0, "credit only on a confirmed drop", "credit=" + credit);
                // determinism: the same state must roll the same forecast
                sts1solver.search.PotionOutlook.reset();
                sts1solver.search.PotionOutlook.capture();
                Probe.check(sts1solver.search.PotionOutlook.forecastDrop() == drop,
                        "the forecast is deterministic for the same state", "");
                // an open belt slot means the reward lands anyway: no credit
                AbstractDungeon.player.potions.set(0,
                        new com.megacrit.cardcrawl.potions.PotionSlot(0));
                sts1solver.search.PotionOutlook.reset();
                sts1solver.search.PotionOutlook.capture();
                Probe.check(!sts1solver.search.PotionOutlook.beltFull(),
                        "an open slot is detected", "");
                Probe.check(sts1solver.search.PotionOutlook.replacementHpCredit(1) == 0,
                        "an open slot means no credit", "");
            }
        });

