                float[] above = sts1solver.ui.RouteLayout.clipBand(100.0f, 10.0f, 120.0f, 300.0f);
                float[] tall = sts1solver.ui.RouteLayout.clipBand(-100.0f, 900.0f, 0.0f, 300.0f);
