                boolean headline = false;
                for (int i = 0; i < lines.size(); i++) {
                    String line = lines.get(i);
                    boolean verdict = line.indexOf("\u53ef\u8d62") >= 0
                            || line.indexOf("\u672a\u627e\u5230\u80dc\u7ebf") >= 0
                            || line.indexOf("\u6240\u6709\u8def\u7ebf") >= 0
                            || line.indexOf("\u53ea\u80fd\u9003\u8dd1") >= 0;
                    boolean damage = line.indexOf("\u6389\u8840") >= 0 || line.indexOf("\u65e0\u4f24") >= 0;
                    if (verdict && damage) {
                        headline = true;
                    }
                }
                Probe.check(headline, "the panel still states the result and the damage it expects", joined);
                // B33: the end-turn pill belongs to the turn it closes, not to the next row.
                List<sts1solver.ui.RouteRow> route = Gameplay.route();
                int endTurnRows = 0;
                int rowsStartingWithEndTurn = 0;
                int closedTurns = 0;
                for (int r = 0; r < route.size(); r++) {
                    sts1solver.ui.RouteRow row = route.get(r);
                    // Only a row that DOES something may not start with the end-turn pill. A tail
                    // row made purely of end turns is the line's padding (a line that never reaches
                    // a win is padded to the layer limit), so it is not a grouping failure.
                    boolean hasPlay = false;
                    for (int k = 0; k < row.size(); k++) {
                        if (!row.pills.get(k).startsWith("\u7ed3\u675f\u56de\u5408")) {
                            hasPlay = true;
                        }
                    }
                    if (hasPlay) {
                        String firstPill = row.pills.get(0);
                        if (firstPill.startsWith("\u7ed3\u675f\u56de\u5408")) {
                            rowsStartingWithEndTurn++;
                        }
                    }
                    boolean closed = false;
                    for (int k = 0; k < row.size(); k++) {
                        if (row.pills.get(k).startsWith("\u7ed3\u675f\u56de\u5408")) {
                            closed = true;
                            endTurnRows++;
                        }
                    }
                    if (closed) {
                        closedTurns++;
                    }
                }
