            for (int i = 0; i < arrayList.size(); ++i) {
                AbstractMonster abstractMonster = (AbstractMonster)arrayList.get(i);
                Object object = Reflect.get(Reflect.find(AbstractMonster.class, "moveHistory"), abstractMonster);
                stringBuilder.append(i).append(":hist=").append(object instanceof List ? ((List)object).toString() : String.valueOf(object)).append(" cls=").append(abstractMonster.getClass().getSimpleName()).append(" last=").append(abstractMonster.moveHistory == null ? "null" : String.valueOf(abstractMonster.moveHistory.size())).append("; ");
            }
            stringBuilder.append("aiRngCounter=").append(AbstractDungeon.aiRng == null ? "null" : Integer.valueOf(AbstractDungeon.aiRng.counter));
