    private static void leakCheckAround(String string, Runnable runnable) {
        Map<String, String> map = LeakCheck.snapshot();
        runnable.run();
        Map<String, String> map2 = LeakCheck.snapshot();
        List<String> list = LeakCheck.diff(map, map2);
        if (map.size() < 100) {
            Probe.check(false, "leak inventory is present (" + string + ")", LeakCheck.inventoryReport());
            return;
        }
        for (int i = 0; i < list.size() && i < 20; ++i) {
            Log.warn("  LEAK[" + string + "] " + list.get(i));
        }
        Probe.check(list.isEmpty(), "no static field outside the mirror changed (" + string + ")", list.isEmpty() ? LeakCheck.inventoryReport() : list.size() + " fields changed");
    }

