    private static Map<String, Object> identityOfLiveRoots() {
        LinkedHashMap<String, Object> linkedHashMap = new LinkedHashMap<String, Object>();
        try {
            linkedHashMap.put("player", AbstractDungeon.player);
            linkedHashMap.put("actionManager", AbstractDungeon.actionManager);
            linkedHashMap.put("room", AbstractDungeon.getCurrRoom());
            linkedHashMap.put("monsters", AbstractDungeon.getMonsters());
            linkedHashMap.put("overlayMenu", AbstractDungeon.overlayMenu);
            if (AbstractDungeon.overlayMenu != null) {
                linkedHashMap.put("endTurnButton", AbstractDungeon.overlayMenu.endTurnButton);
            }
            linkedHashMap.put("effectList", AbstractDungeon.effectList);
            linkedHashMap.put("effectsQueue", AbstractDungeon.effectsQueue);
            linkedHashMap.put("topLevelEffects", AbstractDungeon.topLevelEffects);
            linkedHashMap.put("topLevelEffectsQueue", AbstractDungeon.topLevelEffectsQueue);
            if (AbstractDungeon.player != null) {
                linkedHashMap.put("hand", AbstractDungeon.player.hand);
                linkedHashMap.put("drawPile", AbstractDungeon.player.drawPile);
                linkedHashMap.put("relics", AbstractDungeon.player.relics);
            }
        }
        catch (Throwable throwable) {
            linkedHashMap.put("error", String.valueOf(throwable));
        }
        return linkedHashMap;
    }

    private static List<String> identityChanged(Map<String, Object> map, Map<String, Object> map2) {
        ArrayList<String> arrayList = new ArrayList<String>();
        for (Map.Entry<String, Object> entry : map.entrySet()) {
            if (!map2.containsKey(entry.getKey())) {
                arrayList.add(entry.getKey() + " vanished");
                continue;
            }
            if (map2.get(entry.getKey()) == entry.getValue()) continue;
            arrayList.add(entry.getKey());
        }
        return arrayList;
    }

    /** Writes a live-mode worker request; the fingerprint is the caller's claim about the state. */
    private static boolean writeWorkerRequest(java.io.File request,
                                             java.util.Map<String, String> liveMap,
                                             String fingerprint, String outName) {
        try {
            java.io.PrintWriter w = new java.io.PrintWriter(request, "UTF-8");
            try {
                w.println("worker");
                w.println("mode=live");
                w.println("fingerprint=" + fingerprint);
                for (java.util.Map.Entry<String, String> e : liveMap.entrySet()) {
                    w.println(e.getKey() + "=" + e.getValue());
                }
                w.println("budgetMs=4000");
                w.println("beam=24");
                w.println("layers=40");
                w.println("out=" + outName);
            } finally {
                w.close();
            }
            return true;
        } catch (Throwable t) {
            Log.warn("  cannot write the worker request: " + t);
            return false;
        }
    }

