    /** B142: does the player's hand hold a card with this id? */
    private static boolean handHas(com.megacrit.cardcrawl.characters.AbstractPlayer p, String cardId) {
        if (p == null || p.hand == null) {
            return false;
        }
        for (int i = 0; i < p.hand.size(); i++) {
            com.megacrit.cardcrawl.cards.AbstractCard c = p.hand.group.get(i);
            if (c != null && cardId.equals(c.cardID)) {
                return true;
            }
        }
        return false;
    }

    /** B142: the hand as a compact id list, for gate messages. */
    private static String handIds(com.megacrit.cardcrawl.characters.AbstractPlayer p) {
        StringBuilder sb = new StringBuilder("hand=[");
        if (p != null && p.hand != null) {
            for (int i = 0; i < p.hand.size(); i++) {
                com.megacrit.cardcrawl.cards.AbstractCard c = p.hand.group.get(i);
                if (i > 0) {
                    sb.append(',');
                }
                sb.append(c == null ? "null" : c.cardID);
            }
        }
        return sb.append(']').toString();
    }

    private static boolean winReached() {
        return Driver.combatOver() && Probe.playerHp() > 0;
    }

    private static void executeWholePlan(Solver.Result result) {
        Driver.begin();
        try {
            int n;
            for (n = 0; n < result.plan.size() && !Driver.combatOver(); ++n) {
                try {
                    Legal.apply(result.plan.get((int)n).action);
                    continue;
                }
                catch (Throwable throwable) {
                    Log.warn("  plan step " + n + " refused by the engine: " + throwable);
                    break;
                }
            }
            n = 0;
            while (!Driver.combatOver() && n++ < 120) {
                Driver.Play play = Probe.chooseAction();
                if (play == null) {
                    break;
                }
                Driver.apply(play);
            }
        }
        finally {
            Driver.end();
        }
    }

    /*
     * WARNING - Removed try catching itself - possible behaviour change.
     */
    private static String potionLabels() {
        StringBuilder stringBuilder = new StringBuilder();
        World world = World.captureLive();
        boolean bl = false;
        try {
            world.install();
            bl = true;
            List<Action> list = Legal.actions();
            for (int i = 0; i < list.size(); ++i) {
                Action action = list.get(i);
                if (!action.isPotion()) continue;
                if (stringBuilder.length() > 0) {
                    stringBuilder.append('|');
                }
                // label is the localised name (m16202-4); append the id so the escape gates below
                // can still tell SmokeBomb apart without relying on the display text.
                stringBuilder.append(action.label).append('(').append(action.cardId).append(')');
            }
        }
        catch (Throwable throwable) {
            stringBuilder.append("error:").append(throwable);
        }
        finally {
            if (bl) {
                try {
                    world.readBack();
                    world.uninstall();
                }
                catch (Throwable throwable) {}
            }
        }
        return stringBuilder.toString();
    }

