    private static float shakeDuration(Object shake) {
        if (shake == null) {
            return -1.0f;
        }
        try {
            java.lang.reflect.Field f = shake.getClass().getDeclaredField("duration");
            f.setAccessible(true);
            return f.getFloat(shake);
        } catch (Throwable t) {
            return -1.0f;
        }
    }

    private static void setShakeDuration(Object shake, float value) {
        if (shake == null) {
            return;
        }
        try {
            java.lang.reflect.Field f = shake.getClass().getDeclaredField("duration");
            f.setAccessible(true);
            f.setFloat(shake, value);
        } catch (Throwable ignored) {
            // a missing field only disables the gate reset
        }
    }

